INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_1_kor_u2_L01_basic#1','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C1',1,'mc','auto','해든이의 말에서 언제인지 알려 주는 말은 어느 것인가요?',ARRAY['K5-1-u2-X01']::text[],false,'{"seq":1,"concept":"K5-1-u2-C1","difficulty":1,"kind":"mc","stem":"해든이의 말에서 언제인지 알려 주는 말은 어느 것인가요?","options":[{"t":"지난 봄에","correct":true},{"t":"강가","mis":"K5-1-u2-X01"},{"t":"산책로에","mis":"K5-1-u2-X01"},{"t":"나는","mis":"K5-1-u2-X01"}],"explanation":["곳을 가리키는 말이에요.","사람을 가리키는 말이에요.","「지난 봄에」가 때를 알려 줘요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"너희 요즘 걷기 좋은 곳 다녀왔거나 갈 계획 있어?"},{"who":"해든","text":"나는 지난 봄에 강가 산책로에 다녀왔어."},{"who":"나린","text":"나는 다음 달에 숲길을 걸으러 갈 거야."}]}}'::jsonb),
('g5_1_kor_u2_L01_basic#2','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C2',1,'mc','auto','해든이와 나린이의 말끝이 서로 다른 까닭은 무엇인가요?',ARRAY['K5-1-u2-X02']::text[],false,'{"seq":2,"concept":"K5-1-u2-C2","difficulty":1,"kind":"mc","stem":"해든이와 나린이의 말끝이 서로 다른 까닭은 무엇인가요?","options":[{"t":"해든이는 이미 다녀온 일을, 나린이는 앞으로 할 일을 말했기 때문이다","correct":true},{"t":"두 사람이 간 곳이 다르기 때문이다","mis":"K5-1-u2-X02"},{"t":"두 사람의 목소리가 다르기 때문이다","mis":"K5-1-u2-X02"},{"t":"나린이가 더 멀리 가기 때문이다","mis":"K5-1-u2-X02"}],"explanation":["곳은 말끝을 바꾸지 않아요.","말한 사람과도 관계없어요.","지난 일과 앞으로 할 일이라 말끝이 달라요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"너희 요즘 걷기 좋은 곳 다녀왔거나 갈 계획 있어?"},{"who":"해든","text":"나는 지난 봄에 강가 산책로에 다녀왔어."},{"who":"나린","text":"나는 다음 달에 숲길을 걸으러 갈 거야."}]}}'::jsonb),
('g5_1_kor_u2_L01_basic#3','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C3',1,'ox','auto','해든이가 산책로에서 본 것을 적어 두었다면 윤슬이에게 알려 줄 수 있었을 거예요.',ARRAY['K5-1-u2-X03']::text[],false,'{"seq":3,"concept":"K5-1-u2-C3","difficulty":1,"kind":"ox","stem":"해든이가 산책로에서 본 것을 적어 두었다면 윤슬이에게 알려 줄 수 있었을 거예요.","answer":"O","reason_options":[{"t":"글로 남기면 겪은 일을 오래 간직하고 다른 사람에게 전할 수 있기 때문에","correct":true},{"t":"겪은 일은 적지 않아도 늘 또렷이 기억나기 때문에","mis":"K5-1-u2-X03"}],"mis":"K5-1-u2-X03","explanation":["해든이는 기억이 잘 안 난다고 했어요.","기억은 시간이 지나면 흐려져요.","기록은 오래 남고 나눌 수 있어요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"해든아, 나도 그 산책로 가 보려고. 거기서 뭘 봤어?"},{"who":"해든","text":"음……. 기억이 잘 안 나. 적어 둘 걸 그랬어."},{"who":"윤슬","text":"아, 나도 궁금했는데 아쉽다."}]}}'::jsonb),
('g5_1_kor_u2_L01_basic#4','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C4',1,'mc','auto','기행문의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X04']::text[],false,'{"seq":4,"concept":"K5-1-u2-C4","difficulty":1,"kind":"mc","stem":"기행문의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"여행하며 보고, 듣고, 느끼고, 생각한 것을 쓴 글","correct":true},{"t":"여행에서 출발한 시각과 도착한 시각만 적은 글","mis":"K5-1-u2-X04"},{"t":"여행에 쓴 돈을 차례대로 적은 글","mis":"K5-1-u2-X04"},{"t":"가 보고 싶은 곳의 이름만 모은 글","mis":"K5-1-u2-X04"}],"explanation":["시각만 적으면 일정표예요.","돈을 적으면 목록이에요.","보고 듣고 느낀 것이 함께 담겨요."]}'::jsonb),
('g5_1_kor_u2_L01_basic#5','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C1',2,'mc','auto','다음 가운데 시간 표현이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u2-X01']::text[],false,'{"seq":5,"concept":"K5-1-u2-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 시간 표현이 아닌 것은 어느 것인가요?","options":[{"t":"숲길","correct":true},{"t":"다음 달","mis":"K5-1-u2-X01"},{"t":"다녀왔어","mis":"K5-1-u2-X01"},{"t":"갈 거야","mis":"K5-1-u2-X01"}],"explanation":["「다음 달」은 언제인지 알려 줘요.","말끝도 때를 알려 줘요.","「숲길」은 곳을 가리키는 말이에요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"너희 요즘 걷기 좋은 곳 다녀왔거나 갈 계획 있어?"},{"who":"해든","text":"나는 지난 봄에 강가 산책로에 다녀왔어."},{"who":"나린","text":"나는 다음 달에 숲길을 걸으러 갈 거야."}]}}'::jsonb),
('g5_1_kor_u2_L01_basic#6','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C2',2,'blank','auto','빈칸에 알맞은 말을 고르세요. 「나는 어제 강가를 (　　).」',ARRAY['K5-1-u2-X05']::text[],false,'{"seq":6,"concept":"K5-1-u2-C2","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말을 고르세요. 「나는 어제 강가를 (　　).」","options":[{"t":"걸었다","correct":true},{"t":"걷는다","mis":"K5-1-u2-X05"},{"t":"걸을 것이다","mis":"K5-1-u2-X05"},{"t":"걷겠다","mis":"K5-1-u2-X05"}],"explanation":["「어제」는 지난 때예요.","앞으로 할 일의 말끝은 어울리지 않아요.","지난 일이라 「걸었다」예요."]}'::jsonb),
('g5_1_kor_u2_L01_basic#7','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C4',2,'mc','auto','다음 가운데 기행문에 가장 가까운 것은 어느 것인가요?',ARRAY['K5-1-u2-X04','K5-1-u2-X01']::text[],false,'{"seq":7,"concept":"K5-1-u2-C4","difficulty":2,"kind":"mc","stem":"다음 가운데 기행문에 가장 가까운 것은 어느 것인가요?","options":[{"t":"「강가 산책로를 따라 걸었다. 물새가 줄지어 날았는데, 마음까지 시원해지는 것 같았다.」","correct":true},{"t":"「아홉 시 출발, 열 시 도착, 열두 시 점심」","mis":"K5-1-u2-X04"},{"t":"「버스비, 간식값, 입장료」","mis":"K5-1-u2-X04"},{"t":"「다음 주에 가고 싶은 곳: 숲길, 강가」","mis":"K5-1-u2-X01"}],"explanation":["시각만 있는 일정표예요.","쓴 돈의 목록이에요.","다닌 곳 · 본 것 · 느낀 것이 함께 있어요."]}'::jsonb),
('g5_1_kor_u2_L01_basic#8','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C5',2,'mc','auto','이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u2-X04']::text[],false,'{"seq":8,"concept":"K5-1-u2-C5","difficulty":2,"kind":"mc","stem":"이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"시간 표현을 활용해 글 쓰기 · 기행문 쓰기","correct":true},{"t":"시간 표현을 활용해 글 쓰기 · 토론하기","mis":"K5-1-u2-X04"},{"t":"일정표 만들기 · 기행문 쓰기","mis":"K5-1-u2-X04"},{"t":"여행 비용 계산하기 · 일기 쓰기","mis":"K5-1-u2-X04"}],"explanation":["토론은 이 단원이 아니에요.","일정표는 기행문과 달라요.","시간 표현과 기행문을 배워요."]}'::jsonb),
('g5_1_kor_u2_L01_basic#9','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C3',2,'ox','auto','기억에 남는 체험을 떠올릴 때 언제 있었던 일인지, 무엇을 보고 느꼈는지도 함께 떠올리면 좋아요.',ARRAY['K5-1-u2-X04']::text[],false,'{"seq":9,"concept":"K5-1-u2-C3","difficulty":2,"kind":"ox","stem":"기억에 남는 체험을 떠올릴 때 언제 있었던 일인지, 무엇을 보고 느꼈는지도 함께 떠올리면 좋아요.","answer":"O","reason_options":[{"t":"때와 본 것과 느낀 것이 있어야 체험을 글로 생생하게 쓸 수 있기 때문에","correct":true},{"t":"체험은 다닌 곳의 이름만 떠올리면 충분하기 때문에","mis":"K5-1-u2-X04"}],"mis":"K5-1-u2-X04","explanation":["세 가지 물음을 떠올려요.","곳의 이름만으로는 부족해요.","언제 · 무엇을 보고 · 무엇을 느꼈는지."]}'::jsonb),
('g5_1_kor_u2_L01_basic#10','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C5',3,'match','auto','같은 일을 때에 맞게 쓴 문장과 그 때를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C5","difficulty":3,"kind":"match","stem":"같은 일을 때에 맞게 쓴 문장과 그 때를 이으세요.","pairs":[{"l":"나는 어제 강가를 걸었다.","r":"과거"},{"l":"나는 지금 강가를 걷는다.","r":"현재"},{"l":"나는 내일 강가를 걸을 것이다.","r":"미래"}],"mis":"K5-1-u2-X05","explanation":["「어제」는 지난 때예요.","「지금」은 바로 이때예요.","말끝이 때를 알려 줘요."]}'::jsonb),
('g5_1_kor_u2_L01_challenge#1','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C1',2,'mc','auto','윤슬이의 첫 말에서 지난 일과 앞으로의 일을 모두 물은 부분은 어느 것인가요?',ARRAY['K5-1-u2-X01','K5-1-u2-X02','K5-1-u2-X06']::text[],false,'{"seq":1,"concept":"K5-1-u2-C1","difficulty":2,"kind":"mc","stem":"윤슬이의 첫 말에서 지난 일과 앞으로의 일을 모두 물은 부분은 어느 것인가요?","options":[{"t":"「다녀왔거나 갈 계획」","correct":true},{"t":"「걷기 좋은 곳」","mis":"K5-1-u2-X01"},{"t":"「너희 요즘」","mis":"K5-1-u2-X02"},{"t":"「있어?」","mis":"K5-1-u2-X06"}],"explanation":["곳을 가리키는 말이에요.","「요즘」만으로는 지난 일과 앞일이 갈리지 않아요.","다녀왔거나 · 갈 계획이 두 때를 물어요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"너희 요즘 걷기 좋은 곳 다녀왔거나 갈 계획 있어?"},{"who":"해든","text":"나는 지난 봄에 강가 산책로에 다녀왔어."},{"who":"나린","text":"나는 다음 달에 숲길을 걸으러 갈 거야."}]}}'::jsonb),
('g5_1_kor_u2_L01_challenge#2','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C4',2,'ox','auto','다닌 곳의 차례만 빠짐없이 적으면 기행문이라고 할 수 있어요.',ARRAY['K5-1-u2-X04']::text[],false,'{"seq":2,"concept":"K5-1-u2-C4","difficulty":2,"kind":"ox","stem":"다닌 곳의 차례만 빠짐없이 적으면 기행문이라고 할 수 있어요.","answer":"X","reason_options":[{"t":"무엇을 보았는지와 무엇을 느꼈는지가 함께 담겨야 기행문이 되기 때문에","correct":true},{"t":"기행문은 다닌 곳의 차례가 가장 중요하기 때문에","mis":"K5-1-u2-X04"}],"mis":"K5-1-u2-X04","explanation":["차례만 있으면 일정표예요.","보고 느낀 것이 빠졌어요.","보고 들은 것 · 느낀 것이 함께 있어야 해요."]}'::jsonb),
('g5_1_kor_u2_L01_challenge#3','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C3',3,'mc','auto','해든이의 말 「적어 둘 걸 그랬어.」에 담긴 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X03','K5-1-u2-X02']::text[],false,'{"seq":3,"concept":"K5-1-u2-C3","difficulty":3,"kind":"mc","stem":"해든이의 말 「적어 둘 걸 그랬어.」에 담긴 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기록해 두지 않아 본 것을 나누지 못해 아쉬운 마음","correct":true},{"t":"산책로에 다시는 가고 싶지 않은 마음","mis":"K5-1-u2-X03"},{"t":"윤슬이가 묻는 것이 귀찮은 마음","mis":"K5-1-u2-X03"},{"t":"산책로가 너무 멀어서 힘들었던 마음","mis":"K5-1-u2-X02"}],"explanation":["그런 단서는 없어요.","귀찮아하는 말이 아니에요.","기억이 흐려져 아쉬워해요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"해든아, 나도 그 산책로 가 보려고. 거기서 뭘 봤어?"},{"who":"해든","text":"음……. 기억이 잘 안 나. 적어 둘 걸 그랬어."},{"who":"윤슬","text":"아, 나도 궁금했는데 아쉽다."}]}}'::jsonb),
('g5_1_kor_u2_L01_challenge#4','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C2',3,'mc','auto','「다음 달에 숲길을 걸으러 갈 거야.」를 지난 일로 바꾸어 말한 것은 어느 것인가요?',ARRAY['K5-1-u2-X10','K5-1-u2-X21','K5-1-u2-X05']::text[],false,'{"seq":4,"concept":"K5-1-u2-C2","difficulty":3,"kind":"mc","stem":"「다음 달에 숲길을 걸으러 갈 거야.」를 지난 일로 바꾸어 말한 것은 어느 것인가요?","options":[{"t":"「지난달에 숲길을 걸으러 갔어.」","correct":true},{"t":"「지난달에 숲길을 걸으러 갈 거야.」","mis":"K5-1-u2-X10"},{"t":"「다음 달에 숲길을 걸으러 갔어.」","mis":"K5-1-u2-X21"},{"t":"「지금 숲길을 걸으러 간다.」","mis":"K5-1-u2-X05"}],"explanation":["말끝이 그대로예요.","때의 말이 그대로예요.","때의 말과 말끝을 함께 바꿨어요."]}'::jsonb),
('g5_1_kor_u2_L01_challenge#5','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C4',3,'error','auto','기행문에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X04','K5-1-u2-X30','K5-1-u2-X33']::text[],false,'{"seq":5,"concept":"K5-1-u2-C4","difficulty":3,"kind":"error","stem":"기행문에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「여행에 쓴 돈만 꼼꼼히 적어도 기행문이야.」","correct":true,"mis_target":"K5-1-u2-X04"},{"t":"「무엇을 보았는지가 담겨야 해.」","mis":"K5-1-u2-X30"},{"t":"「무엇을 느꼈는지도 함께 담겨야 해.」","mis":"K5-1-u2-X33"}],"explanation":["본 것은 꼭 담겨요.","느낀 것도 담겨요.","돈의 목록은 기행문이 아니에요."]}'::jsonb),
('g5_1_kor_u2_L01_challenge#6','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C5',3,'mc','auto','체험을 떠올려 말하기를 가장 잘한 친구는 누구인가요?',ARRAY['K5-1-u2-X03','K5-1-u2-X02']::text[],false,'{"seq":6,"concept":"K5-1-u2-C5","difficulty":3,"kind":"mc","stem":"체험을 떠올려 말하기를 가장 잘한 친구는 누구인가요?","options":[{"t":"「지난 토요일에 시장에 갔어. 생선 가게 아저씨의 목소리가 커서 깜짝 놀랐고 신이 났어.」","correct":true},{"t":"「시장에 갔어.」","mis":"K5-1-u2-X03"},{"t":"「시장이 좋아.」","mis":"K5-1-u2-X03"},{"t":"「다음에 시장에 갈 거야. 생선이 많대.」","mis":"K5-1-u2-X02"}],"explanation":["언제 · 본 것 · 느낀 것이 빠졌어요.","겪은 일이 드러나지 않아요.","때 · 본 것 · 느낀 것이 모두 있어요."]}'::jsonb),
('g5_1_kor_u2_L01_challenge#7','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C4',3,'sa','auto','여행하며 보고, 듣고, 느끼고, 생각한 것을 쓴 글을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K5-1-u2-C4","difficulty":3,"kind":"sa","stem":"여행하며 보고, 듣고, 느끼고, 생각한 것을 쓴 글을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["기행문"],"explanation":["여행 글이에요.","일정표와 달라요.","「기행문」이에요."],"mis":"K5-1-u2-X04"}'::jsonb),
('g5_1_kor_u2_L01_challenge#8','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C3',4,'essay','teacher','해든이가 산책로에 다녀온 날 무엇을 기록해 두었으면 좋았을지 두 가지 쓰고, 그 기록이 윤슬이에게 어떻게 도움이 되었을지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u2-C3","difficulty":4,"kind":"essay","stem":"해든이가 산책로에 다녀온 날 무엇을 기록해 두었으면 좋았을지 두 가지 쓰고, 그 기록이 윤슬이에게 어떻게 도움이 되었을지 쓰세요.","answer_guide":{"answer":"예: 언제 갔는지와 산책로에서 본 것(강물 위를 나는 새, 길가의 꽃), 그때 느낀 마음(바람이 시원해 기분이 좋았다)을 적어 두었으면 좋았다. 그랬다면 산책로에 가 보려는 윤슬이에게 무엇을 볼 수 있는지 알려 주어 윤슬이가 더 즐겁게 다녀올 수 있었을 것이다.","scoring_points":["기록할 내용을 두 가지 썼는가","본 것과 느낀 것이 들어 있는가","기록이 다른 사람에게 주는 도움을 썼는가"]},"explanation":["해든이는 기억이 안 난다고 했어요.","본 것 · 느낀 것을 떠올려요.","나눌 수 있다는 점과 이어요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"해든아, 나도 그 산책로 가 보려고. 거기서 뭘 봤어?"},{"who":"해든","text":"음……. 기억이 잘 안 나. 적어 둘 걸 그랬어."},{"who":"윤슬","text":"아, 나도 궁금했는데 아쉽다."}]}}'::jsonb),
('g5_1_kor_u2_L01_challenge#9','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C1',4,'essay','teacher','해든이와 나린이의 말에서 시간 표현을 모두 찾아 쓰고, 어떤 표현이 지난 일과 앞으로의 일을 알려 주는지 나누어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u2-C1","difficulty":4,"kind":"essay","stem":"해든이와 나린이의 말에서 시간 표현을 모두 찾아 쓰고, 어떤 표현이 지난 일과 앞으로의 일을 알려 주는지 나누어 쓰세요.","answer_guide":{"answer":"예: 해든이의 말 — 「지난 봄에」와 「다녀왔어」가 지난 일을 알려 준다. 나린이의 말 — 「다음 달에」와 「갈 거야」가 앞으로의 일을 알려 준다. 「산책로」 · 「숲길」은 곳을 가리키는 말이라 시간 표현이 아니다.","scoring_points":["네 가지 시간 표현을 찾았는가","지난 일과 앞으로의 일로 나누었는가","때의 낱말과 말끝을 함께 찾았는가"]},"explanation":["언제인지 알려 주는 말을 찾아요.","말끝도 살펴요.","두 때로 나누어요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"너희 요즘 걷기 좋은 곳 다녀왔거나 갈 계획 있어?"},{"who":"해든","text":"나는 지난 봄에 강가 산책로에 다녀왔어."},{"who":"나린","text":"나는 다음 달에 숲길을 걸으러 갈 거야."}]}}'::jsonb),
('g5_1_kor_u2_L01_challenge#10','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C4',4,'essay','teacher','「동문 → 골목 → 대장간 → 남문」처럼 다닌 곳만 적힌 글을 기행문으로 바꾸려면 무엇을 더 써야 하는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C4","difficulty":4,"kind":"essay","stem":"「동문 → 골목 → 대장간 → 남문」처럼 다닌 곳만 적힌 글을 기행문으로 바꾸려면 무엇을 더 써야 하는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 다닌 곳마다 무엇을 보고 들었는지와 그때 무엇을 느끼고 생각했는지를 더 써야 한다. 다닌 곳만 있으면 일정표일 뿐이고, 보고 듣고 느낀 것이 함께 담겨야 비로소 기행문이 되기 때문이다.","scoring_points":["보고 들은 것을 더해야 한다고 썼는가","느끼고 생각한 것을 더해야 한다고 썼는가","일정표와 기행문의 차이로 까닭을 썼는가"]},"explanation":["지금은 일정표예요.","무엇이 빠졌는지 떠올려요.","본 것 · 느낀 것을 더해요."]}'::jsonb),
('g5_1_kor_u2_L02_basic#1','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C6',1,'mc','auto','「학교 앞 은행나무의 한 해」에서 이미 지나간 일을 나타낸 문장은 어느 것인가요?',ARRAY['K5-1-u2-X05']::text[],false,'{"seq":1,"concept":"K5-1-u2-C6","difficulty":1,"kind":"mc","stem":"「학교 앞 은행나무의 한 해」에서 이미 지나간 일을 나타낸 문장은 어느 것인가요?","options":[{"t":"「이 나무는 아주 작은 연둣빛 잎을 내밀었다.」","correct":true},{"t":"「잎이 우수수 떨어진다.」","mis":"K5-1-u2-X05"},{"t":"「다시 작은 잎을 내밀 것이다.」","mis":"K5-1-u2-X05"},{"t":"「가지만 앙상하게 남을 것이다.」","mis":"K5-1-u2-X05"}],"explanation":["지금 일어나는 일이에요.","앞으로 일어날 일이에요.","-었-이 들어 있어 지난 일이에요."],"asset":{"type":"passage","lines":["학교 정문 옆에는 커다란 은행나무가 서 있다.","지난 사월, 이 나무는 아주 작은 연둣빛 잎을 내밀었다.","여름 내내 잎은 넓고 진해졌고, 한낮에는 넉넉한 그늘을 만들어 주었다.","지금은 시월이다. 나무는 온통 노랗게 물들어 있다.","바람이 불 때마다 잎이 우수수 떨어진다.","다음 달이면 가지만 앙상하게 남을 것이다.","그리고 내년 봄에는 다시 작은 잎을 내밀 것이다."],"title":"「학교 앞 은행나무의 한 해」"}}'::jsonb),
('g5_1_kor_u2_L02_basic#2','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C7',1,'mc','auto','「바람이 불 때마다 잎이 우수수 떨어진다.」는 언제의 일인가요?',ARRAY['K5-1-u2-X05','K5-1-u2-X20']::text[],false,'{"seq":2,"concept":"K5-1-u2-C7","difficulty":1,"kind":"mc","stem":"「바람이 불 때마다 잎이 우수수 떨어진다.」는 언제의 일인가요?","options":[{"t":"지금 일어나고 있는 일","correct":true},{"t":"이미 지나간 일","mis":"K5-1-u2-X05"},{"t":"앞으로 일어날 일","mis":"K5-1-u2-X05"},{"t":"언제인지 알 수 없는 일","mis":"K5-1-u2-X20"}],"explanation":["-었-이 없어요.","-ㄹ 것이 없어요.","-ㄴ-이 지금을 나타내요."],"asset":{"type":"passage","lines":["학교 정문 옆에는 커다란 은행나무가 서 있다.","지난 사월, 이 나무는 아주 작은 연둣빛 잎을 내밀었다.","여름 내내 잎은 넓고 진해졌고, 한낮에는 넉넉한 그늘을 만들어 주었다.","지금은 시월이다. 나무는 온통 노랗게 물들어 있다.","바람이 불 때마다 잎이 우수수 떨어진다.","다음 달이면 가지만 앙상하게 남을 것이다.","그리고 내년 봄에는 다시 작은 잎을 내밀 것이다."],"title":"「학교 앞 은행나무의 한 해」"}}'::jsonb),
