('g5_1_kor_u2_review_a#8','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C43',1,'mc','auto','외갓집 마을 안내장에 넣기에 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u2-X42']::text[],false,'{"seq":8,"concept":"K5-1-u2-C43","difficulty":1,"kind":"mc","stem":"외갓집 마을 안내장에 넣기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"내 시험 점수","correct":true},{"t":"떡방앗간의 갓 찐 떡","mis":"K5-1-u2-X42"},{"t":"느티나무 쉼터","mis":"K5-1-u2-X42"},{"t":"저수지 둑길 산책","mis":"K5-1-u2-X42"}],"explanation":["먹을거리예요.","갈 만한 곳이에요.","여행지와 관계없어요."]}'::jsonb),
('g5_1_kor_u2_review_a#9','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C12',2,'mc','auto','솔미의 글에서 때를 나타내는 말과 말끝이 어색하게 쓰인 문장은 어느 것인가요?',ARRAY['K5-1-u2-X10','K5-1-u2-X11']::text[],false,'{"seq":9,"concept":"K5-1-u2-C12","difficulty":2,"kind":"mc","stem":"솔미의 글에서 때를 나타내는 말과 말끝이 어색하게 쓰인 문장은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"K5-1-u2-X10"},{"t":"㉰","mis":"K5-1-u2-X10"},{"t":"㉲","mis":"K5-1-u2-X11"}],"explanation":["「봄에 … 있었다」는 어울려요.","지난 일을 지난 말끝으로 썼어요.","「지난 금요일」인데 「캔다」라서 어색해요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb),
('g5_1_kor_u2_review_a#10','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C29',2,'match','auto','가비의 기행문 ①의 문장과 요소를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C29","difficulty":2,"kind":"match","stem":"가비의 기행문 ①의 문장과 요소를 이으세요.","pairs":[{"l":"우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다","r":"여정"},{"l":"이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다","r":"견문"},{"l":"마을 사람들을 오래 지켜 온 할아버지 같았다","r":"감상"}],"mis":"K5-1-u2-X28","explanation":["어디로 갔나요?","들은 것인가요?","느낀 것인가요?"],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb),
('g5_1_kor_u2_review_a#11','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C51',2,'blank','auto','㉮의 빈칸에 알맞은 낱말을 고르세요.',ARRAY['K5-1-u2-X50']::text[],false,'{"seq":11,"concept":"K5-1-u2-C51","difficulty":2,"kind":"blank","stem":"㉮의 빈칸에 알맞은 낱말을 고르세요.","options":[{"t":"조용히","correct":true},{"t":"조용이","mis":"K5-1-u2-X50"},{"t":"조용하게히","mis":"K5-1-u2-X50"},{"t":"조용니","mis":"K5-1-u2-X50"}],"explanation":["「히」로 끝나는 무리예요.","그런 낱말은 없어요.","「조용히」로 써요."],"asset":{"type":"passage","lines":["㉮ 동생이 잠든 방 앞을 (　　) 지나갔다.","㉯ 쉬는 시간마다 (　　) 여행 일기를 적었다.","㉰ 방 안을 (　　) 뒤졌지만 열쇠는 보이지 않았다.","㉱ 넘어졌는데 (　　) 크게 다치지는 않았다."],"title":"빈칸에 들어갈 낱말"}}'::jsonb),
('g5_1_kor_u2_review_a#12','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C17',2,'mc','auto','채온이네 반이 학급 문고를 정리하는 날은 모두 며칠인가요?',ARRAY['K5-1-u2-X15','K5-1-u2-X16']::text[],false,'{"seq":12,"concept":"K5-1-u2-C17","difficulty":2,"kind":"mc","stem":"채온이네 반이 학급 문고를 정리하는 날은 모두 며칠인가요?","options":[{"t":"사흘","correct":true},{"t":"이틀","mis":"K5-1-u2-X15"},{"t":"나흘","mis":"K5-1-u2-X16"},{"t":"닷새","mis":"K5-1-u2-X15"}],"explanation":["수요일만 세지 마세요.","수 · 목 · 금을 세어 보세요.","수요일부터 금요일까지 사흘이에요."],"asset":{"type":"passage","lines":["오늘은 월요일이다.","우리 반은 모레인 수요일부터 금요일까지 학급 문고 정리를 한다.","정리가 끝나면 그다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 연다."],"title":"채온이네 반의 계획"}}'::jsonb),
('g5_1_kor_u2_review_a#13','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C13',2,'mc','auto','고치지 않아도 되는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X10']::text[],false,'{"seq":13,"concept":"K5-1-u2-C13","difficulty":2,"kind":"mc","stem":"고치지 않아도 되는 문장은 어느 것인가요?","options":[{"t":"「나 내일 외갓집에 간다.」","correct":true},{"t":"「나 어제 외갓집에 갈 것이다.」","mis":"K5-1-u2-X10"},{"t":"「나 아까 외갓집에 가겠다.」","mis":"K5-1-u2-X10"},{"t":"「나 그저께 외갓집에 갈 거야.」","mis":"K5-1-u2-X10"}],"explanation":["지난 날과 앞일의 말끝이 어색해요.","조금 전과 앞일의 말끝이 어색해요.","가까운 앞일을 「간다」로 말해도 어색하지 않아요."]}'::jsonb),
('g5_1_kor_u2_review_a#14','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C32',2,'mc','auto','「김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.」가 견문인 까닭은 무엇인가요?',ARRAY['K5-1-u2-X31','K5-1-u2-X30','K5-1-u2-X28']::text[],false,'{"seq":14,"concept":"K5-1-u2-C32","difficulty":2,"kind":"mc","stem":"「김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.」가 견문인 까닭은 무엇인가요?","options":[{"t":"그곳에 있던 사람이라면 누구나 똑같이 확인할 수 있기 때문이다","correct":true},{"t":"문장이 길기 때문이다","mis":"K5-1-u2-X31"},{"t":"가비의 마음이 드러나기 때문이다","mis":"K5-1-u2-X30"},{"t":"다닌 곳이 드러나기 때문이다","mis":"K5-1-u2-X28"}],"explanation":["길이로 가르지 않아요.","마음이 드러나면 감상이에요.","누구나 확인할 수 있으면 견문이에요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb),
('g5_1_kor_u2_review_a#15','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C35',2,'mc','auto','가비의 기행문은 어떤 경험을 글감으로 삼았나요?',ARRAY['K5-1-u2-X34']::text[],false,'{"seq":15,"concept":"K5-1-u2-C35","difficulty":2,"kind":"mc","stem":"가비의 기행문은 어떤 경험을 글감으로 삼았나요?","options":[{"t":"명절에 간 친척 집 마을","correct":true},{"t":"먼 나라로 떠난 여행","mis":"K5-1-u2-X34"},{"t":"이름난 관광지","mis":"K5-1-u2-X34"},{"t":"상상 속의 여행","mis":"K5-1-u2-X34"}],"explanation":["멀리 가지 않았어요.","외갓집 마을이에요.","명절에 간 친척 집도 글감이에요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb),
('g5_1_kor_u2_review_a#16','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C46',2,'mc','auto','해솜이와 율하의 안내장 문구 가운데 감상이 드러난 것은 누구의 것인가요?',ARRAY['K5-1-u2-X45']::text[],false,'{"seq":16,"concept":"K5-1-u2-C46","difficulty":2,"kind":"mc","stem":"해솜이와 율하의 안내장 문구 가운데 감상이 드러난 것은 누구의 것인가요?","options":[{"t":"율하","correct":true},{"t":"해솜","mis":"K5-1-u2-X45"},{"t":"둘 다","mis":"K5-1-u2-X45"},{"t":"둘 다 아니다","mis":"K5-1-u2-X45"}],"explanation":["해솜이는 위치와 그늘만 알렸어요.","한 사람만 느낌을 담았어요.","「하루가 천천히 흘러갑니다」에 느낌이 있어요."],"asset":{"type":"passage","lines":["해솜 — 「느티나무 쉼터: 마을 입구에 있습니다. 그늘이 넓습니다.」","율하 — 「느티나무 쉼터: 두 팔로 안아도 다 안기지 않는 나무 아래에서","　　　 바람 소리를 들으면 하루가 천천히 흘러갑니다.」"],"title":"두 친구가 쓴 안내장 문구"}}'::jsonb),
('g5_1_kor_u2_review_a#17','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C49',3,'mc','auto','기행문을 쓸 때 시간 표현이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X48','K5-1-u2-X33']::text[],false,'{"seq":17,"concept":"K5-1-u2-C49","difficulty":3,"kind":"mc","stem":"기행문을 쓸 때 시간 표현이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기행문은 시간과 공간을 따라 움직이는 글이라 시간 표현이 흔들리면 다닌 길도 흐트러지기 때문이다","correct":true},{"t":"기행문에는 시간 표현을 쓰지 않기 때문이다","mis":"K5-1-u2-X48"},{"t":"시간 표현은 일기에만 쓰기 때문이다","mis":"K5-1-u2-X48"},{"t":"다닌 곳만 쓰면 시간은 필요 없기 때문이다","mis":"K5-1-u2-X33"}],"explanation":["기행문에도 시간 표현이 있어요.","두 소단원은 이어져 있어요.","시간 표현이 기행문의 뼈대예요."]}'::jsonb),
('g5_1_kor_u2_review_a#18','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C27',3,'mc','auto','솔미가 초안을 스스로 확인할 때 가장 먼저 고쳐야 할 것은 어느 것인가요?',ARRAY['K5-1-u2-X26','K5-1-u2-X11']::text[],false,'{"seq":18,"concept":"K5-1-u2-C27","difficulty":3,"kind":"mc","stem":"솔미가 초안을 스스로 확인할 때 가장 먼저 고쳐야 할 것은 어느 것인가요?","options":[{"t":"때를 나타내는 말과 말끝이 어색한 ㉮와 ㉳","correct":true},{"t":"글씨를 더 크게 쓰기","mis":"K5-1-u2-X26"},{"t":"문장을 모두 짧게 줄이기","mis":"K5-1-u2-X26"},{"t":"㉲의 「지금」을 지우기","mis":"K5-1-u2-X11"}],"explanation":["글씨는 기준이 아니에요.","길이를 줄이는 것이 아니에요.","시간 표현이 어색한 문장을 고쳐요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb),
('g5_1_kor_u2_review_a#19','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C38',3,'mc','auto','가비의 기행문 가운데 부분은 무엇을 따라 쓰였나요?',ARRAY['K5-1-u2-X37']::text[],false,'{"seq":19,"concept":"K5-1-u2-C38","difficulty":3,"kind":"mc","stem":"가비의 기행문 가운데 부분은 무엇을 따라 쓰였나요?","options":[{"t":"마을 안에서 다닌 곳의 차례","correct":true},{"t":"떡을 만드는 순서","mis":"K5-1-u2-X37"},{"t":"외할머니의 말씀 순서","mis":"K5-1-u2-X37"},{"t":"하루의 날씨 변화","mis":"K5-1-u2-X37"}],"explanation":["떡 이야기는 한 곳에서 나와요.","말씀은 견문의 하나예요.","느티나무 → 방앗간 → 둑길을 따라가요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb),
('g5_1_kor_u2_review_a#20','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C29',3,'match','auto','「모래벌판을 지나」의 문장과 요소를 이으세요.','{}'::text[],false,'{"seq":20,"concept":"K5-1-u2-C29","difficulty":3,"kind":"match","stem":"「모래벌판을 지나」의 문장과 요소를 이으세요.","pairs":[{"l":"언덕 너머 습지에 이르렀다","r":"여정"},{"l":"바람이 수천 년 동안 모래를 실어 나르며 만들어졌다고 한다","r":"견문"},{"l":"바람이 이렇게 오래 일한다는 사실이 놀라웠다","r":"감상"}],"mis":"K5-1-u2-X28","explanation":["다닌 곳이에요.","들은 설명이에요.","놀란 마음이에요."],"asset":{"type":"passage","lines":["지난 봄, 우리 가족은 태안 신두리로 여행을 떠났다. 바닷가 모래 언덕이 궁금했기 때문이다.","우리는 먼저 해안 사구 탐방로에 들어섰다. 발밑에서 모래가 자꾸 무너졌다.","이곳의 모래 언덕은 바람이 수천 년 동안 모래를 실어 나르며 만들어진 것이라고 한다.","바람이 이렇게 오래 일한다는 사실이 놀라웠다.","다음으로 언덕 너머 습지에 이르렀다. 마른 모래땅 바로 옆에 물이 고여 풀이 자라고 있었다.","돌아오는 길에 신발 속 모래를 털어 냈다.","발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다. 다음에는 바람이 센 계절에 다시 와 보고 싶다."],"title":"「모래벌판을 지나」"}}'::jsonb),
('g5_1_kor_u2_review_a#21','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C20',3,'mc','auto','「금방」이 조금 전의 때를 가리키는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X18']::text[],false,'{"seq":21,"concept":"K5-1-u2-C20","difficulty":3,"kind":"mc","stem":"「금방」이 조금 전의 때를 가리키는 문장은 어느 것인가요?","options":[{"t":"「외할머니께서 금방 떡을 쪄 오셨다.」","correct":true},{"t":"「떡이 금방 다 쪄질 거야.」","mis":"K5-1-u2-X18"},{"t":"「소문이 금세 온 마을에 퍼졌다.」","mis":"K5-1-u2-X18"},{"t":"「금방 출발할 테니 기다려.」","mis":"K5-1-u2-X18"}],"explanation":["곧을 가리켜요.","빠르기를 말해요.","「쪄 오셨다」와 함께 조금 전이에요."]}'::jsonb),
('g5_1_kor_u2_review_a#22','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C41',3,'mc','auto','가비가 기행문을 쓰기 전에 했을 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X40','K5-1-u2-X33']::text[],false,'{"seq":22,"concept":"K5-1-u2-C41","difficulty":3,"kind":"mc","stem":"가비가 기행문을 쓰기 전에 했을 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"외갓집 마을에서 찍은 사진을 보며 기억에 남는 장면을 떠올리고 개요를 짠다","correct":true},{"t":"여러 해의 명절 이야기를 한 글에 모두 섞기로 한다","mis":"K5-1-u2-X40"},{"t":"개요 없이 떠오르는 대로 바로 쓴다","mis":"K5-1-u2-X40"},{"t":"다닌 곳 이름만 적고 쓰기를 끝낸다","mis":"K5-1-u2-X33"}],"explanation":["경험 하나를 골라요.","개요를 먼저 짜요.","장면을 떠올려 개요로 정리해요."]}'::jsonb),
('g5_1_kor_u2_review_a#23','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C23',4,'essay','teacher','솔미의 글에서 시간 표현이 어색한 문장 두 개를 찾아 바르게 고쳐 쓰고, 왜 그렇게 고쳤는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u2-C23","difficulty":4,"kind":"essay","stem":"솔미의 글에서 시간 표현이 어색한 문장 두 개를 찾아 바르게 고쳐 쓰고, 왜 그렇게 고쳤는지 쓰세요.","answer_guide":{"answer":"예: ㉮ 「지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캤다.」 — 「지난 금요일」은 이미 지난 때라 지난 일의 말끝으로 고쳤다. ㉳ 「다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹을 것이다.」 — 「다음 주」는 앞으로의 때라 앞일의 말끝으로 고쳤다.","scoring_points":["어색한 두 문장을 찾았는가","때의 말에 맞게 말끝을 고쳤는가","고친 까닭을 썼는가"]},"explanation":["때를 나타내는 말부터 봐요.","말끝이 어울리는지 소리 내어 읽어요.","때에 맞게 고쳐요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb),
('g5_1_kor_u2_review_a#24','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C38',4,'essay','teacher','가 본 곳 하나를 떠올려 기행문의 가운데 부분을 한 문단으로 쓰세요. 다닌 곳 · 보고 들은 것 · 느낀 것을 모두 넣고, 지난 일을 나타내는 말끝을 바르게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u2-C38","difficulty":4,"kind":"essay","stem":"가 본 곳 하나를 떠올려 기행문의 가운데 부분을 한 문단으로 쓰세요. 다닌 곳 · 보고 들은 것 · 느낀 것을 모두 넣고, 지난 일을 나타내는 말끝을 바르게 쓰세요.","answer_guide":{"answer":"예: 다음으로 시장 안 국수 골목에 들어섰다. 커다란 솥에서 김이 모락모락 피어올랐고, 할머니께서 국수를 사십 년 동안 삶아 오셨다고 말씀하셨다. 한 그릇의 국수에 할머니의 긴 시간이 담겨 있는 것 같아 국물까지 남김없이 마셨다.","scoring_points":["다닌 곳을 밝혔는가","보고 들은 것을 썼는가","느낀 것을 넣고 지난 일의 말끝을 바르게 썼는가"]},"explanation":["다닌 곳 하나를 골라요.","본 것과 들은 것을 써요.","느낀 것으로 마무리해요."]}'::jsonb),
('g5_1_kor_u2_review_a#25','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C49',4,'essay','teacher','이 단원에서 배운 「시간 표현을 활용해 글 쓰기」와 「기행문 쓰기」가 서로 어떻게 이어지는지 쓰고, 가비의 기행문에서 시간 표현이 쓰인 곳을 예로 드세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u2-C49","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「시간 표현을 활용해 글 쓰기」와 「기행문 쓰기」가 서로 어떻게 이어지는지 쓰고, 가비의 기행문에서 시간 표현이 쓰인 곳을 예로 드세요.","answer_guide":{"answer":"예: 기행문은 시간과 공간을 따라 움직이는 글이라, 시간 표현이 흔들리면 다닌 길도 흐트러진다. 그래서 시간 표현이 기행문의 뼈대를 세운다. 가비의 기행문에서는 「추석 연휴에」 · 「먼저」 · 「다음으로」 · 「마지막으로」 · 「돌아오는 길」과 지난 일의 말끝 「갔다 · 들렀다 · 걸었다」가 다닌 차례를 또렷하게 해 준다.","scoring_points":["두 공부가 이어지는 까닭을 썼는가","시간 표현이 뼈대라는 점을 썼는가","가비의 기행문에서 예를 들었는가"]},"explanation":["기행문은 움직이는 글이에요.","시간 표현이 하는 일을 떠올려요.","예를 찾아 써요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb),
('g5_1_kor_u2_review_b#1','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C51',1,'mc','auto','「히」로 끝나는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K5-1-u2-X50']::text[],false,'{"seq":1,"concept":"K5-1-u2-C51","difficulty":1,"kind":"mc","stem":"「히」로 끝나는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"조용히","correct":true},{"t":"솔직이","mis":"K5-1-u2-X50"},{"t":"분명이","mis":"K5-1-u2-X50"},{"t":"특별이","mis":"K5-1-u2-X50"}],"explanation":["「솔직히」로 써요.","「분명히」로 써요.","「조용히」가 바른 표기예요."]}'::jsonb),
('g5_1_kor_u2_review_b#2','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C7',1,'mc','auto','솔미의 글에서 지금의 일을 나타낸 문장은 어느 것인가요?',ARRAY['K5-1-u2-X05']::text[],false,'{"seq":2,"concept":"K5-1-u2-C7","difficulty":1,"kind":"mc","stem":"솔미의 글에서 지금의 일을 나타낸 문장은 어느 것인가요?","options":[{"t":"㉲","correct":true},{"t":"㉯","mis":"K5-1-u2-X05"},{"t":"㉰","mis":"K5-1-u2-X05"},{"t":"㉱","mis":"K5-1-u2-X05"}],"explanation":["「뻗어 있었다」 — 지난 일이에요.","「나왔다」 — 지난 일이에요.","「지금 … 떠오른다」가 지금을 알려 줘요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb),
('g5_1_kor_u2_review_b#3','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C15',1,'mc','auto','오늘에서 사흘 전을 가리키는 말은 어느 것인가요?',ARRAY['K5-1-u2-X13']::text[],false,'{"seq":3,"concept":"K5-1-u2-C15","difficulty":1,"kind":"mc","stem":"오늘에서 사흘 전을 가리키는 말은 어느 것인가요?","options":[{"t":"그끄저께","correct":true},{"t":"그저께","mis":"K5-1-u2-X13"},{"t":"글피","mis":"K5-1-u2-X13"},{"t":"어제","mis":"K5-1-u2-X13"}],"explanation":["그저께는 이틀 전이에요.","글피는 사흘 뒤예요.","그저께보다 하루 더 앞이 그끄저께예요."]}'::jsonb),
('g5_1_kor_u2_review_b#4','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C18',1,'mc','auto','방앗간 아주머니께서 떡을 찐다고 하신 「사흘 동안」은 며칠 동안인가요?',ARRAY['K5-1-u2-X16','K5-1-u2-X14']::text[],false,'{"seq":4,"concept":"K5-1-u2-C18","difficulty":1,"kind":"mc","stem":"방앗간 아주머니께서 떡을 찐다고 하신 「사흘 동안」은 며칠 동안인가요?","options":[{"t":"삼 일 동안","correct":true},{"t":"사 일 동안","mis":"K5-1-u2-X16"},{"t":"이 일 동안","mis":"K5-1-u2-X14"},{"t":"오 일 동안","mis":"K5-1-u2-X14"}],"explanation":["「사」 소리에 속지 마세요.","이 일은 이틀이에요.","사흘은 삼 일이에요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb),
('g5_1_kor_u2_review_b#5','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C30',1,'mc','auto','가비의 기행문에서 들은 것을 쓴 견문은 어느 것인가요?',ARRAY['K5-1-u2-X29','K5-1-u2-X30']::text[],false,'{"seq":5,"concept":"K5-1-u2-C30","difficulty":1,"kind":"mc","stem":"가비의 기행문에서 들은 것을 쓴 견문은 어느 것인가요?","options":[{"t":"「외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.」","correct":true},{"t":"「우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.」","mis":"K5-1-u2-X29"},{"t":"「마을 사람들을 오래 지켜 온 할아버지 같았다.」","mis":"K5-1-u2-X30"},{"t":"「아침부터 마음이 들떴다.」","mis":"K5-1-u2-X29"}],"explanation":["다닌 곳이에요.","느낀 마음이에요.","들은 설명도 견문이에요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb),
