('g5_1_kor_u2_review_b#12','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C21',2,'mc','auto','채온이네 반의 계획을 날짜 말과 날수 말로 바르게 줄인 것은 어느 것인가요?',ARRAY['K5-1-u2-X15','K5-1-u2-X19']::text[],false,'{"seq":12,"concept":"K5-1-u2-C21","difficulty":2,"kind":"mc","stem":"채온이네 반의 계획을 날짜 말과 날수 말로 바르게 줄인 것은 어느 것인가요?","options":[{"t":"「모레부터 사흘 동안 학급 문고를 정리한다.」","correct":true},{"t":"「모레 동안 학급 문고를 정리한다.」","mis":"K5-1-u2-X15"},{"t":"「사흘에 학급 문고를 정리한다.」","mis":"K5-1-u2-X15"},{"t":"「언젠가 학급 문고를 정리한다.」","mis":"K5-1-u2-X19"}],"explanation":["「모레」는 며칠 동안이 아니에요.","「사흘」은 어느 날이 아니에요.","시작하는 날과 며칠 동안을 함께 말했어요."],"asset":{"type":"passage","lines":["오늘은 월요일이다.","우리 반은 모레인 수요일부터 금요일까지 학급 문고 정리를 한다.","정리가 끝나면 그다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 연다."],"title":"채온이네 반의 계획"}}'::jsonb),
('g5_1_kor_u2_review_b#13','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C10',2,'ox','auto','「소는 풀을 먹는다.」의 「먹는다」는 바로 이 순간에만 먹고 있다는 뜻이에요.',ARRAY['K5-1-u2-X07']::text[],false,'{"seq":13,"concept":"K5-1-u2-C10","difficulty":2,"kind":"ox","stem":"「소는 풀을 먹는다.」의 「먹는다」는 바로 이 순간에만 먹고 있다는 뜻이에요.","answer":"X","reason_options":[{"t":"-는-은 늘 되풀이되는 일에도 쓰이기 때문에","correct":true},{"t":"-는-은 언제나 지금 이 순간만 나타내기 때문에","mis":"K5-1-u2-X07"}],"mis":"K5-1-u2-X07","explanation":["-는-이 늘 지금만은 아니에요.","소는 늘 풀을 먹어요.","되풀이되는 일이에요."]}'::jsonb),
('g5_1_kor_u2_review_b#14','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C32',2,'ox','auto','「굵은 줄기가 할아버지 같았다」는 가비와 함께 있던 사람이라면 누구나 똑같이 느낄 수 있으니 견문이에요.',ARRAY['K5-1-u2-X31']::text[],false,'{"seq":14,"concept":"K5-1-u2-C32","difficulty":2,"kind":"ox","stem":"「굵은 줄기가 할아버지 같았다」는 가비와 함께 있던 사람이라면 누구나 똑같이 느낄 수 있으니 견문이에요.","answer":"X","reason_options":[{"t":"같은 나무를 보아도 사람마다 다르게 느낄 수 있는 마음이므로 감상이기 때문에","correct":true},{"t":"나무를 직접 보았으니 견문이기 때문에","mis":"K5-1-u2-X31"}],"mis":"K5-1-u2-X31","explanation":["본 것과 느낀 것은 달라요.","사람마다 다를 수 있어요.","마음속에서 일어난 감상이에요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb),
('g5_1_kor_u2_review_b#15','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C35',2,'ox','auto','가비처럼 명절에 외갓집에 다녀온 경험은 여행이 아니라서 기행문으로 쓸 수 없어요.',ARRAY['K5-1-u2-X34']::text[],false,'{"seq":15,"concept":"K5-1-u2-C35","difficulty":2,"kind":"ox","stem":"가비처럼 명절에 외갓집에 다녀온 경험은 여행이 아니라서 기행문으로 쓸 수 없어요.","answer":"X","reason_options":[{"t":"다닌 곳이 있고 보고 느낀 것이 있으면 가까운 곳이나 친척 집도 기행문의 글감이기 때문에","correct":true},{"t":"기행문은 이름난 관광지에 다녀와야만 쓸 수 있기 때문에","mis":"K5-1-u2-X34"}],"mis":"K5-1-u2-X34","explanation":["멀리 가야 하는 것이 아니에요.","다닌 곳 · 본 것 · 느낀 것이 있어요.","친척 집도 글감이에요."]}'::jsonb),
('g5_1_kor_u2_review_b#16','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C46',2,'ox','auto','해솜이의 문구처럼 사실만 적어도 읽는 사람이 꼭 가 보고 싶어져요.',ARRAY['K5-1-u2-X45']::text[],false,'{"seq":16,"concept":"K5-1-u2-C46","difficulty":2,"kind":"ox","stem":"해솜이의 문구처럼 사실만 적어도 읽는 사람이 꼭 가 보고 싶어져요.","answer":"X","reason_options":[{"t":"정보만 있으면 안내판이 되고 느낌이 있어야 가 보고 싶어지기 때문에","correct":true},{"t":"사실이 많을수록 마음이 움직이기 때문에","mis":"K5-1-u2-X45"}],"mis":"K5-1-u2-X45","explanation":["정보도 필요해요.","그것만으로는 마음이 덜 움직여요.","느낌을 한 문장 더해요."],"asset":{"type":"passage","lines":["해솜 — 「느티나무 쉼터: 마을 입구에 있습니다. 그늘이 넓습니다.」","율하 — 「느티나무 쉼터: 두 팔로 안아도 다 안기지 않는 나무 아래에서","　　　 바람 소리를 들으면 하루가 천천히 흘러갑니다.」"],"title":"두 친구가 쓴 안내장 문구"}}'::jsonb),
('g5_1_kor_u2_review_b#17','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C49',3,'ox','auto','시간 표현을 활용해 글 쓰기와 기행문 쓰기는 서로 관계없는 공부예요.',ARRAY['K5-1-u2-X48']::text[],false,'{"seq":17,"concept":"K5-1-u2-C49","difficulty":3,"kind":"ox","stem":"시간 표현을 활용해 글 쓰기와 기행문 쓰기는 서로 관계없는 공부예요.","answer":"X","reason_options":[{"t":"기행문은 시간과 공간을 따라 움직여 시간 표현이 뼈대를 세우기 때문에","correct":true},{"t":"기행문은 시간과 상관없이 느낌만 쓰는 글이기 때문에","mis":"K5-1-u2-X48"}],"mis":"K5-1-u2-X48","explanation":["두 소단원은 이어져 있어요.","느낌만 쓰지 않아요.","시간 표현이 기행문을 받쳐 줘요."]}'::jsonb),
('g5_1_kor_u2_review_b#18','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C25',3,'mc','auto','솔미의 글에 처음 부분을 더한다면 들어갈 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X23']::text[],false,'{"seq":18,"concept":"K5-1-u2-C25","difficulty":3,"kind":"mc","stem":"솔미의 글에 처음 부분을 더한다면 들어갈 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고구마를 캐게 된 까닭이나 그날의 상황","correct":true},{"t":"다음에 또 하고 싶은 다짐","mis":"K5-1-u2-X23"},{"t":"고구마를 캐며 있었던 일","mis":"K5-1-u2-X23"},{"t":"고구마를 먹은 뒤의 전체 느낌","mis":"K5-1-u2-X23"}],"explanation":["끝에 들어가요.","가운데에 들어가요.","처음에는 상황이나 까닭이 들어가요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb),
('g5_1_kor_u2_review_b#19','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C33',3,'mc','auto','가비의 기행문에서 여정 · 견문 · 감상이 한 대목 안에 함께 어우러진 곳은 어디인가요?',ARRAY['K5-1-u2-X32']::text[],false,'{"seq":19,"concept":"K5-1-u2-C33","difficulty":3,"kind":"mc","stem":"가비의 기행문에서 여정 · 견문 · 감상이 한 대목 안에 함께 어우러진 곳은 어디인가요?","options":[{"t":"느티나무 대목","correct":true},{"t":"기행문 맨 첫 문장","mis":"K5-1-u2-X32"},{"t":"설에 다시 가고 싶다는 문장","mis":"K5-1-u2-X32"},{"t":"기행문에는 어우러진 대목이 없다","mis":"K5-1-u2-X32"}],"explanation":["첫 문장은 여정만 있어요.","끝의 바람이에요.","갔다 → 말씀하셨다 → 할아버지 같았다가 이어져요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb),
('g5_1_kor_u2_review_b#20','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C31',3,'mc','auto','「발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다.」가 감상인 까닭은 무엇인가요?',ARRAY['K5-1-u2-X30','K5-1-u2-X28','K5-1-u2-X31']::text[],false,'{"seq":20,"concept":"K5-1-u2-C31","difficulty":3,"kind":"mc","stem":"「발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다.」가 감상인 까닭은 무엇인가요?","options":[{"t":"모래를 보고 글쓴이가 마음속으로 느낀 것이라 사람마다 다를 수 있기 때문이다","correct":true},{"t":"신발 속에 모래가 있었다는 사실이기 때문이다","mis":"K5-1-u2-X30"},{"t":"다닌 곳이 드러나기 때문이다","mis":"K5-1-u2-X28"},{"t":"문장에 꾸미는 말이 많기 때문이다","mis":"K5-1-u2-X31"}],"explanation":["모래가 있었던 것은 사실이지만 문장의 중심은 마음이에요.","다닌 곳이 아니에요.","꾸미는 말로 가르지 않아요."],"asset":{"type":"passage","lines":["지난 봄, 우리 가족은 태안 신두리로 여행을 떠났다. 바닷가 모래 언덕이 궁금했기 때문이다.","우리는 먼저 해안 사구 탐방로에 들어섰다. 발밑에서 모래가 자꾸 무너졌다.","이곳의 모래 언덕은 바람이 수천 년 동안 모래를 실어 나르며 만들어진 것이라고 한다.","바람이 이렇게 오래 일한다는 사실이 놀라웠다.","다음으로 언덕 너머 습지에 이르렀다. 마른 모래땅 바로 옆에 물이 고여 풀이 자라고 있었다.","돌아오는 길에 신발 속 모래를 털어 냈다.","발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다. 다음에는 바람이 센 계절에 다시 와 보고 싶다."],"title":"「모래벌판을 지나」"}}'::jsonb),
('g5_1_kor_u2_review_b#21','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C14',3,'mc','auto','「올해」를 앞으로의 일에 쓴 문장은 어느 것인가요?',ARRAY['K5-1-u2-X12']::text[],false,'{"seq":21,"concept":"K5-1-u2-C14","difficulty":3,"kind":"mc","stem":"「올해」를 앞으로의 일에 쓴 문장은 어느 것인가요?","options":[{"t":"「올해 안에 외갓집에 한 번 더 갈 것이다.」","correct":true},{"t":"「올해 봄에 외갓집에 갔다.」","mis":"K5-1-u2-X12"},{"t":"「올해는 벼가 잘 익는다.」","mis":"K5-1-u2-X12"},{"t":"「올해 설에 떡을 빚었다.」","mis":"K5-1-u2-X12"}],"explanation":["지난 일이에요.","지금의 일이에요.","「올해」는 세 때에 두루 쓰여요. 말끝을 봐요."]}'::jsonb),
('g5_1_kor_u2_review_b#22','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C42',3,'mc','auto','가비가 쓰기 과정을 점검하며 적은 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X41','K5-1-u2-X26','K5-1-u2-X27']::text[],false,'{"seq":22,"concept":"K5-1-u2-C42","difficulty":3,"kind":"mc","stem":"가비가 쓰기 과정을 점검하며 적은 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「방앗간 대목에 감상이 적어서, 다음에는 그곳에서 느낀 마음을 더 써야겠다.」","correct":true},{"t":"「다 썼으니 돌아볼 것이 없다.」","mis":"K5-1-u2-X41"},{"t":"「글씨가 예쁘지 않았다.」","mis":"K5-1-u2-X26"},{"t":"「글이 길어서 잘 썼다.」","mis":"K5-1-u2-X27"}],"explanation":["돌아보는 것도 쓰기예요.","글씨는 기준이 아니에요.","아쉬운 점과 고칠 방법을 적었어요."]}'::jsonb),
('g5_1_kor_u2_review_b#23','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C33',4,'essay','teacher','가비의 기행문 ②에서 한 곳을 골라 여정 · 견문 · 감상이 한 문단 안에서 어떻게 이어지는지 문장을 들어 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u2-C33","difficulty":4,"kind":"essay","stem":"가비의 기행문 ②에서 한 곳을 골라 여정 · 견문 · 감상이 한 문단 안에서 어떻게 이어지는지 문장을 들어 설명하세요.","answer_guide":{"answer":"예: 방앗간 대목 — 「다음으로 개울을 건너 떡방앗간에 들렀다」(여정)에서 방앗간에 간 것을 밝히고, 「시루에서 갓 찐 떡을 꺼내고 있었다」 · 「사흘 동안은 새벽부터 떡을 찐다고 하셨다」(견문)로 본 것과 들은 것을 쓴 뒤, 끝에서 「설에 다시 가면 떡을 빚어 보고 싶다」(감상)로 마음을 이었다. 셋이 따로 떨어지지 않고 그곳을 중심으로 이어진다.","scoring_points":["한 곳을 골랐는가","여정 · 견문 · 감상 문장을 찾았는가","어떻게 이어지는지 설명했는가"]},"explanation":["다닌 곳 하나를 골라요.","세 요소의 문장을 찾아요.","이어지는 모습을 설명해요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb),
('g5_1_kor_u2_review_b#24','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C39',4,'essay','teacher','가비의 기행문 끝부분에 전체적인 느낌이나 배운 것을 한두 문장 더 써 보고, 끝부분에 그런 내용이 들어가는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u2-C39","difficulty":4,"kind":"essay","stem":"가비의 기행문 끝부분에 전체적인 느낌이나 배운 것을 한두 문장 더 써 보고, 끝부분에 그런 내용이 들어가는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「외갓집 마을은 작지만, 오래된 나무와 새벽부터 떡을 찌는 방앗간처럼 저마다 제 몫을 하는 것들로 가득했다. 이번 여행으로 외할머니가 사는 마을을 조금 더 알게 되었다.」 끝부분은 여행을 돌아보며 전체적인 느낌과 배운 것, 앞으로의 계획을 정리하는 곳이기 때문이다.","scoring_points":["전체적인 느낌이나 배운 것을 썼는가","가비의 기행문 내용과 이어지는가","끝부분의 몫으로 까닭을 썼는가"]},"explanation":["여행 전체를 돌아봐요.","배운 것을 떠올려요.","끝부분의 몫을 써요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb),
('g5_1_kor_u2_review_b#25','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C32',4,'essay','teacher','견문과 감상을 가르는 물음이 무엇인지 쓰고, 「모래벌판을 지나」에서 견문과 감상을 하나씩 찾아 그 물음으로 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u2-C32","difficulty":4,"kind":"essay","stem":"견문과 감상을 가르는 물음이 무엇인지 쓰고, 「모래벌판을 지나」에서 견문과 감상을 하나씩 찾아 그 물음으로 설명하세요.","answer_guide":{"answer":"예: 그곳에 함께 있던 다른 사람도 똑같이 확인할 수 있는지 묻는다. 「마른 모래땅 바로 옆에 물이 고여 풀이 자라고 있었다」는 누구나 똑같이 볼 수 있으니 견문이다. 「바람이 이렇게 오래 일한다는 사실이 놀라웠다」는 같은 것을 보아도 사람마다 다르게 느낄 수 있으니 감상이다.","scoring_points":["가르는 물음을 썼는가","견문과 감상을 하나씩 찾았는가","물음으로 설명했는가"]},"explanation":["누구나 확인할 수 있나요?","사람마다 다를 수 있나요?","하나씩 찾아 설명해요."],"asset":{"type":"passage","lines":["지난 봄, 우리 가족은 태안 신두리로 여행을 떠났다. 바닷가 모래 언덕이 궁금했기 때문이다.","우리는 먼저 해안 사구 탐방로에 들어섰다. 발밑에서 모래가 자꾸 무너졌다.","이곳의 모래 언덕은 바람이 수천 년 동안 모래를 실어 나르며 만들어진 것이라고 한다.","바람이 이렇게 오래 일한다는 사실이 놀라웠다.","다음으로 언덕 너머 습지에 이르렀다. 마른 모래땅 바로 옆에 물이 고여 풀이 자라고 있었다.","돌아오는 길에 신발 속 모래를 털어 냈다.","발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다. 다음에는 바람이 센 계절에 다시 와 보고 싶다."],"title":"「모래벌판을 지나」"}}'::jsonb),
('g5_1_kor_u2_review_c#1','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C50',1,'mc','auto','「이」로 끝나는 낱말로만 묶은 것은 어느 것인가요?',ARRAY['K5-1-u2-X50']::text[],false,'{"seq":1,"concept":"K5-1-u2-C50","difficulty":1,"kind":"mc","stem":"「이」로 끝나는 낱말로만 묶은 것은 어느 것인가요?","options":[{"t":"틈틈이 · 곰곰이 · 가까이","correct":true},{"t":"틈틈이 · 조용히 · 가까이","mis":"K5-1-u2-X50"},{"t":"다행히 · 곰곰이 · 특별히","mis":"K5-1-u2-X50"},{"t":"도저히 · 솔직히 · 분명히","mis":"K5-1-u2-X50"}],"explanation":["「조용히」는 「히」예요.","「다행히」 · 「특별히」는 「히」예요.","모두 「이」로 끝나요."]}'::jsonb),
('g5_1_kor_u2_review_c#2','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C8',1,'mc','auto','앞으로의 일을 나타낸 문장은 어느 것인가요?',ARRAY['K5-1-u2-X05','K5-1-u2-X09']::text[],false,'{"seq":2,"concept":"K5-1-u2-C8","difficulty":1,"kind":"mc","stem":"앞으로의 일을 나타낸 문장은 어느 것인가요?","options":[{"t":"「다음 주에 고구마를 쪄서 나누어 먹을 것이다.」","correct":true},{"t":"「어제 고구마를 쪄서 나누어 먹었다.」","mis":"K5-1-u2-X05"},{"t":"「지금 고구마를 쪄서 나누어 먹는다.」","mis":"K5-1-u2-X05"},{"t":"「아까 고구마를 쪄서 나누어 먹었다.」","mis":"K5-1-u2-X09"}],"explanation":["지난 일이에요.","지금의 일이에요.","-ㄹ 것이 앞으로를 알려 줘요."]}'::jsonb),
('g5_1_kor_u2_review_c#3','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C15',1,'match','auto','오늘을 가운데에 두고 날짜를 가리키는 말을 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K5-1-u2-C15","difficulty":1,"kind":"match","stem":"오늘을 가운데에 두고 날짜를 가리키는 말을 이으세요.","pairs":[{"l":"어제","r":"하루 전"},{"l":"모레","r":"이틀 뒤"},{"l":"글피","r":"사흘 뒤"}],"mis":"K5-1-u2-X13","explanation":["오늘에서 세어요.","앞뒤를 나누어요.","어제 · 모레 · 글피를 차례로 세어요."]}'::jsonb),
('g5_1_kor_u2_review_c#4','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C16',1,'mc','auto','칠 일을 세는 우리말은 어느 것인가요?',ARRAY['K5-1-u2-X14']::text[],false,'{"seq":4,"concept":"K5-1-u2-C16","difficulty":1,"kind":"mc","stem":"칠 일을 세는 우리말은 어느 것인가요?","options":[{"t":"이레","correct":true},{"t":"엿새","mis":"K5-1-u2-X14"},{"t":"여드레","mis":"K5-1-u2-X14"},{"t":"열흘","mis":"K5-1-u2-X14"}],"explanation":["엿새는 육 일이에요.","여드레는 팔 일이에요.","칠 일은 이레예요."]}'::jsonb),
('g5_1_kor_u2_review_c#5','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C31',1,'mc','auto','가비의 기행문에서 감상에 해당하는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X28','K5-1-u2-X30']::text[],false,'{"seq":5,"concept":"K5-1-u2-C31","difficulty":1,"kind":"mc","stem":"가비의 기행문에서 감상에 해당하는 문장은 어느 것인가요?","options":[{"t":"「굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다.」","correct":true},{"t":"「우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.」","mis":"K5-1-u2-X28"},{"t":"「외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.」","mis":"K5-1-u2-X30"},{"t":"「추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.」","mis":"K5-1-u2-X28"}],"explanation":["다닌 곳이에요.","들은 것이에요.","「~같았다」에 마음이 드러나요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb),
('g5_1_kor_u2_review_c#6','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C37',1,'mc','auto','기행문의 처음 부분에 쓰기에 가장 알맞은 문장은 어느 것인가요?',ARRAY['K5-1-u2-X36','K5-1-u2-X38','K5-1-u2-X37']::text[],false,'{"seq":6,"concept":"K5-1-u2-C37","difficulty":1,"kind":"mc","stem":"기행문의 처음 부분에 쓰기에 가장 알맞은 문장은 어느 것인가요?","options":[{"t":"「외할머니께서 마을을 구경시켜 주신다고 해서 아침부터 마음이 들떴다.」","correct":true},{"t":"「다음에는 떡을 빚어 보고 싶다.」","mis":"K5-1-u2-X36"},{"t":"「마을이 나를 배웅하는 것 같았다.」","mis":"K5-1-u2-X38"},{"t":"「둑 아래로 벼가 펼쳐져 있었다.」","mis":"K5-1-u2-X37"}],"explanation":["끝에 어울려요.","끝에 어울려요.","떠나기 전의 기대와 기분이에요."]}'::jsonb),
('g5_1_kor_u2_review_c#7','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C34',1,'ox','auto','다닌 곳만 차례대로 적은 글은 일정표에 가까워요.',ARRAY['K5-1-u2-X33']::text[],false,'{"seq":7,"concept":"K5-1-u2-C34","difficulty":1,"kind":"ox","stem":"다닌 곳만 차례대로 적은 글은 일정표에 가까워요.","answer":"O","reason_options":[{"t":"여정만 있고 견문과 감상이 없기 때문에","correct":true},{"t":"다닌 곳이 많을수록 기행문이 되기 때문에","mis":"K5-1-u2-X33"}],"mis":"K5-1-u2-X33","explanation":["맞는 말이에요.","곳의 수로 정해지지 않아요.","여정만 있으면 일정표예요."]}'::jsonb),
('g5_1_kor_u2_review_c#8','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C45',1,'mc','auto','안내장에 공공 누리집의 사진을 넣을 때 사진 옆에 꼭 적어야 하는 것은 어느 것인가요?',ARRAY['K5-1-u2-X44']::text[],false,'{"seq":8,"concept":"K5-1-u2-C45","difficulty":1,"kind":"mc","stem":"안내장에 공공 누리집의 사진을 넣을 때 사진 옆에 꼭 적어야 하는 것은 어느 것인가요?","options":[{"t":"어디에서 가져왔는지 밝힌 출처","correct":true},{"t":"사진을 찍은 날의 내 기분","mis":"K5-1-u2-X44"},{"t":"내 이름만","mis":"K5-1-u2-X44"},{"t":"아무것도 적지 않는다","mis":"K5-1-u2-X44"}],"explanation":["출처가 아니에요.","내가 만든 사진이 아니에요.","가져온 곳을 밝혀요."]}'::jsonb),
('g5_1_kor_u2_review_c#9','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C12',2,'mc','auto','솔미의 글 ㉮를 바르게 고친 것은 어느 것인가요?',ARRAY['K5-1-u2-X10','K5-1-u2-X21']::text[],false,'{"seq":9,"concept":"K5-1-u2-C12","difficulty":2,"kind":"mc","stem":"솔미의 글 ㉮를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캤다.」","correct":true},{"t":"「지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캘 것이다.」","mis":"K5-1-u2-X10"},{"t":"「다음 금요일에 우리 반은 학교 텃밭에서 고구마를 캤다.」","mis":"K5-1-u2-X21"},{"t":"「지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캐겠다.」","mis":"K5-1-u2-X10"}],"explanation":["지난 일인데 앞일의 말끝이에요.","때의 말과 말끝이 어긋나요.","「지난 금요일」에 맞게 「캤다」로 고쳐요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb),
('g5_1_kor_u2_review_c#10','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C31',2,'match','auto','방앗간 대목의 문장과 요소를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C31","difficulty":2,"kind":"match","stem":"방앗간 대목의 문장과 요소를 이으세요.","pairs":[{"l":"개울을 건너 떡방앗간에 들렀다","r":"여정"},{"l":"명절 전 사흘 동안은 새벽부터 떡을 찐다고 하셨다","r":"견문"},{"l":"설에 다시 가면 떡을 빚어 보고 싶다","r":"감상"}],"mis":"K5-1-u2-X30","explanation":["다닌 곳이에요.","들은 설명이에요.","바람과 마음이에요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb),
('g5_1_kor_u2_review_c#11','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C50',2,'blank','auto','㉰의 빈칸에 알맞은 낱말을 고르세요.',ARRAY['K5-1-u2-X49']::text[],false,'{"seq":11,"concept":"K5-1-u2-C50","difficulty":2,"kind":"blank","stem":"㉰의 빈칸에 알맞은 낱말을 고르세요.","options":[{"t":"샅샅이","correct":true},{"t":"샅샅히","mis":"K5-1-u2-X49"},{"t":"삳삳이","mis":"K5-1-u2-X49"},{"t":"샅샅희","mis":"K5-1-u2-X49"}],"explanation":["「이」로 끝나는 무리예요.","받침을 확인해요.","「샅샅이」로 써요."],"asset":{"type":"passage","lines":["㉮ 동생이 잠든 방 앞을 (　　) 지나갔다.","㉯ 쉬는 시간마다 (　　) 여행 일기를 적었다.","㉰ 방 안을 (　　) 뒤졌지만 열쇠는 보이지 않았다.","㉱ 넘어졌는데 (　　) 크게 다치지는 않았다."],"title":"빈칸에 들어갈 낱말"}}'::jsonb),
('g5_1_kor_u2_review_c#12','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C17',2,'ox','auto','채온이네 계획의 「닷새 동안」은 행사를 여는 날짜를 가리키는 말이에요.',ARRAY['K5-1-u2-X15']::text[],false,'{"seq":12,"concept":"K5-1-u2-C17","difficulty":2,"kind":"ox","stem":"채온이네 계획의 「닷새 동안」은 행사를 여는 날짜를 가리키는 말이에요.","answer":"X","reason_options":[{"t":"「닷새」는 어느 날인지가 아니라 며칠 동안인지를 세는 말이기 때문에","correct":true},{"t":"「닷새」는 다섯째 날을 가리키는 날짜 말이기 때문에","mis":"K5-1-u2-X15"}],"mis":"K5-1-u2-X15","explanation":["날짜는 「월요일부터」예요.","「닷새」는 날의 개수예요.","며칠 동안인지를 세는 말이에요."],"asset":{"type":"passage","lines":["오늘은 월요일이다.","우리 반은 모레인 수요일부터 금요일까지 학급 문고 정리를 한다.","정리가 끝나면 그다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 연다."],"title":"채온이네 반의 계획"}}'::jsonb),
