('g5_1_kor_u3_L07_basic#7','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C37',2,'mc','auto','더 분명하게 표현한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X35']::text[],false,'{"seq":7,"concept":"K5-1-u3-C37","difficulty":2,"kind":"mc","stem":"더 분명하게 표현한 질문은 어느 것인가요?","options":[{"t":"나눔 시간에는 한 번에 몇 명이 발표하나요?","correct":true},{"t":"그건 좀 애매하지 않나요?","mis":"K5-1-u3-X35"},{"t":"어떻게 하실 건가요?","mis":"K5-1-u3-X35"},{"t":"그거 좀 이상하지 않아요?","mis":"K5-1-u3-X35"}],"explanation":["무엇이 애매한지 알 수 없어요.","무엇을 어떻게인지 흐릿해요.","무엇을 알고 싶은지 또렷해요."]}'::jsonb),
('g5_1_kor_u3_L07_basic#8','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C36',2,'mc','auto','다른 경우를 짚어 볼 때 질문을 여는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X34']::text[],false,'{"seq":8,"concept":"K5-1-u3-C36","difficulty":2,"kind":"mc","stem":"다른 경우를 짚어 볼 때 질문을 여는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"만약","correct":true},{"t":"누가","mis":"K5-1-u3-X34"},{"t":"언제","mis":"K5-1-u3-X34"},{"t":"어디에서","mis":"K5-1-u3-X34"}],"explanation":["사실을 또렷이 할 때 써요.","사실을 또렷이 할 때 써요.","「만약 … 라면」으로 다른 경우를 짚어요."]}'::jsonb),
('g5_1_kor_u3_L07_basic#9','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C38',2,'mc','auto','이 학급 회의에서 할 만한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X36']::text[],false,'{"seq":9,"concept":"K5-1-u3-C38","difficulty":2,"kind":"mc","stem":"이 학급 회의에서 할 만한 질문은 어느 것인가요?","options":[{"t":"두 주마다 바꾸면 청소가 서툴러지지 않을까요?","correct":true},{"t":"오늘 몇 교시까지 하나요?","mis":"K5-1-u3-X36"},{"t":"그 의견은 왜 그렇게 별로인가요?","mis":"K5-1-u3-X36"},{"t":"노아는 어느 동네에 사나요?","mis":"K5-1-u3-X36"}],"explanation":["회의 내용과 관계없어요.","깎아내리는 말이에요.","노아의 제안과 이어지는 질문이에요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"학급 회의를 시작하겠습니다. 오늘의 주제는 새로운 학급 규칙 정하기입니다. 손을 들고 발언권을 얻은 뒤에 말해 주세요."},{"who":"노아","text":"청소 구역을 두 주마다 바꾸면 좋겠습니다. 어떤 구역은 늘 힘들고 어떤 구역은 늘 수월해서 불만이 쌓입니다."},{"who":"시연","text":"한 달에 한 번 학급 나눔 시간을 열면 좋겠습니다. 서로 잘하는 것을 보여 줄 기회가 없습니다."},{"who":"준우","text":"별명 대신 이름을 부르면 좋겠습니다. 별명 때문에 기분이 상하는 친구가 있습니다."}]}}'::jsonb),
('g5_1_kor_u3_L07_basic#10','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C39',3,'ox','auto','한 질문은 반드시 한 가지 목적에만 들어가요.',ARRAY['K5-1-u3-X37']::text[],false,'{"seq":10,"concept":"K5-1-u3-C39","difficulty":3,"kind":"ox","stem":"한 질문은 반드시 한 가지 목적에만 들어가요.","answer":"X","reason_options":[{"t":"「이 행사로 어떤 변화를 기대하나요?」처럼 의도를 묻는 동시에 정보도 구하는 질문이 있기 때문에","correct":true},{"t":"질문의 목적은 늘 하나로 정해져 있기 때문에","mis":"K5-1-u3-X37"}],"mis":"K5-1-u3-X37","explanation":["두 목적에 걸치기도 해요.","갈래 맞히기가 목적이 아니에요.","무엇을 알고 싶은지가 먼저예요."]}'::jsonb),
('g5_1_kor_u3_L07_challenge#1','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C36',2,'mc','auto','까닭과 의도를 물을 때 질문을 여는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X34']::text[],false,'{"seq":1,"concept":"K5-1-u3-C36","difficulty":2,"kind":"mc","stem":"까닭과 의도를 물을 때 질문을 여는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"왜","correct":true},{"t":"만약","mis":"K5-1-u3-X34"},{"t":"언제","mis":"K5-1-u3-X34"},{"t":"누가","mis":"K5-1-u3-X34"}],"explanation":["다른 경우를 짚을 때 써요.","때를 또렷이 할 때 써요.","「왜」로 까닭과 의도를 물어요."]}'::jsonb),
('g5_1_kor_u3_L07_challenge#2','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C31',2,'mc','auto','준우는 무엇을 문제라고 보았나요?',ARRAY['K5-1-u3-X30','K5-1-u3-X29']::text[],false,'{"seq":2,"concept":"K5-1-u3-C31","difficulty":2,"kind":"mc","stem":"준우는 무엇을 문제라고 보았나요?","options":[{"t":"별명 때문에 기분이 상하는 친구가 있다는 것","correct":true},{"t":"청소 구역이 고르지 않다는 것","mis":"K5-1-u3-X30"},{"t":"잘하는 것을 보여 줄 기회가 없다는 것","mis":"K5-1-u3-X30"},{"t":"회의 시간이 짧다는 것","mis":"K5-1-u3-X29"}],"explanation":["노아가 본 문제예요.","시연이가 본 문제예요.","준우는 상한 마음을 까닭으로 들었어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"학급 회의를 시작하겠습니다. 오늘의 주제는 새로운 학급 규칙 정하기입니다. 손을 들고 발언권을 얻은 뒤에 말해 주세요."},{"who":"노아","text":"청소 구역을 두 주마다 바꾸면 좋겠습니다. 어떤 구역은 늘 힘들고 어떤 구역은 늘 수월해서 불만이 쌓입니다."},{"who":"시연","text":"한 달에 한 번 학급 나눔 시간을 열면 좋겠습니다. 서로 잘하는 것을 보여 줄 기회가 없습니다."},{"who":"준우","text":"별명 대신 이름을 부르면 좋겠습니다. 별명 때문에 기분이 상하는 친구가 있습니다."}]}}'::jsonb),
('g5_1_kor_u3_L07_challenge#3','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C35',3,'mc','auto','등대 발표를 듣고 한 질문 「등대에 대해 더 알고 싶으면 어떤 자료를 찾아보면 좋을까요?」의 목적은 무엇인가요?',ARRAY['K5-1-u3-X33','K5-1-u3-X36']::text[],false,'{"seq":3,"concept":"K5-1-u3-C35","difficulty":3,"kind":"mc","stem":"등대 발표를 듣고 한 질문 「등대에 대해 더 알고 싶으면 어떤 자료를 찾아보면 좋을까요?」의 목적은 무엇인가요?","options":[{"t":"대안이나 정보를 찾기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X33"},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X33"},{"t":"발표자를 깎아내리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["까닭을 묻지 않아요.","발표 속 뜻을 묻지 않아요.","발표에 없던 정보를 새로 구해요."],"asset":{"type":"passage","lines":["저는 우리 지역 등대에 대해 발표하겠습니다.","등대는 밤바다에서 배가 길을 찾도록 빛을 보내는 건물입니다.","우리 지역 등대는 백 년이 넘었고, 처음에는 기름으로 불을 밝혔다고 합니다.","지금은 전기를 씁니다.","등대마다 빛이 깜빡이는 간격이 달라서 배가 어느 등대인지 알아볼 수 있습니다.","이상으로 발표를 마치겠습니다."],"title":"발표 「우리 지역 등대」"}}'::jsonb),
