('g5_1_kor_u3_review_a#4','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C33',1,'mc','auto','율비에게 「복도 걷기 도우미를 두자고 하신 까닭이 무엇인가요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X31','K5-1-u3-X36']::text[],false,'{"seq":4,"concept":"K5-1-u3-C33","difficulty":1,"kind":"mc","stem":"율비에게 「복도 걷기 도우미를 두자고 하신 까닭이 무엇인가요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"의도를 파악하기 위해서","correct":true},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X31"},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X31"},{"t":"율비를 깎아내리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["뜻을 묻지 않아요.","다른 방법을 구하지 않아요.","왜 제안했는지 묻고 있어요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb),
('g5_1_kor_u3_review_a#5','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C13',1,'mc','auto','「우리 지역 여름 축제」 발표 내용 ②를 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X12','K5-1-u3-X08']::text[],false,'{"seq":5,"concept":"K5-1-u3-C13","difficulty":1,"kind":"mc","stem":"「우리 지역 여름 축제」 발표 내용 ②를 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"표나 그래프","correct":true},{"t":"영상","mis":"K5-1-u3-X12"},{"t":"그림이나 사진","mis":"K5-1-u3-X12"},{"t":"글","mis":"K5-1-u3-X08"}],"explanation":["움직임이 아니에요.","모습이 아니에요.","해마다 달라진 사람 수는 표나 그래프예요."],"asset":{"type":"passage","lines":["① 축제의 뜻과 시작된 해","② 해마다 다녀간 사람 수","③ 축제 무대 공연 장면","④ 축제 마당의 모습"],"title":"「우리 지역 여름 축제」 발표 내용"}}'::jsonb),
('g5_1_kor_u3_review_a#6','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C15',1,'mc','auto','지슬이가 발표 내용 ④에 쓸 단락은 어느 것인가요?',ARRAY['K5-1-u3-X14']::text[],false,'{"seq":6,"concept":"K5-1-u3-C15","difficulty":1,"kind":"mc","stem":"지슬이가 발표 내용 ④에 쓸 단락은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"K5-1-u3-X14"},{"t":"㉰","mis":"K5-1-u3-X14"},{"t":"㉱","mis":"K5-1-u3-X14"}],"explanation":["쉼터의 뜻과 생긴 곳이에요.","마을 사람들이 하는 일이에요.","큰고니의 생김새가 담겼어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb),
('g5_1_kor_u3_review_a#7','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C44',1,'mc','auto','「담 너머」의 인물에게 할 만한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X42']::text[],false,'{"seq":7,"concept":"K5-1-u3-C44","difficulty":1,"kind":"mc","stem":"「담 너머」의 인물에게 할 만한 질문은 어느 것인가요?","options":[{"t":"「담 너머를 왜 그렇게 궁금해했나요?」","correct":true},{"t":"「담의 높이는 몇 센티미터인가요?」","mis":"K5-1-u3-X42"},{"t":"「나비의 날개는 무슨 색인가요?」","mis":"K5-1-u3-X42"},{"t":"「두더지는 몇 살인가요?」","mis":"K5-1-u3-X42"}],"explanation":["글 안에서 생각해 볼 수 없어요.","글과 관계없는 사실이에요.","인물의 마음으로 들어가는 질문이에요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb),
('g5_1_kor_u3_review_a#8','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C27',1,'mc','auto','지슬이의 시작하는 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X26']::text[],false,'{"seq":8,"concept":"K5-1-u3-C27","difficulty":1,"kind":"mc","stem":"지슬이의 시작하는 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"K5-1-u3-X26"},{"t":"나","mis":"K5-1-u3-X26"},{"t":"세 가지 모두 똑같이 알맞다","mis":"K5-1-u3-X26"}],"explanation":["핑계로 시작했어요.","인사 없이 바로 본론이에요.","주제와 조사한 까닭이 담겼어요."],"asset":{"type":"speech","turns":[{"who":"가","text":"음…… 준비를 많이 못 했는데 그냥 해 보겠습니다."},{"who":"나","text":"철새는 계절에 따라 사는 곳을 옮기는 새로, 마을 저수지는 물이 얕아……."},{"who":"다","text":"안녕하세요. 저는 우리 마을 철새 쉼터에 대해 발표할 지슬입니다. 겨울 방학에 저수지에서 새 떼를 본 뒤로 궁금해져 조사해 보았습니다."}]}}'::jsonb),
