('g5_1_kor_u3_review_a#14','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C50',2,'mc','auto','지슬이가 「해마다 쉼터를 찾아온 새의 수」를 조사할 때 가장 믿을 수 있는 자료는 어느 것인가요?',ARRAY['K5-1-u3-X48']::text[],false,'{"seq":14,"concept":"K5-1-u3-C50","difficulty":2,"kind":"mc","stem":"지슬이가 「해마다 쉼터를 찾아온 새의 수」를 조사할 때 가장 믿을 수 있는 자료는 어느 것인가요?","options":[{"t":"지역 환경 기관 누리집에 올라온, 낸 때가 적힌 조사 자료","correct":true},{"t":"누가 썼는지 모르는 게시글","mis":"K5-1-u3-X48"},{"t":"지나가던 사람에게 들은 말","mis":"K5-1-u3-X48"},{"t":"새를 좋아하는 친구의 짐작","mis":"K5-1-u3-X48"}],"explanation":["쓴 사람을 알 수 없어요.","확인되지 않은 말이에요.","만든 곳과 때가 드러나요."]}'::jsonb),
('g5_1_kor_u3_review_a#15','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C14',2,'ox','auto','지슬이의 발표 내용 ③은 영상이 없으면 발표할 수 없어요.',ARRAY['K5-1-u3-X13']::text[],false,'{"seq":15,"concept":"K5-1-u3-C14","difficulty":2,"kind":"ox","stem":"지슬이의 발표 내용 ③은 영상이 없으면 발표할 수 없어요.","answer":"X","reason_options":[{"t":"날아오르기 전과 뒤의 사진을 나란히 보여 주는 것처럼 다른 유형으로도 전할 수 있기 때문에","correct":true},{"t":"한 내용에는 정해진 유형 하나만 쓸 수 있기 때문에","mis":"K5-1-u3-X13"}],"mis":"K5-1-u3-X13","explanation":["다른 유형으로도 전할 수 있어요.","정답 유형이 하나로 정해져 있지 않아요.","내용을 잘 전하는가가 중요해요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb),
('g5_1_kor_u3_review_a#16','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C53',2,'mc','auto','「우리 주변에서 바꾸어 쓸 말을 찾아봅니다」에 맞게 말한 것은 어느 것인가요?',ARRAY['K5-1-u3-X51','K5-1-u3-X53']::text[],false,'{"seq":16,"concept":"K5-1-u3-C53","difficulty":2,"kind":"mc","stem":"「우리 주변에서 바꾸어 쓸 말을 찾아봅니다」에 맞게 말한 것은 어느 것인가요?","options":[{"t":"「누군가를 낮추거나 빠뜨리는 말은 함께함을 담은 말로 바꾸어 써야겠어.」","correct":true},{"t":"「뜻만 통하면 아무 말이나 괜찮아.」","mis":"K5-1-u3-X51"},{"t":"「오래 써 온 말은 바꿀 필요가 없어.」","mis":"K5-1-u3-X53"},{"t":"「짧은 말이 늘 더 좋아.」","mis":"K5-1-u3-X51"}],"explanation":["낱말에는 태도가 담겨요.","오래 썼어도 고칠 말이 있어요.","누구를 어떻게 부르는지 살펴요."]}'::jsonb),
('g5_1_kor_u3_review_a#17','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C52',3,'mc','auto','「자료를 선별하여 발표하기」와 「궁금한 내용 질문하기」가 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X50','K5-1-u3-X49']::text[],false,'{"seq":17,"concept":"K5-1-u3-C52","difficulty":3,"kind":"mc","stem":"「자료를 선별하여 발표하기」와 「궁금한 내용 질문하기」가 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"발표하는 사람은 예상 질문을 준비하고, 듣는 사람은 자료와 내용을 집중해 들으며 질문을 만든다","correct":true},{"t":"발표하는 사람은 질문을 받지 않고, 듣는 사람은 조용히 있는다","mis":"K5-1-u3-X50"},{"t":"발표 공부와 질문 공부는 서로 관계없다","mis":"K5-1-u3-X50"},{"t":"질문은 이야기를 읽을 때만 한다","mis":"K5-1-u3-X49"}],"explanation":["질문이 빠졌어요.","두 공부는 한 짝이에요.","발표와 질문이 맞물려요."]}'::jsonb),
('g5_1_kor_u3_review_a#18','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C23',3,'mc','auto','지슬이가 「우리 마을 철새 쉼터」를 주제로 고른 것이 알맞은 까닭은 무엇인가요?',ARRAY['K5-1-u3-X22','K5-1-u3-X01']::text[],false,'{"seq":18,"concept":"K5-1-u3-C23","difficulty":3,"kind":"mc","stem":"지슬이가 「우리 마을 철새 쉼터」를 주제로 고른 것이 알맞은 까닭은 무엇인가요?","options":[{"t":"너무 넓지도 좁지도 않아 짧은 발표 시간에 자료를 모아 다루기 좋기 때문이다","correct":true},{"t":"세상의 모든 새를 다룰 수 있기 때문이다","mis":"K5-1-u3-X22"},{"t":"큰고니 깃털 한 개만 다루기 때문이다","mis":"K5-1-u3-X22"},{"t":"아무 자료도 필요 없기 때문이다","mis":"K5-1-u3-X01"}],"explanation":["너무 넓은 주제가 아니에요.","너무 좁은 주제가 아니에요.","알맞은 크기의 주제예요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb),
('g5_1_kor_u3_review_a#19','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C42',3,'mc','auto','「창틀의 화분」의 흐름을 차례대로 바르게 간추린 것은 어느 것인가요?',ARRAY['K5-1-u3-X40']::text[],false,'{"seq":19,"concept":"K5-1-u3-C42","difficulty":3,"kind":"mc","stem":"「창틀의 화분」의 흐름을 차례대로 바르게 간추린 것은 어느 것인가요?","options":[{"t":"촉촉한 흙의 수수께끼 → 「그냥 내가 주는 거야」 → 전학 간 친구와의 약속 → 함께 물 주기와 꽃","correct":true},{"t":"전학 간 친구와의 약속 → 촉촉한 흙의 수수께끼 → 함께 물 주기와 꽃 → 「그냥 내가 주는 거야」","mis":"K5-1-u3-X40"},{"t":"함께 물 주기와 꽃 → 「그냥 내가 주는 거야」 → 촉촉한 흙의 수수께끼 → 전학 간 친구와의 약속","mis":"K5-1-u3-X40"},{"t":"촉촉한 흙의 수수께끼 → 함께 물 주기와 꽃 → 전학 간 친구와의 약속 → 「그냥 내가 주는 거야」","mis":"K5-1-u3-X40"}],"explanation":["약속은 셋째에 드러나요.","꽃은 맨 끝이에요.","일어난 차례대로 간추렸어요."]}'::jsonb),
('g5_1_kor_u3_review_a#20','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C28',3,'mc','auto','지슬이의 발표에서 나올 법한 예상 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X27']::text[],false,'{"seq":20,"concept":"K5-1-u3-C28","difficulty":3,"kind":"mc","stem":"지슬이의 발표에서 나올 법한 예상 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「갈대 울타리를 치면 새들이 왜 덜 놀라나요?」","correct":true},{"t":"「지슬이는 무슨 음식을 좋아하나요?」","mis":"K5-1-u3-X27"},{"t":"「빵집은 몇 시에 문을 여나요?」","mis":"K5-1-u3-X27"},{"t":"「내일 날씨는 어떤가요?」","mis":"K5-1-u3-X27"}],"explanation":["발표와 관계없어요.","발표에서 뺀 내용이에요.","발표 내용 ①과 ㉰에서 나올 질문이에요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb),
('g5_1_kor_u3_review_a#21','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C39',3,'ox','auto','「쉼터를 만들어서 마을에 어떤 변화가 생기기를 바라나요?」는 한 가지 목적으로만 나눌 수 있어요.',ARRAY['K5-1-u3-X37']::text[],false,'{"seq":21,"concept":"K5-1-u3-C39","difficulty":3,"kind":"ox","stem":"「쉼터를 만들어서 마을에 어떤 변화가 생기기를 바라나요?」는 한 가지 목적으로만 나눌 수 있어요.","answer":"X","reason_options":[{"t":"왜 쉼터를 만들었는지 의도를 묻는 동시에 앞으로의 변화에 대한 정보도 구하는 질문이기 때문에","correct":true},{"t":"질문은 언제나 한 가지 목적에만 들어가기 때문에","mis":"K5-1-u3-X37"}],"mis":"K5-1-u3-X37","explanation":["두 목적에 걸쳐요.","갈래 맞히기가 목적이 아니에요.","무엇을 알고 싶은지가 먼저예요."]}'::jsonb),
('g5_1_kor_u3_review_a#22','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C7',3,'mc','auto','지슬이가 큰고니에 대해 깊이 있는 답을 듣고 싶을 때 알맞은 조사 방법과 그 특징을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u3-X06','K5-1-u3-X48']::text[],false,'{"seq":22,"concept":"K5-1-u3-C7","difficulty":3,"kind":"mc","stem":"지슬이가 큰고니에 대해 깊이 있는 답을 듣고 싶을 때 알맞은 조사 방법과 그 특징을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"새를 연구하는 전문가에게 묻기 — 깊이 있는 답을 들을 수 있으나 만나기 어렵다","correct":true},{"t":"인터넷에서 찾기 — 늘 사실이라 확인할 필요가 없다","mis":"K5-1-u3-X06"},{"t":"책에서 찾기 — 언제나 가장 새로운 정보가 있다","mis":"K5-1-u3-X06"},{"t":"친구에게 묻기 — 전해 들은 말이라도 그대로 믿을 수 있다","mis":"K5-1-u3-X48"}],"explanation":["인터넷은 사실인지 확인해야 해요.","책은 최신 정보가 적을 수 있어요.","전문가에게서 깊이 있는 답을 들어요."]}'::jsonb),
('g5_1_kor_u3_review_a#23','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C16',4,'essay','teacher','지슬이의 글 자료에서 발표에 쓸 단락과 뺄 단락을 고르고, 쓸 단락 하나를 발표 화면에 넣을 수 있게 요약하세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u3-C16","difficulty":4,"kind":"essay","stem":"지슬이의 글 자료에서 발표에 쓸 단락과 뺄 단락을 고르고, 쓸 단락 하나를 발표 화면에 넣을 수 있게 요약하세요.","answer_guide":{"answer":"예: 쓸 단락 — ㉮ · ㉯ · ㉰, 뺄 단락 — ㉱(빵집은 철새 쉼터와 관계없다). ㉰ 요약 — 겨울마다 볍씨를 뿌려 먹이를 나눔 · 새가 놀라지 않게 갈대 울타리를 침.","scoring_points":["쓸 단락과 뺄 단락을 바르게 골랐는가","뺀 까닭을 썼는가","필요한 내용만 남겨 요약했는가"]},"explanation":["발표 주제와 이어지는지 봐요.","관계없는 것은 덜어요.","필요한 것만 남겨요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb),
('g5_1_kor_u3_review_a#24','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C54',4,'essay','teacher','「알맞은 낱말 고르기」의 ㉮~㉱에서 더 바람직한 낱말을 하나씩 고르고, 그 가운데 둘을 골라 왜 바람직한지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u3-C54","difficulty":4,"kind":"essay","stem":"「알맞은 낱말 고르기」의 ㉮~㉱에서 더 바람직한 낱말을 하나씩 고르고, 그 가운데 둘을 골라 왜 바람직한지 쓰세요.","answer_guide":{"answer":"예: ㉮ 협력 · ㉯ 반려 · ㉰ 살구색 · ㉱ 학부모. 「반려」는 동물을 즐기는 대상이 아니라 함께 사는 동무로 여기는 태도를 담는다. 「학부모」는 아버지와 형만이 아니라 학생의 보호자를 두루 가리켜 누군가를 빠뜨리지 않는다.","scoring_points":["네 낱말을 바르게 골랐는가","둘을 골라 까닭을 썼는가","낱말에 담긴 태도로 설명했는가"]},"explanation":["누구를 어떻게 부르는지 봐요.","함께함을 담은 말을 골라요.","빠뜨리는 사람이 없는지 봐요."],"asset":{"type":"passage","lines":["㉮ 시장 상인회와 동네 마트가 (협력 / 하청)하여 장보기 행사를 열었다.","㉯ 이모는 강아지를 (반려 / 애완)동물로 기르며 가족처럼 여긴다.","㉰ 미술 시간에 (살구색 / 살색) 물감으로 얼굴을 칠했다.","㉱ 오늘 학교에서 (학부모 / 학부형) 공개 수업이 열린다."],"title":"알맞은 낱말 고르기"}}'::jsonb),
('g5_1_kor_u3_review_a#25','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C52',4,'essay','teacher','이 단원에서 배운 「자료를 선별하여 발표하기」와 「궁금한 내용 질문하기」가 어떻게 이어지는지 지슬이의 발표를 예로 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u3-C52","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「자료를 선별하여 발표하기」와 「궁금한 내용 질문하기」가 어떻게 이어지는지 지슬이의 발표를 예로 들어 쓰세요.","answer_guide":{"answer":"예: 지슬이는 철새 쉼터 발표에 맞는 자료를 골라 요약하고, 새의 수가 줄어든 까닭 같은 예상 질문을 미리 준비한다. 듣는 친구들은 지슬이의 자료와 말을 집중해 듣고 「큰고니 사진은 어디에서 찾았나요?」처럼 목적에 맞게 분명히 묻는다. 질문과 답이 오가면서 발표가 완성되므로 두 공부는 한 짝이다.","scoring_points":["발표하는 쪽의 할 일을 썼는가","듣고 질문하는 쪽의 할 일을 썼는가","둘이 이어지는 까닭을 지슬이의 예로 썼는가"]},"explanation":["발표하는 사람은 무엇을 준비하나요?","듣는 사람은 무엇을 하나요?","두 쪽이 어떻게 만나나요?"]}'::jsonb),
('g5_1_kor_u3_review_b#1','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C54',1,'mc','auto','㉮의 빈칸에 들어갈 더 바람직한 낱말은 어느 것인가요?',ARRAY['K5-1-u3-X52','K5-1-u3-X51']::text[],false,'{"seq":1,"concept":"K5-1-u3-C54","difficulty":1,"kind":"mc","stem":"㉮의 빈칸에 들어갈 더 바람직한 낱말은 어느 것인가요?","options":[{"t":"협력","correct":true},{"t":"하청","mis":"K5-1-u3-X52"},{"t":"지시","mis":"K5-1-u3-X51"},{"t":"명령","mis":"K5-1-u3-X51"}],"explanation":["아래에서 일을 맡는다는 말이에요.","위아래를 가르는 말이에요.","힘을 합하여 서로 돕는다는 말이에요."],"asset":{"type":"passage","lines":["㉮ 시장 상인회와 동네 마트가 (협력 / 하청)하여 장보기 행사를 열었다.","㉯ 이모는 강아지를 (반려 / 애완)동물로 기르며 가족처럼 여긴다.","㉰ 미술 시간에 (살구색 / 살색) 물감으로 얼굴을 칠했다.","㉱ 오늘 학교에서 (학부모 / 학부형) 공개 수업이 열린다."],"title":"알맞은 낱말 고르기"}}'::jsonb),
