('g5_1_kor_u3_review_b#3','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C13',1,'mc','auto','지슬이의 발표 내용 ②를 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X12','K5-1-u3-X08']::text[],false,'{"seq":3,"concept":"K5-1-u3-C13","difficulty":1,"kind":"mc","stem":"지슬이의 발표 내용 ②를 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"표나 그래프","correct":true},{"t":"영상","mis":"K5-1-u3-X12"},{"t":"그림이나 사진","mis":"K5-1-u3-X12"},{"t":"글","mis":"K5-1-u3-X08"}],"explanation":["움직임이 아니에요.","생김새가 아니에요.","해마다 달라진 수치는 표나 그래프예요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb),
('g5_1_kor_u3_review_b#4','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C34',1,'mc','auto','하설이에게 「정리 당번은 책을 꽂기만 하나요, 찢어진 책도 고치나요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X32','K5-1-u3-X36']::text[],false,'{"seq":4,"concept":"K5-1-u3-C34","difficulty":1,"kind":"mc","stem":"하설이에게 「정리 당번은 책을 꽂기만 하나요, 찢어진 책도 고치나요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"명료하게 이해하기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X32"},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X32"},{"t":"회의를 빨리 끝내기 위해서","mis":"K5-1-u3-X36"}],"explanation":["까닭을 묻지 않아요.","다른 방법을 구하지 않아요.","당번이 하는 일을 또렷이 하려는 질문이에요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb),
('g5_1_kor_u3_review_b#5','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C13',1,'mc','auto','「우리 지역 여름 축제」 발표 내용 ③을 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X12','K5-1-u3-X13']::text[],false,'{"seq":5,"concept":"K5-1-u3-C13","difficulty":1,"kind":"mc","stem":"「우리 지역 여름 축제」 발표 내용 ③을 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"영상","correct":true},{"t":"표나 그래프","mis":"K5-1-u3-X12"},{"t":"글","mis":"K5-1-u3-X12"},{"t":"그림이나 사진","mis":"K5-1-u3-X13"}],"explanation":["수치가 아니에요.","설명이 아니에요.","공연은 움직임이라 영상이 잘 보여 줘요."],"asset":{"type":"passage","lines":["① 축제의 뜻과 시작된 해","② 해마다 다녀간 사람 수","③ 축제 무대 공연 장면","④ 축제 마당의 모습"],"title":"「우리 지역 여름 축제」 발표 내용"}}'::jsonb),
('g5_1_kor_u3_review_b#6','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C17',1,'mc','auto','지슬이의 글 자료에서 발표 주제와 관계없어 빼야 할 단락은 어느 것인가요?',ARRAY['K5-1-u3-X16']::text[],false,'{"seq":6,"concept":"K5-1-u3-C17","difficulty":1,"kind":"mc","stem":"지슬이의 글 자료에서 발표 주제와 관계없어 빼야 할 단락은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"K5-1-u3-X16"},{"t":"㉯","mis":"K5-1-u3-X16"},{"t":"㉰","mis":"K5-1-u3-X16"}],"explanation":["발표 내용 ①과 이어져요.","발표 내용 ④와 이어져요.","빵집은 철새 쉼터와 관계없어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb),
('g5_1_kor_u3_review_b#7','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C34',1,'mc','auto','「담 너머」를 읽고 「내가 세우는 담이란 어떤 뜻인가요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X32','K5-1-u3-X36']::text[],false,'{"seq":7,"concept":"K5-1-u3-C34","difficulty":1,"kind":"mc","stem":"「담 너머」를 읽고 「내가 세우는 담이란 어떤 뜻인가요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"명료하게 이해하기 위해서","correct":true},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X32"},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X32"},{"t":"나비를 놀리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["다른 방법을 구하지 않아요.","왜 했는지보다 말의 뜻을 물어요.","흐릿한 말의 뜻을 또렷이 하려는 질문이에요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb),
('g5_1_kor_u3_review_b#8','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C27',1,'mc','auto','지슬이의 시작하는 말 「가」가 알맞지 않은 까닭은 무엇인가요?',ARRAY['K5-1-u3-X26']::text[],false,'{"seq":8,"concept":"K5-1-u3-C27","difficulty":1,"kind":"mc","stem":"지슬이의 시작하는 말 「가」가 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"무엇을 왜 발표하는지 없이 핑계부터 댔기 때문이다","correct":true},{"t":"너무 길기 때문이다","mis":"K5-1-u3-X26"},{"t":"질문 안내가 빠졌기 때문이다","mis":"K5-1-u3-X26"},{"t":"철새를 설명했기 때문이다","mis":"K5-1-u3-X26"}],"explanation":["길이 때문이 아니에요.","질문 안내는 끝맺는 말에 담아요.","주제와 까닭이 없어요."],"asset":{"type":"speech","turns":[{"who":"가","text":"음…… 준비를 많이 못 했는데 그냥 해 보겠습니다."},{"who":"나","text":"철새는 계절에 따라 사는 곳을 옮기는 새로, 마을 저수지는 물이 얕아……."},{"who":"다","text":"안녕하세요. 저는 우리 마을 철새 쉼터에 대해 발표할 지슬입니다. 겨울 방학에 저수지에서 새 떼를 본 뒤로 궁금해져 조사해 보았습니다."}]}}'::jsonb),
('g5_1_kor_u3_review_b#9','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C18',2,'mc','auto','㉯의 「월동한다」를 쉬운 말로 알맞게 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u3-X17']::text[],false,'{"seq":9,"concept":"K5-1-u3-C18","difficulty":2,"kind":"mc","stem":"㉯의 「월동한다」를 쉬운 말로 알맞게 바꾼 것은 어느 것인가요?","options":[{"t":"겨울을 난다","correct":true},{"t":"달을 본다","mis":"K5-1-u3-X17"},{"t":"겨울에 떠난다","mis":"K5-1-u3-X17"},{"t":"잠만 잔다","mis":"K5-1-u3-X17"}],"explanation":["낱자의 뜻만 보면 안 돼요.","머무는 것이지 떠나는 것이 아니에요.","겨울을 지낸다는 뜻 그대로예요."],"asset":{"type":"passage","lines":["㉮ 철새가 도래하는 때는 늦가을이다.","㉯ 큰고니는 이 저수지에서 월동한다.","㉰ 해마다 찾아오는 새의 개체 수가 감소하고 있다."],"title":"지슬이의 발표 원고 가운데"}}'::jsonb),
('g5_1_kor_u3_review_b#10','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C26',2,'mc','auto','지슬이의 첫 화면으로 발표하면 어떤 일이 생길까요?',ARRAY['K5-1-u3-X25']::text[],false,'{"seq":10,"concept":"K5-1-u3-C26","difficulty":2,"kind":"mc","stem":"지슬이의 첫 화면으로 발표하면 어떤 일이 생길까요?","options":[{"t":"듣는 사람이 지슬이를 보지 않고 화면의 글만 읽게 된다","correct":true},{"t":"듣는 사람이 지슬이의 말에 더 집중한다","mis":"K5-1-u3-X25"},{"t":"발표가 짧고 분명해진다","mis":"K5-1-u3-X25"},{"t":"자료가 많아 더 좋은 발표가 된다","mis":"K5-1-u3-X25"}],"explanation":["글이 많으면 화면만 봐요.","오히려 흐려져요.","자료는 많을수록 좋은 것이 아니에요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb),
('g5_1_kor_u3_review_b#11','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C37',2,'mc','auto','하설이의 제안에 대해 더 분명하게 표현한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X35']::text[],false,'{"seq":11,"concept":"K5-1-u3-C37","difficulty":2,"kind":"mc","stem":"하설이의 제안에 대해 더 분명하게 표현한 질문은 어느 것인가요?","options":[{"t":"「정리 당번은 무슨 요일에 몇 명이 하나요?」","correct":true},{"t":"「그거 좀 그렇지 않아요?」","mis":"K5-1-u3-X35"},{"t":"「어떻게 되는 건가요?」","mis":"K5-1-u3-X35"},{"t":"「좀 애매한데요?」","mis":"K5-1-u3-X35"}],"explanation":["무엇이 궁금한지 알 수 없어요.","흐릿해요.","무엇을 알고 싶은지 또렷해요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb),
('g5_1_kor_u3_review_b#12','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C40',2,'mc','auto','「창틀의 화분」 ①에서 한율이가 궁금해할 만한 것은 무엇인가요?',ARRAY['K5-1-u3-X42']::text[],false,'{"seq":12,"concept":"K5-1-u3-C40","difficulty":2,"kind":"mc","stem":"「창틀의 화분」 ①에서 한율이가 궁금해할 만한 것은 무엇인가요?","options":[{"t":"누구 것인지 모르는 화분의 흙이 아침마다 촉촉한 것","correct":true},{"t":"창틀이 무슨 색인지","mis":"K5-1-u3-X42"},{"t":"교실이 몇 층인지","mis":"K5-1-u3-X42"},{"t":"물병이 얼마인지","mis":"K5-1-u3-X42"}],"explanation":["이야기와 관계없어요.","이야기와 관계없어요.","까닭이 적히지 않은 일이에요."],"asset":{"type":"passage","lines":["한율이네 교실 창틀 끝에는 작은 화분 하나가 있다.","누구 것인지 아무도 몰랐다. 그런데 아침마다 흙이 촉촉했다.","어느 날 일찍 학교에 온 한율이는 려원이가 물병으로 그 화분에","물을 주는 것을 보았다. 려원이는 잎에 앉은 먼지를 손끝으로","하나하나 닦아 냈다."],"title":"이야기 「창틀의 화분」 ①"}}'::jsonb),
('g5_1_kor_u3_review_b#13','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C35',2,'mc','auto','한율이에게 「화분에 꽃이 더 잘 피게 하려면 무엇을 더 해 볼 수 있을까요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X33','K5-1-u3-X36']::text[],false,'{"seq":13,"concept":"K5-1-u3-C35","difficulty":2,"kind":"mc","stem":"한율이에게 「화분에 꽃이 더 잘 피게 하려면 무엇을 더 해 볼 수 있을까요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"대안이나 정보를 찾기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X33"},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X33"},{"t":"한율이를 놀리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["까닭을 묻지 않아요.","뜻을 묻지 않아요.","더 해 볼 방법을 구하는 질문이에요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb),
('g5_1_kor_u3_review_b#14','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C10',2,'mc','auto','지슬이가 인터넷에서 찾은 철새 정보를 믿을 수 있는지 확인하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X09']::text[],false,'{"seq":14,"concept":"K5-1-u3-C10","difficulty":2,"kind":"mc","stem":"지슬이가 인터넷에서 찾은 철새 정보를 믿을 수 있는지 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 내용을 다른 곳에서도 찾아 견주어 본다","correct":true},{"t":"처음 찾은 글을 그대로 쓴다","mis":"K5-1-u3-X09"},{"t":"글쓴이가 자신 있게 썼으면 믿는다","mis":"K5-1-u3-X09"},{"t":"사진이 많은 글을 고른다","mis":"K5-1-u3-X09"}],"explanation":["한 곳만 보면 틀릴 수 있어요.","자신 있는 말투와 사실은 달라요.","여러 곳에서 확인해요."]}'::jsonb),
('g5_1_kor_u3_review_b#15','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C14',2,'mc','auto','지슬이의 발표 내용 ①을 더 잘 전하려면 어떻게 하면 좋을까요?',ARRAY['K5-1-u3-X12','K5-1-u3-X16','K5-1-u3-X13']::text[],false,'{"seq":15,"concept":"K5-1-u3-C14","difficulty":2,"kind":"mc","stem":"지슬이의 발표 내용 ①을 더 잘 전하려면 어떻게 하면 좋을까요?","options":[{"t":"글로 설명하면서 저수지 사진을 함께 보여 준다","correct":true},{"t":"글은 빼고 그래프만 보여 준다","mis":"K5-1-u3-X12"},{"t":"관계없는 빵집 사진을 넣는다","mis":"K5-1-u3-X16"},{"t":"정해진 유형이 글이니 다른 것은 쓰지 않는다","mis":"K5-1-u3-X13"}],"explanation":["그래프는 수치에 알맞아요.","주제와 관계없어요.","한 내용에 여러 유형을 함께 쓸 수 있어요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb),
('g5_1_kor_u3_review_b#16','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C55',2,'mc','auto','「살색」을 「살구색」으로 고쳐 쓰는 까닭은 무엇인가요?',ARRAY['K5-1-u3-X51','K5-1-u3-X53']::text[],false,'{"seq":16,"concept":"K5-1-u3-C55","difficulty":2,"kind":"mc","stem":"「살색」을 「살구색」으로 고쳐 쓰는 까닭은 무엇인가요?","options":[{"t":"사람마다 피부색이 다른데 한 가지 색만 「살」의 색이라고 하면 누군가를 빠뜨리기 때문이다","correct":true},{"t":"「살구색」이 글자 수가 더 많기 때문이다","mis":"K5-1-u3-X51"},{"t":"「살색」은 맞춤법이 틀린 말이기 때문이다","mis":"K5-1-u3-X53"},{"t":"어른들이 쓰지 말라고 했기 때문이다","mis":"K5-1-u3-X53"}],"explanation":["글자 수와는 관계없어요.","맞춤법의 문제가 아니에요.","빠뜨리는 사람이 없게 고쳐요."]}'::jsonb),
('g5_1_kor_u3_review_b#17','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C52',3,'ox','auto','발표를 잘 준비한 사람은 질문을 받을 준비도 함께 해요.',ARRAY['K5-1-u3-X50']::text[],false,'{"seq":17,"concept":"K5-1-u3-C52","difficulty":3,"kind":"ox","stem":"발표를 잘 준비한 사람은 질문을 받을 준비도 함께 해요.","answer":"O","reason_options":[{"t":"발표와 질문은 한 짝이라 예상 질문과 답을 미리 만들면 발표 내용의 빈 곳도 채울 수 있기 때문에","correct":true},{"t":"좋은 발표에는 질문이 나오지 않기 때문에","mis":"K5-1-u3-X50"}],"mis":"K5-1-u3-X50","explanation":["예상 질문을 준비해요.","질문이 오갈 때 발표가 완성돼요.","두 공부는 이어져 있어요."]}'::jsonb),
('g5_1_kor_u3_review_b#18','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C22',3,'mc','auto','지슬이가 주제를 좁혀 간 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X21']::text[],false,'{"seq":18,"concept":"K5-1-u3-C22","difficulty":3,"kind":"mc","stem":"지슬이가 주제를 좁혀 간 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"동물 → 새 → 우리 마을에 오는 철새 → 우리 마을 철새 쉼터","correct":true},{"t":"우리 마을 철새 쉼터 → 동물 → 새 → 우리 마을에 오는 철새","mis":"K5-1-u3-X21"},{"t":"새 → 동물 → 우리 마을 철새 쉼터 → 우리 마을에 오는 철새","mis":"K5-1-u3-X21"},{"t":"동물 → 우리 마을 철새 쉼터","mis":"K5-1-u3-X21"}],"explanation":["맨 끝이 맨 앞에 왔어요.","넓혀 갔다가 좁혔어요.","넓은 것에서 차례로 좁혔어요."]}'::jsonb),
('g5_1_kor_u3_review_b#19','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C46',3,'mc','auto','「창틀의 화분」을 나와 관련지어 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X44']::text[],false,'{"seq":19,"concept":"K5-1-u3-C46","difficulty":3,"kind":"mc","stem":"「창틀의 화분」을 나와 관련지어 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이사 간 친구와 한 약속을 지키려고 나도 혼자 무언가를 한 적이 있어. 려원이 마음을 알 것 같아.」","correct":true},{"t":"「화분 이야기는 나와 관계없어.」","mis":"K5-1-u3-X44"},{"t":"「나는 식물을 안 키워서 할 말이 없어.」","mis":"K5-1-u3-X44"},{"t":"「꽃은 노란색이 예뻐.」","mis":"K5-1-u3-X44"}],"explanation":["나와 이어 보지 않았어요.","경험이 달라도 마음은 이어 볼 수 있어요.","내 경험을 인물의 마음과 이었어요."]}'::jsonb),
('g5_1_kor_u3_review_b#20','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C29',3,'mc','auto','지슬이가 발표를 마치고 점검한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X28','K5-1-u3-X25','K5-1-u3-X18']::text[],false,'{"seq":20,"concept":"K5-1-u3-C29","difficulty":3,"kind":"mc","stem":"지슬이가 발표를 마치고 점검한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「새 떼 영상은 효과적이었지만, 새의 수가 줄어든 까닭을 묻는 질문에는 성의 있게 답하지 못해서 아쉬웠다.」","correct":true},{"t":"「발표가 끝났으니 돌아볼 것이 없다.」","mis":"K5-1-u3-X28"},{"t":"「화면 장수가 많아서 잘한 발표였다.」","mis":"K5-1-u3-X25"},{"t":"「글씨 색이 예뻐서 만족한다.」","mis":"K5-1-u3-X18"}],"explanation":["점검까지가 발표예요.","장수가 기준이 아니에요.","좋았던 점과 아쉬운 점을 함께 짚었어요."]}'::jsonb),
('g5_1_kor_u3_review_b#21','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C39',3,'mc','auto','질문하기 전에 가장 먼저 생각할 것은 무엇인가요?',ARRAY['K5-1-u3-X37','K5-1-u3-X35','K5-1-u3-X29']::text[],false,'{"seq":21,"concept":"K5-1-u3-C39","difficulty":3,"kind":"mc","stem":"질문하기 전에 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"내가 무엇을 알고 싶은지","correct":true},{"t":"질문의 갈래 이름이 무엇인지","mis":"K5-1-u3-X37"},{"t":"질문이 얼마나 긴지","mis":"K5-1-u3-X35"},{"t":"다른 친구가 무엇을 물었는지","mis":"K5-1-u3-X29"}],"explanation":["갈래 이름보다 알고 싶은 것이 먼저예요.","길이는 기준이 아니에요.","알고 싶은 것에 맞게 물어요."]}'::jsonb),
('g5_1_kor_u3_review_b#22','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C11',3,'mc','auto','지슬이가 새 떼 영상을 발표에 쓸 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-1-u3-X10','K5-1-u3-X25','K5-1-u3-X19']::text[],false,'{"seq":22,"concept":"K5-1-u3-C11","difficulty":3,"kind":"mc","stem":"지슬이가 새 떼 영상을 발표에 쓸 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"날아오르는 장면만 짧게 골라 보여 준다","correct":true},{"t":"처음부터 끝까지 모두 튼다","mis":"K5-1-u3-X10"},{"t":"영상 내내 지슬이는 아무 말도 하지 않는다","mis":"K5-1-u3-X25"},{"t":"영상의 출처는 적지 않는다","mis":"K5-1-u3-X19"}],"explanation":["필요한 부분만 골라요.","설명은 발표자가 해요.","꼭 필요한 부분만 써요."]}'::jsonb),
('g5_1_kor_u3_review_b#23','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C25',4,'essay','teacher','지슬이의 첫 발표 화면을 어떻게 고치면 좋을지 세 가지 쓰고, 그렇게 고치면 듣는 사람에게 무엇이 좋은지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u3-C25","difficulty":4,"kind":"essay","stem":"지슬이의 첫 발표 화면을 어떻게 고치면 좋을지 세 가지 쓰고, 그렇게 고치면 듣는 사람에게 무엇이 좋은지 쓰세요.","answer_guide":{"answer":"예: 화면마다 철새 이름 · 저수지 지도 · 먹이 주는 날 가운데 한 가지만 담는다. 긴 설명 글은 요약해서 큰 글씨로 쓴다. 큰고니 사진 아래에 가져온 곳을 적는다. 그러면 듣는 사람이 화면을 한눈에 알아보고 지슬이의 말에 집중할 수 있으며 자료도 믿고 볼 수 있다.","scoring_points":["고칠 점을 세 가지 썼는가","고치는 방법이 자료 만들 때 지킬 것과 맞는가","듣는 사람에게 좋은 점을 썼는가"]},"explanation":["내용의 양을 봐요.","글씨와 글의 양을 봐요.","출처를 봐요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb),
('g5_1_kor_u3_review_b#24','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C38',4,'essay','teacher','율비네 학급 회의에서 하설이의 제안에 대해 내용과 이어지고 예의 있는 질문을 두 개 만들고, 그 질문이 왜 좋은지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u3-C38","difficulty":4,"kind":"essay","stem":"율비네 학급 회의에서 하설이의 제안에 대해 내용과 이어지고 예의 있는 질문을 두 개 만들고, 그 질문이 왜 좋은지 쓰세요.","answer_guide":{"answer":"예: 「정리 당번은 일주일에 한 번 몇 명이 하나요?」 · 「만약 당번이 정리한 뒤에도 책이 흐트러지면 어떻게 하나요?」 두 질문 모두 하설이의 제안과 이어지고, 상대를 깎아내리지 않으며 무엇이 궁금한지 분명하다.","scoring_points":["하설이의 제안과 이어지는 질문을 두 개 썼는가","예의 있게 물었는가","좋은 까닭을 썼는가"]},"explanation":["하설이는 무엇을 제안했나요?","깎아내리는 말은 빼요.","분명하게 물어요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb),
('g5_1_kor_u3_review_b#25','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C13',4,'essay','teacher','「자료 유형은 발표 내용이 무엇을 보여 주려는지에 따라 고른다」와 「유형에 정답이 하나로 정해진 것은 아니다」를 함께 생각하여, 자료 유형을 고르는 방법을 예와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u3-C13","difficulty":4,"kind":"essay","stem":"「자료 유형은 발표 내용이 무엇을 보여 주려는지에 따라 고른다」와 「유형에 정답이 하나로 정해진 것은 아니다」를 함께 생각하여, 자료 유형을 고르는 방법을 예와 함께 쓰세요.","answer_guide":{"answer":"예: 먼저 발표 내용이 설명인지, 변화 과정인지, 생김새인지, 수치인지 따져 그 내용을 가장 잘 살려 주는 유형을 고른다. 새 떼가 날아오르는 모습은 영상이 가장 잘 보여 준다. 그러나 영상을 구하기 어렵다면 날아오르기 전과 뒤의 사진 두 장을 나란히 두어도 된다. 중요한 것은 유형의 이름이 아니라 자료가 내용을 잘 전하는가이다.","scoring_points":["보여 주려는 것을 기준으로 고른다고 썼는가","다른 유형으로도 전할 수 있다고 썼는가","예를 들었는가"]},"explanation":["기준을 먼저 써요.","정답이 하나뿐일까요?","예를 들어 설명해요."]}'::jsonb),
('g5_1_kor_u3_review_c#1','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C54',1,'match','auto','낱말과 그 뜻을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K5-1-u3-C54","difficulty":1,"kind":"match","stem":"낱말과 그 뜻을 이으세요.","pairs":[{"l":"애완","r":"귀여워하거나 즐김"},{"l":"반려","r":"짝이 되는 동무"},{"l":"협력","r":"힘을 합하여 서로 도움"}],"mis":"K5-1-u3-X52","explanation":["즐기는 대상으로 봐요.","함께 지내는 동무로 봐요.","함께함을 담았어요."]}'::jsonb),
('g5_1_kor_u3_review_c#2','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C53',1,'ox','auto','비슷한 뜻의 낱말이라도 담고 있는 태도가 달라요.',ARRAY['K5-1-u3-X51']::text[],false,'{"seq":2,"concept":"K5-1-u3-C53","difficulty":1,"kind":"ox","stem":"비슷한 뜻의 낱말이라도 담고 있는 태도가 달라요.","answer":"O","reason_options":[{"t":"「애완」과 「반려」처럼 같은 대상을 즐기는 것으로 보는지 동무로 보는지가 다르기 때문에","correct":true},{"t":"뜻이 비슷하면 어느 낱말을 써도 똑같기 때문에","mis":"K5-1-u3-X51"}],"mis":"K5-1-u3-X51","explanation":["낱말마다 태도가 담겨요.","대상을 보는 눈이 달라요.","그래서 낱말을 골라 써요."]}'::jsonb),
('g5_1_kor_u3_review_c#3','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C13',1,'mc','auto','지슬이의 발표 내용 ④를 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X12']::text[],false,'{"seq":3,"concept":"K5-1-u3-C13","difficulty":1,"kind":"mc","stem":"지슬이의 발표 내용 ④를 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"그림이나 사진","correct":true},{"t":"표나 그래프","mis":"K5-1-u3-X12"},{"t":"영상","mis":"K5-1-u3-X12"},{"t":"글","mis":"K5-1-u3-X12"}],"explanation":["수치가 아니에요.","움직임보다 생김새를 보여 줘야 해요.","생김새의 특징은 사진이 잘 보여 줘요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb),
('g5_1_kor_u3_review_c#4','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C35',1,'mc','auto','려원이에게 「방학 동안에는 화분에 물을 어떻게 주나요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X33','K5-1-u3-X36']::text[],false,'{"seq":4,"concept":"K5-1-u3-C35","difficulty":1,"kind":"mc","stem":"려원이에게 「방학 동안에는 화분에 물을 어떻게 주나요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"대안이나 정보를 찾기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X33"},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X33"},{"t":"려원이를 놀리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["까닭을 묻지 않아요.","말의 뜻을 묻지 않아요.","그럴 때의 방법을 구하는 질문이에요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb),
('g5_1_kor_u3_review_c#5','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C8',1,'mc','auto','「우리 지역 여름 축제」 발표 내용 ①을 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X07']::text[],false,'{"seq":5,"concept":"K5-1-u3-C8","difficulty":1,"kind":"mc","stem":"「우리 지역 여름 축제」 발표 내용 ①을 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"글","correct":true},{"t":"영상","mis":"K5-1-u3-X07"},{"t":"표나 그래프","mis":"K5-1-u3-X07"},{"t":"그림이나 사진","mis":"K5-1-u3-X07"}],"explanation":["움직임이 아니에요.","수치의 변화가 아니에요.","뜻과 시작은 자세한 설명이 필요해요."],"asset":{"type":"passage","lines":["① 축제의 뜻과 시작된 해","② 해마다 다녀간 사람 수","③ 축제 무대 공연 장면","④ 축제 마당의 모습"],"title":"「우리 지역 여름 축제」 발표 내용"}}'::jsonb),
('g5_1_kor_u3_review_c#6','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C15',1,'mc','auto','지슬이가 발표 내용 ①에 쓸 단락은 어느 것인가요?',ARRAY['K5-1-u3-X14']::text[],false,'{"seq":6,"concept":"K5-1-u3-C15","difficulty":1,"kind":"mc","stem":"지슬이가 발표 내용 ①에 쓸 단락은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"K5-1-u3-X14"},{"t":"㉰","mis":"K5-1-u3-X14"},{"t":"㉱","mis":"K5-1-u3-X14"}],"explanation":["생김새예요.","마을 사람들이 하는 일이에요.","철새의 뜻과 저수지가 쉼터인 까닭이 담겼어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb),
('g5_1_kor_u3_review_c#7','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C41',1,'mc','auto','「담 너머」에서 고양이가 담 너머로 가 보게 된 일은 어느 것인가요?',ARRAY['K5-1-u3-X39']::text[],false,'{"seq":7,"concept":"K5-1-u3-C41","difficulty":1,"kind":"mc","stem":"「담 너머」에서 고양이가 담 너머로 가 보게 된 일은 어느 것인가요?","options":[{"t":"나비가 「내 등에 올라타 봐.」라고 말했다","correct":true},{"t":"늙은 개가 위험하다고 했다","mis":"K5-1-u3-X39"},{"t":"두더지가 아무것도 없다고 했다","mis":"K5-1-u3-X39"},{"t":"참새가 관심 없다고 했다","mis":"K5-1-u3-X39"}],"explanation":["이웃들의 대답이에요.","이웃들의 대답이에요.","나비의 말이 고양이를 담 너머로 이끌었어요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb),
('g5_1_kor_u3_review_c#8','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C27',1,'mc','auto','지슬이의 끝맺는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X26','K5-1-u3-X49']::text[],false,'{"seq":8,"concept":"K5-1-u3-C27","difficulty":1,"kind":"mc","stem":"지슬이의 끝맺는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「이상으로 우리 마을 철새 쉼터에 대한 발표를 마치겠습니다. 궁금한 점이 있으면 질문해 주세요.」","correct":true},{"t":"「여기까지예요.」","mis":"K5-1-u3-X26"},{"t":"「다음에 또 할게요. 질문은 안 받아요.」","mis":"K5-1-u3-X49"},{"t":"「철새는 계절에 따라 사는 곳을 옮기는 새입니다.」","mis":"K5-1-u3-X26"}],"explanation":["마무리가 흐려요.","질문을 막았어요.","마무리와 질문 안내가 담겼어요."]}'::jsonb),
('g5_1_kor_u3_review_c#9','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C18',2,'error','auto','㉰를 쉬운 말로 바꾼 것이에요. 뜻이 달라져 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u3-X17']::text[],false,'{"seq":9,"concept":"K5-1-u3-C18","difficulty":2,"kind":"error","stem":"㉰를 쉬운 말로 바꾼 것이에요. 뜻이 달라져 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「해마다 찾아오는 새가 모두 사라졌다.」","correct":true,"mis_target":"K5-1-u3-X17"},{"t":"「해마다 찾아오는 새의 수가 줄어들고 있다.」","mis":"K5-1-u3-X17"},{"t":"「해마다 찾아오는 새가 점점 적어지고 있다.」","mis":"K5-1-u3-X17"}],"explanation":["뜻이 그대로예요.","뜻이 그대로예요.","줄어드는 것과 사라지는 것은 달라요."],"asset":{"type":"passage","lines":["㉮ 철새가 도래하는 때는 늦가을이다.","㉯ 큰고니는 이 저수지에서 월동한다.","㉰ 해마다 찾아오는 새의 개체 수가 감소하고 있다."],"title":"지슬이의 발표 원고 가운데"}}'::jsonb),
('g5_1_kor_u3_review_c#10','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C20',2,'mc','auto','지슬이가 인터넷에서 가져온 큰고니 사진에 해야 할 일은 어느 것인가요?',ARRAY['K5-1-u3-X19','K5-1-u3-X24']::text[],false,'{"seq":10,"concept":"K5-1-u3-C20","difficulty":2,"kind":"mc","stem":"지슬이가 인터넷에서 가져온 큰고니 사진에 해야 할 일은 어느 것인가요?","options":[{"t":"사진 아래쪽에 어디에서 가져왔는지 적는다","correct":true},{"t":"내가 찍은 사진이라고 말한다","mis":"K5-1-u3-X19"},{"t":"사진을 더 크게 늘려 화면을 채운다","mis":"K5-1-u3-X24"},{"t":"출처는 지슬이만 알면 되니 그대로 둔다","mis":"K5-1-u3-X19"}],"explanation":["남의 사진이에요.","크기보다 출처가 먼저예요.","이름표를 달아요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb),
('g5_1_kor_u3_review_c#11','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C36',2,'mc','auto','려원이의 제안에 「만약」을 넣어 다른 경우를 짚어 본 질문은 어느 것인가요?',ARRAY['K5-1-u3-X34']::text[],false,'{"seq":11,"concept":"K5-1-u3-C36","difficulty":2,"kind":"mc","stem":"려원이의 제안에 「만약」을 넣어 다른 경우를 짚어 본 질문은 어느 것인가요?","options":[{"t":"「만약 모둠이 맡은 화분이 시들면 어떻게 하나요?」","correct":true},{"t":"「려원이는 언제 화분을 보았나요?」","mis":"K5-1-u3-X34"},{"t":"「화분은 누가 사 왔나요?」","mis":"K5-1-u3-X34"},{"t":"「화분은 어디에 있나요?」","mis":"K5-1-u3-X34"}],"explanation":["때를 묻는 질문이에요.","사람을 묻는 질문이에요.","「만약」으로 다른 경우를 짚었어요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb),
('g5_1_kor_u3_review_c#12','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C41',2,'mc','auto','려원이가 화분을 돌본 까닭을 짐작할 수 있는 말은 어느 것인가요?',ARRAY['K5-1-u3-X39']::text[],false,'{"seq":12,"concept":"K5-1-u3-C41","difficulty":2,"kind":"mc","stem":"려원이가 화분을 돌본 까닭을 짐작할 수 있는 말은 어느 것인가요?","options":[{"t":"「꽃이 피면 사진 찍어 보내 준다고 했어.」","correct":true},{"t":"「봄 방학을 앞둔 날」","mis":"K5-1-u3-X39"},{"t":"「화분에는 아직 꽃봉오리 하나 없었다.」","mis":"K5-1-u3-X39"},{"t":"「한 달쯤 지나」","mis":"K5-1-u3-X39"}],"explanation":["때를 알려 주는 말이에요.","화분의 모습이에요.","전학 간 친구와의 약속이 드러나요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb),
('g5_1_kor_u3_review_c#13','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C33',2,'mc','auto','한율이에게 「「둘이 주면 더 빨리 필까 해서」라는 말에는 어떤 마음이 담겨 있었나요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X31','K5-1-u3-X36']::text[],false,'{"seq":13,"concept":"K5-1-u3-C33","difficulty":2,"kind":"mc","stem":"한율이에게 「「둘이 주면 더 빨리 필까 해서」라는 말에는 어떤 마음이 담겨 있었나요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"의도를 파악하기 위해서","correct":true},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X31"},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X31"},{"t":"회의를 이어 가기 위해서","mis":"K5-1-u3-X36"}],"explanation":["방법을 구하지 않아요.","낱말 뜻을 묻지 않아요.","왜 그렇게 말했는지 마음을 묻고 있어요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb),
('g5_1_kor_u3_review_c#14','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C20',2,'ox','auto','공공 기관 누리집처럼 믿을 수 있는 곳의 자료는 출처를 적지 않아도 돼요.',ARRAY['K5-1-u3-X19']::text[],false,'{"seq":14,"concept":"K5-1-u3-C20","difficulty":2,"kind":"ox","stem":"공공 기관 누리집처럼 믿을 수 있는 곳의 자료는 출처를 적지 않아도 돼요.","answer":"X","reason_options":[{"t":"믿을 수 있는 곳의 자료라도 남이 만든 것이므로 어디에서 가져왔는지 밝혀야 하기 때문에","correct":true},{"t":"믿을 수 있는 곳의 자료는 누구나 아는 것이기 때문에","mis":"K5-1-u3-X19"}],"mis":"K5-1-u3-X19","explanation":["어디에서 왔는지 밝혀요.","예의이고 믿음의 근거예요.","출처는 늘 적어요."]}'::jsonb),
('g5_1_kor_u3_review_c#15','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C9',2,'mc','auto','「해마다 쉼터를 찾아온 새의 수가 줄었다」를 글로만 전하면 생기는 어려움은 무엇인가요?',ARRAY['K5-1-u3-X08','K5-1-u3-X07']::text[],false,'{"seq":15,"concept":"K5-1-u3-C9","difficulty":2,"kind":"mc","stem":"「해마다 쉼터를 찾아온 새의 수가 줄었다」를 글로만 전하면 생기는 어려움은 무엇인가요?","options":[{"t":"얼마나 줄었는지 듣는 사람이 가늠하기 어렵다","correct":true},{"t":"아무 어려움도 없다","mis":"K5-1-u3-X08"},{"t":"새의 생김새를 알 수 없다","mis":"K5-1-u3-X07"},{"t":"새가 날아오르는 모습이 보이지 않는다","mis":"K5-1-u3-X07"}],"explanation":["수치의 크기는 글로 가늠하기 어려워요.","생김새와는 다른 문제예요.","그래프라면 한눈에 보여요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb),
('g5_1_kor_u3_review_c#16','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C43',2,'mc','auto','「담 너머」의 고양이에게 물을 질문 가운데 의도를 파악하려는 질문은 어느 것인가요?',ARRAY['K5-1-u3-X41','K5-1-u3-X42']::text[],false,'{"seq":16,"concept":"K5-1-u3-C43","difficulty":2,"kind":"mc","stem":"「담 너머」의 고양이에게 물을 질문 가운데 의도를 파악하려는 질문은 어느 것인가요?","options":[{"t":"「이웃들 말과 달리 담을 넘기로 한 까닭은 무엇인가요?」","correct":true},{"t":"「담 너머 들판의 빛깔은 몇 가지였나요?」","mis":"K5-1-u3-X41"},{"t":"「나비는 어디에 살아요?」","mis":"K5-1-u3-X42"},{"t":"「담의 높이는 얼마나 되나요?」","mis":"K5-1-u3-X42"}],"explanation":["사실을 묻는 질문이에요.","글과 관계없어요.","왜 그렇게 했는지 묻고 있어요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb),
('g5_1_kor_u3_review_c#17','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C52',3,'error','auto','이 단원에서 배운 것을 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u3-X50','K5-1-u3-X12','K5-1-u3-X37']::text[],false,'{"seq":17,"concept":"K5-1-u3-C52","difficulty":3,"kind":"error","stem":"이 단원에서 배운 것을 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「자료를 잘 고르면 질문은 받을 필요가 없어.」","correct":true,"mis_target":"K5-1-u3-X50"},{"t":"「자료는 내용과 상황에 맞게 골라야 해.」","mis":"K5-1-u3-X12"},{"t":"「질문은 목적을 생각해 분명하게 해야 해.」","mis":"K5-1-u3-X37"}],"explanation":["맞는 말이에요.","맞는 말이에요.","발표와 질문은 한 짝이에요."]}'::jsonb),
('g5_1_kor_u3_review_c#18','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C24',3,'mc','auto','지슬이가 친구들에게 쉼터 둘레의 갈대를 직접 만져 보게 하려면 어떤 매체가 알맞을까요?',ARRAY['K5-1-u3-X23']::text[],false,'{"seq":18,"concept":"K5-1-u3-C24","difficulty":3,"kind":"mc","stem":"지슬이가 친구들에게 쉼터 둘레의 갈대를 직접 만져 보게 하려면 어떤 매체가 알맞을까요?","options":[{"t":"직접 가져온 실물","correct":true},{"t":"화면에 띄운 영상","mis":"K5-1-u3-X23"},{"t":"화면에 띄운 그래프","mis":"K5-1-u3-X23"},{"t":"몸짓과 말","mis":"K5-1-u3-X23"}],"explanation":["만져 볼 수 없어요.","수치를 보여 주는 매체예요.","만져 보려면 실물이에요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb),
('g5_1_kor_u3_review_c#19','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C40',3,'mc','auto','「창틀의 화분」에서 읽는 사람이 려원이에게 묻고 싶어지는 까닭은 무엇인가요?',ARRAY['K5-1-u3-X38']::text[],false,'{"seq":19,"concept":"K5-1-u3-C40","difficulty":3,"kind":"mc","stem":"「창틀의 화분」에서 읽는 사람이 려원이에게 묻고 싶어지는 까닭은 무엇인가요?","options":[{"t":"려원이가 화분을 돌보는 까닭을 처음에는 말하지 않았기 때문이다","correct":true},{"t":"화분이 작기 때문이다","mis":"K5-1-u3-X38"},{"t":"이야기가 교실에서 일어나기 때문이다","mis":"K5-1-u3-X38"},{"t":"한율이가 일찍 왔기 때문이다","mis":"K5-1-u3-X38"}],"explanation":["크기 때문이 아니에요.","장소 때문이 아니에요.","까닭이 적히지 않은 행동이 질문을 불러요."]}'::jsonb),
('g5_1_kor_u3_review_c#20','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C28',3,'mc','auto','예상 질문을 미리 만들어 본 지슬이에게 생길 좋은 점은 무엇인가요?',ARRAY['K5-1-u3-X49','K5-1-u3-X27','K5-1-u3-X01']::text[],false,'{"seq":20,"concept":"K5-1-u3-C28","difficulty":3,"kind":"mc","stem":"예상 질문을 미리 만들어 본 지슬이에게 생길 좋은 점은 무엇인가요?","options":[{"t":"「새의 수가 왜 줄었을까?」처럼 발표에서 빠진 곳을 먼저 찾아 채울 수 있다","correct":true},{"t":"친구들이 질문을 하지 못하게 된다","mis":"K5-1-u3-X49"},{"t":"발표 시간이 줄어든다","mis":"K5-1-u3-X27"},{"t":"자료를 만들지 않아도 된다","mis":"K5-1-u3-X01"}],"explanation":["질문은 여전히 받아요.","시간과는 관계없어요.","빈 곳이 먼저 보여요."]}'::jsonb),
('g5_1_kor_u3_review_c#21','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C36',3,'mc','auto','지슬이에게 「먹이로 볍씨를 뿌리는 까닭」을 물으려 할 때 질문을 여는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X34']::text[],false,'{"seq":21,"concept":"K5-1-u3-C36","difficulty":3,"kind":"mc","stem":"지슬이에게 「먹이로 볍씨를 뿌리는 까닭」을 물으려 할 때 질문을 여는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"왜","correct":true},{"t":"만약","mis":"K5-1-u3-X34"},{"t":"언제","mis":"K5-1-u3-X34"},{"t":"누가","mis":"K5-1-u3-X34"}],"explanation":["다른 경우를 짚을 때 써요.","때를 물을 때 써요.","까닭은 「왜」로 물어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb),
('g5_1_kor_u3_review_c#22','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C12',3,'mc','auto','지슬이의 글 자료 ㉮~㉱를 선별한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X11','K5-1-u3-X16','K5-1-u3-X14']::text[],false,'{"seq":22,"concept":"K5-1-u3-C12","difficulty":3,"kind":"mc","stem":"지슬이의 글 자료 ㉮~㉱를 선별한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"㉮ · ㉯ · ㉰를 발표 내용에 맞게 요약해 쓰고 ㉱는 뺀다","correct":true},{"t":"㉮~㉱를 모두 그대로 쓴다","mis":"K5-1-u3-X11"},{"t":"빵집 이야기가 재미있으니 ㉱를 가장 크게 쓴다","mis":"K5-1-u3-X16"},{"t":"㉯만 쓰고 나머지는 모두 뺀다","mis":"K5-1-u3-X14"}],"explanation":["다 쓰면 선별이 아니에요.","주제와 관계없어요.","필요한 것은 남기고 관계없는 것은 덜어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb),
('g5_1_kor_u3_review_c#23','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C27',4,'essay','teacher','지슬이의 시작하는 말 「가」를 알맞게 고쳐 쓰고, 시작하는 말에 꼭 담아야 할 것이 무엇인지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u3-C27","difficulty":4,"kind":"essay","stem":"지슬이의 시작하는 말 「가」를 알맞게 고쳐 쓰고, 시작하는 말에 꼭 담아야 할 것이 무엇인지 쓰세요.","answer_guide":{"answer":"예: 「안녕하세요. 저는 우리 마을 철새 쉼터에 대해 발표할 지슬입니다. 겨울마다 저수지를 찾아오는 새들이 어디에서 왜 오는지 궁금해 조사해 보았습니다.」 시작하는 말에는 무엇을 발표하는지와 왜 발표하는지를 담아야 한다.","scoring_points":["인사와 주제를 담아 고쳤는가","발표하는 까닭을 담았는가","시작하는 말에 담을 것을 썼는가"]},"explanation":["핑계는 빼요.","무엇을 발표하나요?","왜 발표하나요?"],"asset":{"type":"speech","turns":[{"who":"가","text":"음…… 준비를 많이 못 했는데 그냥 해 보겠습니다."},{"who":"나","text":"철새는 계절에 따라 사는 곳을 옮기는 새로, 마을 저수지는 물이 얕아……."},{"who":"다","text":"안녕하세요. 저는 우리 마을 철새 쉼터에 대해 발표할 지슬입니다. 겨울 방학에 저수지에서 새 떼를 본 뒤로 궁금해져 조사해 보았습니다."}]}}'::jsonb),
('g5_1_kor_u3_review_c#24','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C45',4,'essay','teacher','려원이가 되어 「한율이가 물병을 들고 왔을 때 왜 아무 말 없이 웃었나요?」라는 질문에 답하고, 이야기 속 어떤 말과 행동을 근거로 했는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u3-C45","difficulty":4,"kind":"essay","stem":"려원이가 되어 「한율이가 물병을 들고 왔을 때 왜 아무 말 없이 웃었나요?」라는 질문에 답하고, 이야기 속 어떤 말과 행동을 근거로 했는지 쓰세요.","answer_guide":{"answer":"예: 답 — 「혼자 지키던 약속을 한율이가 알아주고 함께해 주니 고마워서 말보다 웃음이 먼저 나왔어.」 근거 — 려원이가 약속을 말한 바로 다음 날 한율이가 물병을 들고 와 「둘이 주면 더 빨리 필까 해서.」라고 말했고, 려원이가 사진을 두 장 찍었다.","scoring_points":["인물이 되어 답했는가","이야기 속 말과 행동을 근거로 들었는가","근거와 답이 이어지는가"]},"explanation":["려원이의 처지에서 답해요.","약속과 한율이의 행동을 봐요.","근거를 밝혀요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb),
('g5_1_kor_u3_review_c#25','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C26',4,'essay','teacher','「자료는 많을수록 좋은 발표가 된다」는 친구의 생각에 대해 자기 생각을 쓰고, 발표의 주인공이 누구인지 밝혀 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u3-C26","difficulty":4,"kind":"essay","stem":"「자료는 많을수록 좋은 발표가 된다」는 친구의 생각에 대해 자기 생각을 쓰고, 발표의 주인공이 누구인지 밝혀 까닭을 쓰세요.","answer_guide":{"answer":"예: 그렇지 않다. 발표의 주인공은 발표하는 사람이고 자료는 말을 도와주는 보조이다. 자료가 너무 많으면 화면이 빽빽해지고 발표자는 화면을 읽기만 하게 된다. 자료는 말로 전하기 어려운 곳에 꼭 필요한 만큼 있을 때 힘이 된다.","scoring_points":["친구의 생각에 대한 자기 생각을 밝혔는가","발표의 주인공이 발표자라고 썼는가","자료가 많을 때의 문제를 들어 까닭을 썼는가"]},"explanation":["자료가 많으면 어떻게 되나요?","주인공은 누구인가요?","자료가 힘이 될 때를 써요."]}'::jsonb),
('g5_1_kor_u3_review_d#1','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C54',1,'blank','auto','빈칸에 알맞은 낱말을 고르세요. 「여러 모둠이 (　　)하여 좋은 결과를 만들었다.」',ARRAY['K5-1-u3-X52','K5-1-u3-X51']::text[],false,'{"seq":1,"concept":"K5-1-u3-C54","difficulty":1,"kind":"blank","stem":"빈칸에 알맞은 낱말을 고르세요. 「여러 모둠이 (　　)하여 좋은 결과를 만들었다.」","options":[{"t":"협력","correct":true},{"t":"하청","mis":"K5-1-u3-X52"},{"t":"지배","mis":"K5-1-u3-X51"},{"t":"경쟁","mis":"K5-1-u3-X51"}],"explanation":["위아래를 가르는 말이에요.","함께함과 거리가 멀어요.","힘을 합하여 돕는다는 말이에요."]}'::jsonb),
