('g5_1_kor_u3_review_d#5','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C9',1,'mc','auto','축제에 해마다 다녀간 사람 수를 표나 그래프로 나타내는 까닭은 무엇인가요?',ARRAY['K5-1-u3-X18','K5-1-u3-X07']::text[],false,'{"seq":5,"concept":"K5-1-u3-C9","difficulty":1,"kind":"mc","stem":"축제에 해마다 다녀간 사람 수를 표나 그래프로 나타내는 까닭은 무엇인가요?","options":[{"t":"수치의 변화를 한눈에 알아볼 수 있어서","correct":true},{"t":"보기에 예뻐서","mis":"K5-1-u3-X18"},{"t":"설명을 자세히 담을 수 있어서","mis":"K5-1-u3-X07"},{"t":"움직임을 보여 줄 수 있어서","mis":"K5-1-u3-X07"}],"explanation":["예쁜 것은 기준이 아니에요.","자세한 설명은 글이에요.","여러 해의 수치가 한눈에 보여요."],"asset":{"type":"passage","lines":["① 축제의 뜻과 시작된 해","② 해마다 다녀간 사람 수","③ 축제 무대 공연 장면","④ 축제 마당의 모습"],"title":"「우리 지역 여름 축제」 발표 내용"}}'::jsonb),
('g5_1_kor_u3_review_d#6','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C16',1,'mc','auto','㉮를 발표 내용 ①에 맞게 요약한 것은 어느 것인가요?',ARRAY['K5-1-u3-X15','K5-1-u3-X14']::text[],false,'{"seq":6,"concept":"K5-1-u3-C16","difficulty":1,"kind":"mc","stem":"㉮를 발표 내용 ①에 맞게 요약한 것은 어느 것인가요?","options":[{"t":"계절 따라 사는 곳을 옮기는 새 · 물이 얕고 잘 얼지 않는 저수지","correct":true},{"t":"㉮의 두 문장을 그대로 옮겨 적음","mis":"K5-1-u3-X15"},{"t":"큰고니는 온몸이 흼","mis":"K5-1-u3-X14"},{"t":"빵집은 주말마다 붐빔","mis":"K5-1-u3-X14"}],"explanation":["옮겨 적으면 요약이 아니에요.","㉯의 내용이에요.","필요한 것만 남겼어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb),
('g5_1_kor_u3_review_d#7','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C40',1,'mc','auto','「담 너머」를 읽고 질문하고 싶어지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X38']::text[],false,'{"seq":7,"concept":"K5-1-u3-C40","difficulty":1,"kind":"mc","stem":"「담 너머」를 읽고 질문하고 싶어지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나비가 「담은 대부분 네가 세우게 될 거야」라고 했지만 그 까닭은 말하지 않았기 때문이다","correct":true},{"t":"고양이가 나오기 때문이다","mis":"K5-1-u3-X38"},{"t":"글이 짧기 때문이다","mis":"K5-1-u3-X38"},{"t":"들판이 넓기 때문이다","mis":"K5-1-u3-X38"}],"explanation":["인물이 나와서가 아니에요.","길이 때문이 아니에요.","까닭이 적히지 않은 말이 질문을 불러요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb),
('g5_1_kor_u3_review_d#8','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C21',1,'mc','auto','지슬이가 발표 화면을 고친 뒤 친구들 앞에서 발표를 마쳤어요. 이제 남은 일은 무엇인가요?',ARRAY['K5-1-u3-X20']::text[],false,'{"seq":8,"concept":"K5-1-u3-C21","difficulty":1,"kind":"mc","stem":"지슬이가 발표 화면을 고친 뒤 친구들 앞에서 발표를 마쳤어요. 이제 남은 일은 무엇인가요?","options":[{"t":"발표 과정을 점검하기","correct":true},{"t":"발표 계획 세우기","mis":"K5-1-u3-X20"},{"t":"발표 주제 정하기","mis":"K5-1-u3-X20"},{"t":"자료 다시 찾기","mis":"K5-1-u3-X20"}],"explanation":["계획은 맨 처음이에요.","주제는 맨 처음이에요.","발표 뒤에는 점검해요."]}'::jsonb),
('g5_1_kor_u3_review_d#9','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C18',2,'mc','auto','어려운 말을 쉬운 말로 바꿀 때 가장 조심할 점은 무엇인가요?',ARRAY['K5-1-u3-X17','K5-1-u3-X15','K5-1-u3-X19']::text[],false,'{"seq":9,"concept":"K5-1-u3-C18","difficulty":2,"kind":"mc","stem":"어려운 말을 쉬운 말로 바꿀 때 가장 조심할 점은 무엇인가요?","options":[{"t":"뜻이 달라지지 않게 한다","correct":true},{"t":"되도록 짧은 말로만 바꾼다","mis":"K5-1-u3-X17"},{"t":"어려운 말은 모두 빼 버린다","mis":"K5-1-u3-X15"},{"t":"바꾼 말에는 출처를 적는다","mis":"K5-1-u3-X19"}],"explanation":["짧다고 뜻이 같은 것은 아니에요.","빼면 내용이 빠져요.","뜻은 그대로, 말만 쉽게."]}'::jsonb),
('g5_1_kor_u3_review_d#10','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C25',2,'mc','auto','지슬이의 첫 화면을 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K5-1-u3-X24','K5-1-u3-X15','K5-1-u3-X13']::text[],false,'{"seq":10,"concept":"K5-1-u3-C25","difficulty":2,"kind":"mc","stem":"지슬이의 첫 화면을 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"화면마다 한 가지 내용만 담고 글은 요약해 크게 쓴다","correct":true},{"t":"철새 이름을 열다섯 개에서 서른 개로 늘린다","mis":"K5-1-u3-X24"},{"t":"설명 글을 세 단락에서 다섯 단락으로 늘린다","mis":"K5-1-u3-X15"},{"t":"사진을 모두 빼고 글만 남긴다","mis":"K5-1-u3-X13"}],"explanation":["더 빽빽해져요.","더 길어져요.","한 화면에 한 가지, 요약, 큰 글씨예요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb),
('g5_1_kor_u3_review_d#11','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C30',2,'mc','auto','율비네 회의에서 좋은 질문을 하려면 듣는 동안 무엇을 해야 하나요?',ARRAY['K5-1-u3-X29','K5-1-u3-X03']::text[],false,'{"seq":11,"concept":"K5-1-u3-C30","difficulty":2,"kind":"mc","stem":"율비네 회의에서 좋은 질문을 하려면 듣는 동안 무엇을 해야 하나요?","options":[{"t":"제안과 그 까닭을 짝지어 들으며 궁금하거나 흐릿한 곳을 짚는다","correct":true},{"t":"다른 친구와 이야기하며 기다린다","mis":"K5-1-u3-X29"},{"t":"내 의견만 생각하며 듣지 않는다","mis":"K5-1-u3-X29"},{"t":"친구가 말하는 도중에 끼어든다","mis":"K5-1-u3-X03"}],"explanation":["집중하지 않으면 질문이 안 생겨요.","들어야 궁금한 곳이 보여요.","집중해서 듣고 짚어 둬요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb),
('g5_1_kor_u3_review_d#12','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C45',2,'mc','auto','려원이가 되어 「왜 사진을 두 장 찍었나요?」에 답한 것으로 이야기에 근거한 것은 어느 것인가요?',ARRAY['K5-1-u3-X43']::text[],false,'{"seq":12,"concept":"K5-1-u3-C45","difficulty":2,"kind":"mc","stem":"려원이가 되어 「왜 사진을 두 장 찍었나요?」에 답한 것으로 이야기에 근거한 것은 어느 것인가요?","options":[{"t":"「한 장은 전학 간 친구에게, 한 장은 같이 물을 준 한율이에게 주고 싶었어요.」","correct":true},{"t":"「사진기가 새것이라서요.」","mis":"K5-1-u3-X43"},{"t":"「꽃이 싫어서 두 번 확인했어요.」","mis":"K5-1-u3-X43"},{"t":"「그냥 손이 미끄러졌어요.」","mis":"K5-1-u3-X43"}],"explanation":["이야기에 근거가 없어요.","이야기와 맞지 않아요.","친구와의 약속과 한율이의 도움이 근거예요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb),
('g5_1_kor_u3_review_d#13','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C44',2,'mc','auto','「창틀의 화분」 안에서 생각해 볼 수 있는 질문은 어느 것인가요?',ARRAY['K5-1-u3-X42']::text[],false,'{"seq":13,"concept":"K5-1-u3-C44","difficulty":2,"kind":"mc","stem":"「창틀의 화분」 안에서 생각해 볼 수 있는 질문은 어느 것인가요?","options":[{"t":"「꽃이 핀 날 려원이는 어떤 마음이었을까요?」","correct":true},{"t":"「화분 값은 얼마인가요?」","mis":"K5-1-u3-X42"},{"t":"「한율이네 학교 이름은 무엇인가요?」","mis":"K5-1-u3-X42"},{"t":"「물병은 몇 개인가요?」","mis":"K5-1-u3-X42"}],"explanation":["이야기와 관계없어요.","이야기와 관계없어요.","이야기 속 말과 행동으로 생각해 볼 수 있어요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb),
('g5_1_kor_u3_review_d#14','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C49',2,'mc','auto','「마을 어르신들이 기억하는 철새 쉼터의 옛 모습」을 알아보는 알맞은 방법은 어느 것인가요?',ARRAY['K5-1-u3-X47']::text[],false,'{"seq":14,"concept":"K5-1-u3-C49","difficulty":2,"kind":"mc","stem":"「마을 어르신들이 기억하는 철새 쉼터의 옛 모습」을 알아보는 알맞은 방법은 어느 것인가요?","options":[{"t":"어르신들을 찾아가 면담한다","correct":true},{"t":"공공 기관 누리집의 통계만 본다","mis":"K5-1-u3-X47"},{"t":"저수지를 오늘 관찰한다","mis":"K5-1-u3-X47"},{"t":"철새 도감을 찾아본다","mis":"K5-1-u3-X47"}],"explanation":["기억은 통계에 없어요.","옛 모습은 오늘 관찰로 알 수 없어요.","기억은 직접 여쭈어요."]}'::jsonb),
('g5_1_kor_u3_review_d#15','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C11',2,'mc','auto','지슬이가 새의 수 그래프를 찾았을 때 먼저 확인할 것은 어느 것인가요?',ARRAY['K5-1-u3-X18','K5-1-u3-X11','K5-1-u3-X24']::text[],false,'{"seq":15,"concept":"K5-1-u3-C11","difficulty":2,"kind":"mc","stem":"지슬이가 새의 수 그래프를 찾았을 때 먼저 확인할 것은 어느 것인가요?","options":[{"t":"눈금의 간격이 고른지, 수치가 과장되지 않았는지","correct":true},{"t":"그래프 색이 예쁜지","mis":"K5-1-u3-X18"},{"t":"막대가 되도록 많은지","mis":"K5-1-u3-X11"},{"t":"그래프가 화면을 가득 채우는지","mis":"K5-1-u3-X24"}],"explanation":["색은 기준이 아니에요.","많다고 좋은 것이 아니에요.","따져 보고 써요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb),
('g5_1_kor_u3_review_d#16','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C45',2,'mc','auto','나비가 되어 「왜 고양이를 도와주었나요?」에 답한 것으로 글에 근거한 것은 어느 것인가요?',ARRAY['K5-1-u3-X43']::text[],false,'{"seq":16,"concept":"K5-1-u3-C45","difficulty":2,"kind":"mc","stem":"나비가 되어 「왜 고양이를 도와주었나요?」에 답한 것으로 글에 근거한 것은 어느 것인가요?","options":[{"t":"「궁금해하며 보는 눈이 있어서 담 너머를 보여 주고 싶었어.」","correct":true},{"t":"「배가 고파서 고양이에게 먹이를 얻으려고.」","mis":"K5-1-u3-X43"},{"t":"「심심해서 아무나 태웠어.」","mis":"K5-1-u3-X43"},{"t":"「고양이가 무서워서.」","mis":"K5-1-u3-X43"}],"explanation":["글에 근거가 없어요.","글과 맞지 않아요.","「너는 궁금해하며 봤으니까」가 근거예요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb),
('g5_1_kor_u3_review_d#17','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C52',3,'mc','auto','지슬이의 발표를 들은 친구가 「큰고니 사진은 어디에서 찾았나요?」라고 물었어요. 이 장면에서 알 수 있는 것은 무엇인가요?',ARRAY['K5-1-u3-X49','K5-1-u3-X29']::text[],false,'{"seq":17,"concept":"K5-1-u3-C52","difficulty":3,"kind":"mc","stem":"지슬이의 발표를 들은 친구가 「큰고니 사진은 어디에서 찾았나요?」라고 물었어요. 이 장면에서 알 수 있는 것은 무엇인가요?","options":[{"t":"발표자가 활용한 자료가 듣는 사람의 질문으로 이어졌다","correct":true},{"t":"발표가 실패했다","mis":"K5-1-u3-X49"},{"t":"듣는 사람이 발표를 듣지 않았다","mis":"K5-1-u3-X29"},{"t":"자료에 대한 질문은 하면 안 된다","mis":"K5-1-u3-X49"}],"explanation":["질문은 실패가 아니에요.","들었기 때문에 물었어요.","자료에 대해서도 물을 수 있어요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb),
('g5_1_kor_u3_review_d#18','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C6',3,'mc','auto','지슬이의 발표를 들을 사람이 마을 어르신들이라면 준비에서 무엇을 더 생각해야 할까요?',ARRAY['K5-1-u3-X05','K5-1-u3-X17','K5-1-u3-X24']::text[],false,'{"seq":18,"concept":"K5-1-u3-C6","difficulty":3,"kind":"mc","stem":"지슬이의 발표를 들을 사람이 마을 어르신들이라면 준비에서 무엇을 더 생각해야 할까요?","options":[{"t":"어르신들이 궁금해할 내용과 잘 보이는 큰 글씨의 자료","correct":true},{"t":"듣는 사람은 생각할 필요가 없다","mis":"K5-1-u3-X05"},{"t":"어려운 낱말을 더 많이 쓴다","mis":"K5-1-u3-X17"},{"t":"화면에 글을 더 빽빽하게 넣는다","mis":"K5-1-u3-X24"}],"explanation":["듣는 사람에 따라 자료가 달라져요.","쉬운 말로 바꾸어요.","한 화면에 한 가지예요."]}'::jsonb),
('g5_1_kor_u3_review_d#19','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C41',3,'mc','auto','한율이가 려원이를 따라 물병을 들고 온 까닭을 짐작할 단서로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X39','K5-1-u3-X41']::text[],false,'{"seq":19,"concept":"K5-1-u3-C41","difficulty":3,"kind":"mc","stem":"한율이가 려원이를 따라 물병을 들고 온 까닭을 짐작할 단서로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"려원이가 전학 간 친구와 한 약속을 들은 바로 다음 날 물병을 들고 왔다","correct":true},{"t":"창틀이 교실 끝에 있다","mis":"K5-1-u3-X39"},{"t":"봄 방학이 다가왔다","mis":"K5-1-u3-X39"},{"t":"화분에 꽃봉오리가 없었다","mis":"K5-1-u3-X41"}],"explanation":["배경이에요.","때를 알려 줄 뿐이에요.","약속을 들은 뒤 행동이 달라졌어요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb),
('g5_1_kor_u3_review_d#20','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C29',3,'error','auto','지슬이의 발표를 듣고 친구들이 말해 준 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u3-X28','K5-1-u3-X19']::text[],false,'{"seq":20,"concept":"K5-1-u3-C29","difficulty":3,"kind":"error","stem":"지슬이의 발표를 듣고 친구들이 말해 준 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「잘한 점은 빼고 틀린 것만 알려 줄게.」","correct":true,"mis_target":"K5-1-u3-X28"},{"t":"「새 떼 영상 덕분에 날아오르는 모습이 한눈에 보였어.」","mis":"K5-1-u3-X28"},{"t":"「큰고니 사진에 출처를 적으면 더 좋겠어.」","mis":"K5-1-u3-X19"}],"explanation":["좋았던 점을 말했어요.","아쉬운 점을 말했어요.","좋았던 점과 아쉬운 점을 함께 말해요."]}'::jsonb),
('g5_1_kor_u3_review_d#21','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C36',3,'mc','auto','「만약」을 알맞게 넣어 지슬이에게 한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X34']::text[],false,'{"seq":21,"concept":"K5-1-u3-C36","difficulty":3,"kind":"mc","stem":"「만약」을 알맞게 넣어 지슬이에게 한 질문은 어느 것인가요?","options":[{"t":"「만약 저수지가 꽁꽁 언다면 철새들은 어디로 가나요?」","correct":true},{"t":"「만약 철새 쉼터는 어디에 있나요?」","mis":"K5-1-u3-X34"},{"t":"「만약 큰고니는 무슨 색인가요?」","mis":"K5-1-u3-X34"},{"t":"「만약 발표는 누가 했나요?」","mis":"K5-1-u3-X34"}],"explanation":["「어디에」로 물으면 돼요.","「무슨」으로 물으면 돼요.","「만약」으로 다른 경우를 짚었어요."]}'::jsonb),
('g5_1_kor_u3_review_d#22','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C19',3,'mc','auto','지슬이가 고친 발표 자료를 검토할 때 살필 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u3-X18','K5-1-u3-X19']::text[],false,'{"seq":22,"concept":"K5-1-u3-C19","difficulty":3,"kind":"mc","stem":"지슬이가 고친 발표 자료를 검토할 때 살필 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"화면의 바탕색이 지슬이가 좋아하는 색인지","correct":true},{"t":"주제에 맞는 자료인지","mis":"K5-1-u3-X18"},{"t":"글의 양이 알맞은지","mis":"K5-1-u3-X18"},{"t":"출처를 밝혔는지","mis":"K5-1-u3-X19"}],"explanation":["살펴야 해요.","살펴야 해요.","좋아하는 색은 기준이 아니에요."]}'::jsonb),
('g5_1_kor_u3_review_d#23','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C32',4,'essay','teacher','「창틀의 화분」을 읽고 려원이나 한율이에게 질문의 세 가지 목적에 맞는 질문을 하나씩 만들어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u3-C32","difficulty":4,"kind":"essay","stem":"「창틀의 화분」을 읽고 려원이나 한율이에게 질문의 세 가지 목적에 맞는 질문을 하나씩 만들어 쓰세요.","answer_guide":{"answer":"예: 의도를 파악하는 질문 — 「려원아, 처음에 「그냥 내가 주는 거야」라고만 말한 까닭은 무엇이니?」 명료하게 이해하는 질문 — 「한율아, 「둘이 주면 더 빨리 필까 해서」는 어떤 뜻이었니?」 대안이나 정보를 찾는 질문 — 「려원아, 친구에게 꽃 사진 말고 무엇을 더 보내 줄 수 있을까?」","scoring_points":["세 목적에 맞는 질문을 하나씩 썼는가","누구에게 묻는지 밝혔는가","이야기 안에서 생각해 볼 수 있는 질문인가"]},"explanation":["까닭을 묻는 질문이에요.","뜻을 묻는 질문이에요.","방법을 구하는 질문이에요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb),
('g5_1_kor_u3_review_d#24','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C48',4,'essay','teacher','「우리 학교 급식 남기지 않기」처럼 학교생활과 관련된 조사 주제를 하나 정하고, 그 주제가 조사할 만한 까닭과 알맞은 조사 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u3-C48","difficulty":4,"kind":"essay","stem":"「우리 학교 급식 남기지 않기」처럼 학교생활과 관련된 조사 주제를 하나 정하고, 그 주제가 조사할 만한 까닭과 알맞은 조사 방법을 쓰세요.","answer_guide":{"answer":"예: 주제 — 우리 학교 급식 남기지 않기. 직접 관찰하거나 영양 선생님을 면담해 자료를 구할 수 있고, 친구들이 음식을 아끼는 데 도움이 되기 때문에 조사할 만하다. 조사 방법 — 일주일 동안 급식 뒤 남은 음식을 관찰하고, 영양 선생님께 면담한다.","scoring_points":["조사 주제를 하나 정했는가","자료를 구할 수 있고 도움이 된다는 까닭을 썼는가","주제에 맞는 조사 방법을 썼는가"]},"explanation":["자료를 구할 수 있나요?","친구들에게 도움이 되나요?","답이 있을 곳을 떠올려요."]}'::jsonb),
('g5_1_kor_u3_review_d#25','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C44',4,'essay','teacher','「담 너머」를 읽고 고양이나 나비에게 할 질문을 두 개 만들고, 각 질문의 목적과 그 질문이 글 안에서 생각해 볼 수 있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u3-C44","difficulty":4,"kind":"essay","stem":"「담 너머」를 읽고 고양이나 나비에게 할 질문을 두 개 만들고, 각 질문의 목적과 그 질문이 글 안에서 생각해 볼 수 있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 나비에게 — 「대부분의 담은 내가 세우게 된다는 말은 어떤 뜻인가요?」 목적: 명료하게 이해하기 위해서. 나비의 말에 담긴 뜻을 글 전체에서 생각해 볼 수 있다. 고양이에게 — 「이웃들 말과 달리 담을 넘기로 한 까닭은 무엇인가요?」 목적: 의도를 파악하기 위해서. 고양이가 늘 궁금해했다는 글의 내용에서 생각해 볼 수 있다.","scoring_points":["질문을 두 개 만들었는가","각 질문의 목적을 썼는가","글 안에서 생각해 볼 수 있는 까닭을 썼는가"]},"explanation":["인물의 말과 행동에서 궁금한 곳을 찾아요.","목적을 밝혀요.","글과 이어 까닭을 써요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K5-1-u4-C1','kor',5,1,'u4',1,'설명하는 글이 필요한 상황 — 읽는 사람이 잘 모르는 대상을 알려 주려 할 때 설명하는 글을 쓰며, 미안한 마음을 전하거나 겪은 일을 일기로 남길 때는 설명하는 글이 아니다',ARRAY['6국03-01 쓰기']::text[],1),
('K5-1-u4-C2','kor',5,1,'u4',1,'설명하는 글은 늘어놓는 글이 아니다 — 아는 것을 떠오르는 대로 늘어놓으면 읽는 사람이 정리하기 어려우므로, 설명하는 글은 읽는 사람이 한 번에 이해하도록 짜서 쓴다',ARRAY['6국03-01 쓰기']::text[],2),
('K5-1-u4-C3','kor',5,1,'u4',1,'글의 구조의 뜻 — 글을 일정한 틀에 따라 구성한 것을 글의 구조라고 하며, 같은 내용도 어떤 틀에 담느냐에 따라 잘 전해지기도 하고 흩어지기도 한다',ARRAY['6국02-01 읽기']::text[],3),
('K5-1-u4-C4','kor',5,1,'u4',1,'미리 구성하기와 정리하는 방법 — 글을 쓰기 전에 내용을 미리 구성하면 짜임새 있게 전할 수 있으며, 비슷한 내용끼리 묶고 알맞은 차례를 정해 정리한다',ARRAY['6국03-01 쓰기']::text[],4),
('K5-1-u4-C5','kor',5,1,'u4',1,'요약의 뜻 — 요약하기는 긴 글에서 중요한 내용을 간추려 정리하는 것이며, 요약할 때 글의 구조를 활용하면 어디가 중요한 내용인지 드러난다',ARRAY['6국02-01 읽기']::text[],5),
('K5-1-u4-C6','kor',5,1,'u4',1,'구조를 생각하며 읽으면 좋은 점 — 글의 구조를 생각하며 읽으면 글 전체를 잘 이해하고 중요한 내용을 쉽게 간추릴 수 있으나, 글을 읽지 않아도 내용을 알게 되는 것은 아니다',ARRAY['6국02-01 읽기']::text[],6),
('K5-1-u4-C7','kor',5,1,'u4',1,'이 단원의 두 갈래 — 이 단원에서는 설명하는 글의 구조를 알고 요약하기와 대상을 설명하는 글 쓰기를 배우며, 읽으며 익힌 구조를 쓸 때 다시 쓴다',ARRAY['6국02-01 읽기']::text[],7),
('K5-1-u4-C8','kor',5,1,'u4',2,'열거 구조 — 대상의 특징을 나열하며 설명하는 구조로, 여러 정보를 항목별로 알려 줄 때 쓴다',ARRAY['6국02-01 읽기']::text[],8),
('K5-1-u4-C9','kor',5,1,'u4',2,'순서 구조 — 시간이나 장소의 변화, 단계를 차례대로 설명하는 구조로, 방법이나 절차를 알려 줄 때 쓴다',ARRAY['6국02-01 읽기']::text[],9),
('K5-1-u4-C10','kor',5,1,'u4',2,'비교와 대조 구조 — 두 대상의 공통점과 차이점을 찾아 설명하는 구조로, 둘을 한눈에 견주어 알려 줄 때 쓴다',ARRAY['6국02-01 읽기']::text[],10),
('K5-1-u4-C11','kor',5,1,'u4',2,'구조를 짐작하게 하는 말 — 열거는 첫째 · 둘째 · 셋째, 순서는 먼저 · 다음으로 · 그 뒤 · 마지막으로, 공통점은 모두 · 공통점 · 비슷하게, 차이점은 반면 · 다르게 · 차이점 같은 말이 구조를 짐작하게 한다',ARRAY['6국02-01 읽기']::text[],11),
('K5-1-u4-C12','kor',5,1,'u4',2,'드러내는 말은 단서일 뿐이다 — 첫째 · 둘째 · 셋째는 순서 구조에서도 쓸 수 있으므로, 첫째와 둘째의 내용을 서로 바꾸어 보아 글이 그대로면 열거, 글이 이상해지면 순서로 가린다',ARRAY['6국02-01 읽기']::text[],12),
('K5-1-u4-C13','kor',5,1,'u4',2,'구조는 무엇을 말하려는지가 정한다 — 같은 가야금도 여러 특징을 소개하면 열거, 만드는 과정을 소개하면 순서, 거문고와 견주면 비교와 대조가 되듯 구조는 대상이 아니라 말하려는 내용이 정한다',ARRAY['6국02-01 읽기']::text[],13),
('K5-1-u4-C14','kor',5,1,'u4',2,'구조가 보이면 짐작하며 읽는다 — 구조를 드러내는 말이 보이면 다음에 무엇이 나올지 짐작하며 읽게 되어 긴 글도 흩어지지 않으며, 구조를 찾는 것이 요약의 첫걸음이다',ARRAY['6국02-01 읽기']::text[],14),
('K5-1-u4-C15','kor',5,1,'u4',4,'중심 문장과 뒷받침 문장 — 한 문단은 대개 한 가지 이야기를 하며, 그 이야기를 대표하는 문장이 중심 문장, 이를 자세히 풀어 주는 문장이 뒷받침 문장이다',ARRAY['6국02-01 읽기']::text[],15),
('K5-1-u4-C16','kor',5,1,'u4',4,'예와 까닭은 뒷받침 문장 — 예를 들거나 까닭을 대며 앞 문장을 풀어 주는 문장은 자세해 보여도 뒷받침 문장이므로 중심 문장으로 고르지 않는다',ARRAY['6국02-01 읽기']::text[],16),
('K5-1-u4-C17','kor',5,1,'u4',4,'열거 틀에 정리하기 — 열거 구조는 항목별로 나란히 정리하며, 각 항목의 특징만 남기고 글 전체를 소개하거나 묶는 문장은 항목 칸에 넣지 않는다',ARRAY['6국02-01 읽기']::text[],17),
('K5-1-u4-C18','kor',5,1,'u4',4,'순서 틀에 정리하기 — 순서 구조는 단계별로 정리하며, 단계가 곧 내용이므로 차례를 바꾸면 안 된다',ARRAY['6국02-01 읽기']::text[],18),
('K5-1-u4-C19','kor',5,1,'u4',4,'비교와 대조 틀에 정리하기 — 비교와 대조 구조는 줄은 줄끼리, 연주는 연주끼리처럼 같은 항목끼리 마주 놓아야 차이가 드러나며, 항목을 뒤바꾸면 정리가 틀린다',ARRAY['6국02-01 읽기']::text[],19),
('K5-1-u4-C20','kor',5,1,'u4',4,'틀은 정해진 모양이 없다 — 구조별 틀은 하나의 예시일 뿐이므로 겹치는 원 두 개나 표처럼 자기만의 모양으로 그려도 되며, 중요한 것은 구조의 특징이 드러나는가이다',ARRAY['6국02-01 읽기']::text[],20),
('K5-1-u4-C21','kor',5,1,'u4',4,'중심 낱말로 짧게 정리하기 — 정리는 한눈에 들어와야 쓸모가 있으므로 문장을 그대로 옮기지 않고 「줄 열두 개 · 안족」처럼 중심 낱말로 간단히 적는다',ARRAY['6국02-01 읽기']::text[],21),
('K5-1-u4-C22','kor',5,1,'u4',5,'긴 글을 요약하는 차례 — 긴 글은 구조 찾기 → 문단마다 중심 문장 찾기 → 처음 · 가운데 · 끝으로 정리하기의 차례로 요약한다',ARRAY['6국02-01 읽기']::text[],22),
('K5-1-u4-C23','kor',5,1,'u4',5,'글 속 낱말의 뜻 — 오염은 더럽게 물듦, 정화는 불순한 것을 걸러 깨끗하게 함, 서식은 생물이 어떤 곳에 깃들어 삶, 무단은 허락 없이 마음대로 함이다',ARRAY['6국02-01 읽기']::text[],23),
('K5-1-u4-C24','kor',5,1,'u4',5,'긴 글의 구조 찾기 — 첫째 · 둘째 · 셋째로 방법을 나누어 하나씩 설명했고 단계도 견주기도 아니면 열거 구조이며, 「그러나」 · 「이처럼」은 구조를 드러내는 말이 아니다',ARRAY['6국02-01 읽기']::text[],24),
('K5-1-u4-C25','kor',5,1,'u4',5,'처음 · 가운데 · 끝 — 처음은 대상을 밝히고 무엇을 알아볼지 열며, 가운데는 항목이나 단계의 중심 내용을 설명하고, 끝은 앞의 내용을 묶어 정리하며 실천을 권하기도 한다',ARRAY['6국02-01 읽기']::text[],25),
('K5-1-u4-C26','kor',5,1,'u4',5,'요약문은 중심 문장을 잇는다 — 요약문은 중심 문장을 이어 만들며, 글에 나온 낱말을 늘어놓거나 뒷받침하는 까닭과 예까지 다 옮기는 것은 요약이 아니다',ARRAY['6국02-01 읽기']::text[],26),
('K5-1-u4-C27','kor',5,1,'u4',5,'다른 과목 글에도 요약하기 — 사회나 과학 교과서의 설명하는 글도 열거 · 비교와 대조처럼 구조에 따라 요약할 수 있으며, 요약은 국어 시간에만 쓰는 기술이 아니다',ARRAY['6국02-01 읽기']::text[],27),
('K5-1-u4-C28','kor',5,1,'u4',7,'필요한 것을 골라 쓴다 — 설명하는 글은 아는 것을 다 쓰는 글이 아니라 읽을 사람에게 필요한 것을 골라 쓰는 글이다',ARRAY['6국03-01 쓰기']::text[],28),
('K5-1-u4-C29','kor',5,1,'u4',7,'쓸 내용을 정하는 차례 — 글을 쓰는 목적 → 읽을 사람 → 설명할 대상 → 글의 구조의 차례로 정한다',ARRAY['6국03-01 쓰기']::text[],29),
('K5-1-u4-C30','kor',5,1,'u4',7,'설명할 대상을 고르는 기준 — 내가 잘 아는 것 · 읽을 사람이 흥미로워할 것 · 믿을 수 있는 자료를 구할 수 있는 것 · 알릴 값이 있는 것을 고른다',ARRAY['6국03-01 쓰기']::text[],30),
('K5-1-u4-C31','kor',5,1,'u4',7,'읽을 사람에 따라 달라진다 — 저학년 동생이 읽으면 어려운 말을 줄이고 그림을 넣으며, 다른 나라 친구가 읽으면 우리에게 익숙한 말도 뜻을 풀어 차근차근 설명하듯 같은 대상도 읽을 사람에 따라 내용과 말이 달라진다',ARRAY['6국03-01 쓰기']::text[],31),
('K5-1-u4-C32','kor',5,1,'u4',7,'한 글 안에 구조가 함께 쓰일 수 있다 — 줄타기 글은 전체가 열거 구조이지만 다른 나라 줄 공연과 견주는 항목 안에서는 비교와 대조가 함께 쓰였다',ARRAY['6국02-01 읽기']::text[],32),
('K5-1-u4-C33','kor',5,1,'u4',7,'읽는 사람을 생각해 배열하기 — 쓸 내용은 떠오른 차례가 아니라 무엇을 먼저 놓아야 읽는 사람의 흥미를 끌고 글이 짜임새 있어질지 생각해 배열한다',ARRAY['6국03-01 쓰기']::text[],33),
('K5-1-u4-C34','kor',5,1,'u4',9,'조사 계획 세우기 — 글의 내용에 맞추어 조사할 내용과 활용할 매체를 정하고, 찾은 곳(출처)과 찾은 날짜를 함께 기록한다',ARRAY['6국03-01 쓰기']::text[],34),
('K5-1-u4-C35','kor',5,1,'u4',9,'조사할 내용에 맞는 매체 — 우리 집에서 해 온 방법은 어른께 여쭙고, 여러 종류를 두루 알려면 그 분야를 다룬 책을, 나라에서 정한 공식 정보는 공공 기관 누리집을 찾는다',ARRAY['6국03-01 쓰기']::text[],35),
('K5-1-u4-C36','kor',5,1,'u4',9,'자료를 점검하는 세 기준 — 찾는 목적에 맞는 자료인지 · 설명하려는 내용을 다룬 최신 자료인지 · 신뢰할 수 있는 자료인지를 점검하며, 분량이나 사진의 예쁨은 기준이 아니다',ARRAY['6국03-01 쓰기']::text[],36),
('K5-1-u4-C37','kor',5,1,'u4',9,'정한 구조를 끝까지 지키기 — 비교와 대조로 시작했다면 끝까지 두 대상을 나란히 놓고, 열거로 시작했다면 항목을 같은 방식으로 이어 가며 구조를 중간에 바꾸지 않는다',ARRAY['6국03-01 쓰기']::text[],37),
('K5-1-u4-C38','kor',5,1,'u4',9,'느낌은 설명하는 글의 중심이 아니다 — 설명하는 글은 대상의 특성을 알려 주는 글이므로 「세상에서 제일 맛있다」 같은 글쓴이의 느낌은 중심이 아니며, 읽는 사람이 쉽게 이해할 표현으로 쓴다',ARRAY['6국03-01 쓰기']::text[],38),
('K5-1-u4-C39','kor',5,1,'u4',9,'도움이 되는 댓글 — 칭찬만 남기면 글이 나아지지 않고 지적만 남기면 마음이 상하므로, 좋았던 점과 보태면 좋을 점을 근거와 함께 적는다',ARRAY['6국03-01 쓰기']::text[],39),
('K5-1-u4-C40','kor',5,1,'u4',9,'쓰기 과정 점검과 다듬기 — 자료 모으기 · 구조 정하기 · 끝까지 쓰기 · 다듬기의 과정 전체를 점검하며, 다 쓴 뒤 읽을 사람의 처지에서 다시 읽어 부족한 것은 더하고 없어도 되는 것은 뺀다',ARRAY['6국03-01 쓰기']::text[],40),
('K5-1-u4-C41','kor',5,1,'u4',12,'글 모음집의 주제 — 글 모음집의 큰 주제는 우리나라 전통 놀이 · 여러 가지 직업 · 우리 고장의 자랑거리처럼 여러 사람이 저마다 다른 대상을 골라 나누어 쓸 수 있는 것이어야 한다',ARRAY['6국03-01 쓰기']::text[],41),
('K5-1-u4-C42','kor',5,1,'u4',12,'글 모음집을 만드는 차례 — 반 전체의 큰 주제 정하기 → 각자 설명할 대상 고르기 → 대상에 맞는 구조로 정리하기 → 글을 써서 모음집으로 묶기의 차례로 한다',ARRAY['6국03-01 쓰기']::text[],42),
('K5-1-u4-C43','kor',5,1,'u4',12,'주제가 같아도 구조는 저마다 — 한 모음집에 실린 글도 대상과 말하려는 내용에 따라 열거 · 순서 · 비교와 대조로 구조가 저마다 다를 수 있다',ARRAY['6국03-01 쓰기']::text[],43),
('K5-1-u4-C44','kor',5,1,'u4',12,'함께 정할 겉모습 — 따로 쓴 글이 한 권으로 보이려면 제목 다는 방식 · 글의 분량 · 사진을 넣을지 같은 겉모습을 미리 함께 정한다',ARRAY['6국03-01 쓰기']::text[],44),
('K5-1-u4-C45','kor',5,1,'u4',12,'글 모음집에 넣을 것 — 표지(모음집 제목과 만든 사람들) · 머리말(어떤 주제로 왜 모았는지) · 차례(글 제목과 쪽수) · 출처(각 글에서 활용한 자료)를 넣는다',ARRAY['6국03-01 쓰기']::text[],45),
('K5-1-u4-C46','kor',5,1,'u4',12,'친구의 글에서 구조 찾기 — 친구의 글을 읽으며 어떤 구조를 썼는지 찾아보면 같은 주제라도 틀에 따라 읽는 느낌이 달라짐을 알게 되고 배운 것이 한 번 더 정리된다',ARRAY['6국02-01 읽기']::text[],46),
('K5-1-u4-C47','kor',5,1,'u4',12,'새- · 샛- · 시- · 싯-의 뜻 — 새- · 샛- · 시- · 싯-은 뒤에 오는 말에 붙어 「매우 짙고 선명하게」라는 뜻을 더하며, 넷 가운데 무엇을 쓸지는 규칙으로 정해진다 (기초 다지기)',ARRAY['기초 다지기(새-·샛-·시-·싯-)']::text[],47),
('K5-1-u4-C48','kor',5,1,'u4',12,'첫소리로 가르기 — 뒤에 오는 말의 첫소리가 된소리 · 거센소리 · ㅎ이면 새- · 시-(새파랗다 · 시퍼렇다), ㄴ · ㅁ이면 샛- · 싯-(샛노랗다 · 싯누렇다)을 쓴다 (기초 다지기)',ARRAY['기초 다지기(새-·샛-·시-·싯-)']::text[],48),
('K5-1-u4-C49','kor',5,1,'u4',12,'모음으로 가르기 — 뒤에 오는 말의 모음이 ㅏ · ㅗ이면 새- · 샛-(새파랗다 · 샛노랗다), ㅓ · ㅜ이면 시- · 싯-(시퍼렇다 · 싯누렇다)을 쓴다 (기초 다지기)',ARRAY['기초 다지기(새-·샛-·시-·싯-)']::text[],49)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K5-1-u4-X01','kor',5,'u4',ARRAY['K5-1-u4-C1']::text[],'설명하는 글이 필요한 상황과 마음을 전하거나 겪은 일을 남기는 상황을 헷갈린다','모르는 대상을 알려 주나?'),
('K5-1-u4-X02','kor',5,'u4',ARRAY['K5-1-u4-C2']::text[],'아는 것을 떠오르는 대로 늘어놓으면 좋은 설명이 된다고 여긴다','한 번에 이해하도록 짜요'),
('K5-1-u4-X03','kor',5,'u4',ARRAY['K5-1-u4-C3']::text[],'글의 구조를 글씨나 꾸밈으로 여기거나, 틀과 관계없이 내용은 늘 똑같이 전해진다고 여긴다','구조 = 글을 담는 틀'),
('K5-1-u4-X04','kor',5,'u4',ARRAY['K5-1-u4-C4']::text[],'미리 구성하는 까닭을 글자 수 늘리기나 시간 줄이기로 여기거나, 떠오르는 차례대로 다 적는 것을 정리로 여긴다','묶고 차례 정하기'),
('K5-1-u4-X05','kor',5,'u4',ARRAY['K5-1-u4-C5']::text[],'요약을 글을 그대로 옮기거나 첫 문장만 베끼는 것으로 여긴다','중요한 내용을 간추려요'),
('K5-1-u4-X06','kor',5,'u4',ARRAY['K5-1-u4-C6']::text[],'구조를 알면 글을 끝까지 읽지 않아도 내용을 다 알 수 있다고 여긴다','구조는 길잡이일 뿐'),
('K5-1-u4-X07','kor',5,'u4',ARRAY['K5-1-u4-C7']::text[],'이 단원의 공부를 읽기 또는 쓰기 한쪽뿐으로 여기거나, 읽으며 익힌 구조는 쓸 때 쓸모없다고 여긴다','요약하기 · 설명하는 글 쓰기'),
('K5-1-u4-X08','kor',5,'u4',ARRAY['K5-1-u4-C8']::text[],'차례가 없는 특징 나열을 순서 구조로 여기는 것처럼 열거 구조를 다른 구조와 헷갈린다','항목별로 나란히'),
('K5-1-u4-X09','kor',5,'u4',ARRAY['K5-1-u4-C9']::text[],'단계나 절차를 차례대로 설명한 글을 순서 구조로 알아보지 못한다','차례 · 단계'),
('K5-1-u4-X10','kor',5,'u4',ARRAY['K5-1-u4-C10']::text[],'두 대상을 견준 글을 비교와 대조 구조로 알아보지 못하거나 공통점과 차이점 한쪽만 살핀다','같은 점 · 다른 점'),
('K5-1-u4-X11','kor',5,'u4',ARRAY['K5-1-u4-C11']::text[],'「반면」을 순서의 말로 여기는 것처럼 구조를 짐작하게 하는 말과 구조를 엉뚱하게 짝짓는다','말과 구조의 짝'),
('K5-1-u4-X12','kor',5,'u4',ARRAY['K5-1-u4-C12']::text[],'첫째 · 둘째 · 셋째가 나오면 내용을 따지지 않고 무조건 열거 구조라고 여긴다','바꾸어 보아요'),
('K5-1-u4-X13','kor',5,'u4',ARRAY['K5-1-u4-C13']::text[],'대상이 정해지면 구조도 하나로 정해진다고 여긴다','무엇을 말하려나?'),
('K5-1-u4-X14','kor',5,'u4',ARRAY['K5-1-u4-C14']::text[],'구조를 드러내는 말을 무심히 넘겨 다음 내용을 짐작하지 못하거나 구조 찾기는 요약과 관계없다고 여긴다','요약의 첫걸음'),
('K5-1-u4-X15','kor',5,'u4',ARRAY['K5-1-u4-C15']::text[],'문단을 대표하는 중심 문장과 풀어 주는 뒷받침 문장을 헷갈린다','대표하는 문장은?'),
('K5-1-u4-X16','kor',5,'u4',ARRAY['K5-1-u4-C16']::text[],'예를 들거나 까닭을 대는 문장이 자세하다고 중심 문장으로 고른다','예와 까닭은 뒷받침'),
('K5-1-u4-X17','kor',5,'u4',ARRAY['K5-1-u4-C17']::text[],'열거 틀의 항목 칸에 글 전체를 소개하거나 묶는 문장을 넣는다','항목의 특징만'),
('K5-1-u4-X18','kor',5,'u4',ARRAY['K5-1-u4-C18']::text[],'순서 틀에서 단계의 차례를 바꾸어도 된다고 여긴다','단계가 곧 내용'),
('K5-1-u4-X19','kor',5,'u4',ARRAY['K5-1-u4-C19']::text[],'비교와 대조 정리에서 항목을 뒤바꾸거나 다른 항목끼리 마주 놓는다','같은 항목끼리'),
('K5-1-u4-X20','kor',5,'u4',ARRAY['K5-1-u4-C20']::text[],'틀은 정해진 한 가지 모양으로만 그려야 한다고 여긴다','특징이 드러나면 돼요'),
('K5-1-u4-X21','kor',5,'u4',ARRAY['K5-1-u4-C21']::text[],'정리할 때 문장을 그대로 옮겨 적는다','중심 낱말로'),
('K5-1-u4-X22','kor',5,'u4',ARRAY['K5-1-u4-C22']::text[],'긴 글을 요약하는 차례를 뒤섞는다','구조 → 중심 문장 → 처음 · 가운데 · 끝'),
('K5-1-u4-X23','kor',5,'u4',ARRAY['K5-1-u4-C23']::text[],'오염 · 정화 · 서식 · 무단의 뜻을 서로 헷갈린다','앞뒤 문장에서 짐작'),
('K5-1-u4-X24','kor',5,'u4',ARRAY['K5-1-u4-C24']::text[],'「그러나」 · 「이처럼」을 구조를 드러내는 말로 여기거나 긴 글의 구조를 잘못 가린다','항목 · 단계 · 견주기'),
('K5-1-u4-X25','kor',5,'u4',ARRAY['K5-1-u4-C25']::text[],'처음 · 가운데 · 끝에 들어갈 내용을 서로 뒤섞는다','여는 말 · 중심 내용 · 맺는 말'),
('K5-1-u4-X26','kor',5,'u4',ARRAY['K5-1-u4-C26']::text[],'낱말을 늘어놓은 것을 요약으로 여기거나 뒷받침하는 까닭과 예까지 요약에 다 넣는다','중심 문장을 이어요'),
('K5-1-u4-X27','kor',5,'u4',ARRAY['K5-1-u4-C27']::text[],'요약은 국어 시간에 읽는 글에만 쓰는 방법이라고 여긴다','다른 과목 글에도'),
('K5-1-u4-X28','kor',5,'u4',ARRAY['K5-1-u4-C28']::text[],'아는 것을 빠짐없이 다 쓰는 것이 좋은 설명하는 글이라고 여긴다','필요한 것을 골라요'),
('K5-1-u4-X29','kor',5,'u4',ARRAY['K5-1-u4-C29']::text[],'목적과 읽을 사람을 정하지 않고 구조나 대상부터 정하는 것처럼 쓸 내용을 정하는 차례를 뒤섞는다','목적 → 읽을 사람 → 대상 → 구조'),
('K5-1-u4-X30','kor',5,'u4',ARRAY['K5-1-u4-C30']::text[],'글자 수를 채우기 좋은지나 좋아하는 색처럼 엉뚱한 기준으로 설명할 대상을 고른다','잘 알고 · 흥미롭고 · 자료가 있나'),
('K5-1-u4-X31','kor',5,'u4',ARRAY['K5-1-u4-C31']::text[],'읽을 사람과 관계없이 같은 내용과 같은 말로 쓰거나 낯선 사람에게 더 어려운 말을 쓴다','누가 읽나?'),
('K5-1-u4-X32','kor',5,'u4',ARRAY['K5-1-u4-C32']::text[],'한 글에는 구조가 하나만 쓰일 수 있다고 여긴다','큰 틀 안의 작은 틀'),
('K5-1-u4-X33','kor',5,'u4',ARRAY['K5-1-u4-C33']::text[],'쓸 내용은 떠오른 차례대로 늘어놓으면 된다고 여긴다','무엇을 먼저 놓을까?'),
('K5-1-u4-X34','kor',5,'u4',ARRAY['K5-1-u4-C34']::text[],'조사할 때 찾은 곳과 찾은 날짜를 적지 않거나 조사할 내용 없이 자료부터 찾는다','출처와 날짜'),
('K5-1-u4-X35','kor',5,'u4',ARRAY['K5-1-u4-C35']::text[],'조사할 내용과 맞지 않는 매체를 고른다','답이 어디에 있을까?'),
('K5-1-u4-X36','kor',5,'u4',ARRAY['K5-1-u4-C36']::text[],'분량이 긴 자료나 사진이 예쁜 자료를 좋은 자료로 여기고, 오래되었거나 누가 썼는지 모르는 자료를 그대로 쓴다','목적 · 최신 · 신뢰'),
('K5-1-u4-X37','kor',5,'u4',ARRAY['K5-1-u4-C37']::text[],'쓰는 도중에 구조를 바꾸거나 열거 항목을 서로 다른 방식으로 쓴다','끝까지 같은 틀'),
('K5-1-u4-X38','kor',5,'u4',ARRAY['K5-1-u4-C38']::text[],'글쓴이의 느낌을 설명하는 글의 중심 내용으로 넣는다','대상의 특성을 알려요'),
('K5-1-u4-X39','kor',5,'u4',ARRAY['K5-1-u4-C39']::text[],'근거 없는 칭찬이나 지적만 남기거나 자기 글과 견주어 깎아내리는 말을 댓글로 여긴다','좋았던 점 + 보탤 점'),
('K5-1-u4-X40','kor',5,'u4',ARRAY['K5-1-u4-C40']::text[],'다 쓴 글만 보면 된다고 여겨 쓰기 과정을 점검하지 않고 다듬지도 않는다','과정 전체 · 고쳐 쓰기'),
('K5-1-u4-X41','kor',5,'u4',ARRAY['K5-1-u4-C41']::text[],'어제 꾼 꿈이나 사물함 비밀번호처럼 나누어 쓸 수 없거나 알맞지 않은 것을 모음집 주제로 고른다','여럿이 나누어 쓸 수 있나'),
('K5-1-u4-X42','kor',5,'u4',ARRAY['K5-1-u4-C42']::text[],'글 모음집을 만드는 차례를 뒤섞는다','주제 → 대상 → 구조 → 묶기'),
('K5-1-u4-X43','kor',5,'u4',ARRAY['K5-1-u4-C43']::text[],'한 모음집에 실릴 글은 모두 똑같은 구조나 똑같은 대상으로 써야 한다고 여긴다','틀은 저마다'),
('K5-1-u4-X44','kor',5,'u4',ARRAY['K5-1-u4-C44']::text[],'제목 다는 방식이나 분량 같은 겉모습은 미리 정하지 않아도 된다고 여긴다','한 권으로 보이게'),
('K5-1-u4-X45','kor',5,'u4',ARRAY['K5-1-u4-C45']::text[],'모음집에 넣을 것을 헷갈리거나 시험 점수처럼 관계없는 것을 넣고 출처를 빠뜨린다','표지 · 머리말 · 차례 · 출처'),
('K5-1-u4-X46','kor',5,'u4',ARRAY['K5-1-u4-C46']::text[],'친구의 글을 읽을 때 구조는 살피지 않거나 같은 주제면 읽는 느낌도 같다고 여긴다','어떤 틀일까?'),
('K5-1-u4-X47','kor',5,'u4',ARRAY['K5-1-u4-C47']::text[],'새- · 샛- · 시- · 싯-의 뜻을 모르거나 넷 가운데 아무것이나 붙여도 된다고 여긴다','매우 짙고 선명하게'),
('K5-1-u4-X48','kor',5,'u4',ARRAY['K5-1-u4-C48']::text[],'「샛파랗다」 · 「새노랗다」처럼 뒤에 오는 첫소리에 따른 새- · 시-와 샛- · 싯-을 헷갈린다','된소리 · 거센소리 · ㅎ ↔ ㄴ · ㅁ'),
('K5-1-u4-X49','kor',5,'u4',ARRAY['K5-1-u4-C49']::text[],'「새퍼렇다」 · 「시파랗다」처럼 뒤에 오는 모음에 따른 새- · 샛-과 시- · 싯-을 헷갈린다','ㅏ · ㅗ ↔ ㅓ · ㅜ')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_1_kor_u4_L01_basic#1','kor',5,1,'u4','L01','g5_1_kor_u4_L01_basic','lesson_basic','K5-1-u4-C1',1,'mc','auto','설명하는 글이 필요한 상황으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X01']::text[],false,'{"seq":1,"concept":"K5-1-u4-C1","difficulty":1,"kind":"mc","stem":"설명하는 글이 필요한 상황으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 악기의 차이를 친구에게 소개할 때","correct":true},{"t":"친구에게 미안한 마음을 전할 때","mis":"K5-1-u4-X01"},{"t":"겪은 일을 일기로 남길 때","mis":"K5-1-u4-X01"},{"t":"생일을 축하하는 마음을 카드에 담을 때","mis":"K5-1-u4-X01"}],"explanation":["마음을 전하는 글이에요.","겪은 일을 남기는 글이에요.","잘 모르는 대상을 알려 주는 상황이에요."]}'::jsonb),
('g5_1_kor_u4_L01_basic#2','kor',5,1,'u4','L01','g5_1_kor_u4_L01_basic','lesson_basic','K5-1-u4-C3',1,'mc','auto','글을 일정한 틀에 따라 구성한 것을 무엇이라고 하나요?',ARRAY['K5-1-u4-X03']::text[],false,'{"seq":2,"concept":"K5-1-u4-C3","difficulty":1,"kind":"mc","stem":"글을 일정한 틀에 따라 구성한 것을 무엇이라고 하나요?","options":[{"t":"글의 구조","correct":true},{"t":"글의 제목","mis":"K5-1-u4-X03"},{"t":"글씨체","mis":"K5-1-u4-X03"},{"t":"글자 수","mis":"K5-1-u4-X03"}],"explanation":["제목은 글의 이름이에요.","글씨 모양과는 관계없어요.","글을 담는 틀이 글의 구조예요."]}'::jsonb),
('g5_1_kor_u4_L01_basic#3','kor',5,1,'u4','L01','g5_1_kor_u4_L01_basic','lesson_basic','K5-1-u4-C5',1,'mc','auto','요약하기에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u4-X05','K5-1-u4-X26']::text[],false,'{"seq":3,"concept":"K5-1-u4-C5","difficulty":1,"kind":"mc","stem":"요약하기에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"긴 글에서 중요한 내용을 간추려 정리하는 것","correct":true},{"t":"긴 글을 처음부터 끝까지 그대로 옮겨 쓰는 것","mis":"K5-1-u4-X05"},{"t":"글의 첫 문장만 골라 적는 것","mis":"K5-1-u4-X05"},{"t":"글에 나온 낱말을 아무렇게나 늘어놓는 것","mis":"K5-1-u4-X26"}],"explanation":["그대로 옮기면 줄어들지 않아요.","첫 문장만으로는 부족해요.","중요한 내용을 간추리는 것이에요."]}'::jsonb),
('g5_1_kor_u4_L01_basic#4','kor',5,1,'u4','L01','g5_1_kor_u4_L01_basic','lesson_basic','K5-1-u4-C2',1,'ox','auto','설명하는 글은 아는 것을 떠오르는 대로 늘어놓는 글이에요.',ARRAY['K5-1-u4-X02']::text[],false,'{"seq":4,"concept":"K5-1-u4-C2","difficulty":1,"kind":"ox","stem":"설명하는 글은 아는 것을 떠오르는 대로 늘어놓는 글이에요.","answer":"X","reason_options":[{"t":"읽는 사람이 한 번에 이해하도록 내용을 짜서 쓰는 글이기 때문에","correct":true},{"t":"아는 것을 많이 늘어놓을수록 좋은 설명이 되기 때문에","mis":"K5-1-u4-X02"}],"mis":"K5-1-u4-X02","explanation":["늘어놓으면 읽는 사람이 정리하기 어려워요.","틀을 정해 짜서 써요.","한 번에 이해하도록 쓰는 글이에요."]}'::jsonb),
('g5_1_kor_u4_L01_basic#5','kor',5,1,'u4','L01','g5_1_kor_u4_L01_basic','lesson_basic','K5-1-u4-C4',2,'mc','auto','글을 쓰기 전에 내용을 미리 구성하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X04','K5-1-u4-X02']::text[],false,'{"seq":5,"concept":"K5-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 쓰기 전에 내용을 미리 구성하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내용을 짜임새 있게 전달하려고","correct":true},{"t":"글자 수를 늘리려고","mis":"K5-1-u4-X04"},{"t":"글 쓰는 시간을 없애려고","mis":"K5-1-u4-X04"},{"t":"떠오르는 대로 모두 적으려고","mis":"K5-1-u4-X02"}],"explanation":["글자 수가 목적이 아니에요.","시간은 오히려 들어요.","미리 짜 두어야 내용이 흩어지지 않아요."]}'::jsonb),
('g5_1_kor_u4_L01_basic#6','kor',5,1,'u4','L01','g5_1_kor_u4_L01_basic','lesson_basic','K5-1-u4-C4',2,'mc','auto','쓸 내용을 잘 정리하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X04']::text[],false,'{"seq":6,"concept":"K5-1-u4-C4","difficulty":2,"kind":"mc","stem":"쓸 내용을 잘 정리하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"비슷한 내용끼리 묶고 알맞은 차례를 정한다","correct":true},{"t":"떠오르는 차례대로 모두 적는다","mis":"K5-1-u4-X04"},{"t":"문장의 길이를 모두 같게 맞춘다","mis":"K5-1-u4-X04"},{"t":"가장 긴 내용 하나만 남긴다","mis":"K5-1-u4-X04"}],"explanation":["떠오른 차례는 흩어지기 쉬워요.","길이는 기준이 아니에요.","묶고 차례를 정해요."]}'::jsonb),
('g5_1_kor_u4_L01_basic#7','kor',5,1,'u4','L01','g5_1_kor_u4_L01_basic','lesson_basic','K5-1-u4-C2',2,'mc','auto','이든이의 대답에서 아쉬운 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X28','K5-1-u4-X01','K5-1-u4-X17']::text[],false,'{"seq":7,"concept":"K5-1-u4-C2","difficulty":2,"kind":"mc","stem":"이든이의 대답에서 아쉬운 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"떠오르는 대로 늘어놓아 듣는 친구가 정리하기 어렵다","correct":true},{"t":"학교에 대해 말할 것이 하나도 없다","mis":"K5-1-u4-X28"},{"t":"다른 나라 친구에게는 학교를 소개하면 안 된다","mis":"K5-1-u4-X01"},{"t":"운동장과 도서관은 학교와 관계없다","mis":"K5-1-u4-X17"}],"explanation":["말할 것은 많았어요.","소개해 달라는 부탁을 받았어요.","무엇부터 말할지 틀을 정해야 해요."],"asset":{"type":"speech","turns":[{"who":"다른 나라 친구","text":"안녕? 나는 다른 나라에 사는 친구야. 너희 학교가 어떤 곳인지 궁금해. 소개해 줄 수 있어?"},{"who":"이든","text":"음… 우리 학교는 크고, 운동장이 있고, 급식이 맛있고, 도서관도 있고, 또……."}]}}'::jsonb),
('g5_1_kor_u4_L01_basic#8','kor',5,1,'u4','L01','g5_1_kor_u4_L01_basic','lesson_basic','K5-1-u4-C6',2,'mc','auto','글의 구조를 생각하며 읽으면 좋은 점은 어느 것인가요?',ARRAY['K5-1-u4-X06','K5-1-u4-X03']::text[],false,'{"seq":8,"concept":"K5-1-u4-C6","difficulty":2,"kind":"mc","stem":"글의 구조를 생각하며 읽으면 좋은 점은 어느 것인가요?","options":[{"t":"중요한 내용을 파악하고 쉽게 간추릴 수 있다","correct":true},{"t":"글을 읽지 않아도 내용을 알 수 있다","mis":"K5-1-u4-X06"},{"t":"글씨체를 예쁘게 쓸 수 있다","mis":"K5-1-u4-X03"},{"t":"글을 빨리 넘길수록 잘 읽은 것이다","mis":"K5-1-u4-X06"}],"explanation":["글은 읽어야 해요.","글씨와는 관계없어요.","구조가 보이면 중요한 곳이 드러나요."]}'::jsonb),
('g5_1_kor_u4_L01_basic#9','kor',5,1,'u4','L01','g5_1_kor_u4_L01_basic','lesson_basic','K5-1-u4-C7',2,'mc','auto','이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u4-X01','K5-1-u4-X07']::text[],false,'{"seq":9,"concept":"K5-1-u4-C7","difficulty":2,"kind":"mc","stem":"이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"글의 구조를 알고 요약하기 · 대상을 설명하는 글 쓰기","correct":true},{"t":"겪은 일을 일기로 쓰기 · 마음을 전하는 편지 쓰기","mis":"K5-1-u4-X01"},{"t":"글을 소리 내어 빨리 읽기 · 글자 수 늘리기","mis":"K5-1-u4-X07"},{"t":"글의 구조 알기 · 쓰기는 하지 않기","mis":"K5-1-u4-X07"}],"explanation":["설명하는 글이 아니에요.","빨리 읽기가 목표가 아니에요.","읽기와 쓰기 두 갈래예요."]}'::jsonb),
('g5_1_kor_u4_L01_basic#10','kor',5,1,'u4','L01','g5_1_kor_u4_L01_basic','lesson_basic','K5-1-u4-C4',3,'mc','auto','「틀에 담으면」 쪽이 더 잘 전해지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X02','K5-1-u4-X03','K5-1-u4-X04']::text[],false,'{"seq":10,"concept":"K5-1-u4-C4","difficulty":3,"kind":"mc","stem":"「틀에 담으면」 쪽이 더 잘 전해지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"비슷한 내용끼리 묶어 무엇부터 말할지 틀을 정했기 때문이다","correct":true},{"t":"내용이 더 많기 때문이다","mis":"K5-1-u4-X02"},{"t":"글씨가 더 크기 때문이다","mis":"K5-1-u4-X03"},{"t":"떠오른 차례를 그대로 지켰기 때문이다","mis":"K5-1-u4-X04"}],"explanation":["내용의 양은 비슷해요.","글씨와는 관계없어요.","묶고 차례를 정한 것이 틀이에요."],"asset":{"type":"passage","lines":["떠오르는 대로 — 크고, 운동장이 있고, 급식이 맛있고, 도서관도 있고……","틀에 담으면 — 첫째, 학교의 크기와 위치","　　　　　　 둘째, 학교의 주요 시설","　　　　　　 셋째, 우리 학교만의 특별한 활동"],"title":"같은 내용, 다른 정리"}}'::jsonb),
('g5_1_kor_u4_L01_challenge#1','kor',5,1,'u4','L01','g5_1_kor_u4_L01_challenge','lesson_challenge','K5-1-u4-C6',2,'ox','auto','글의 구조를 알면 글을 끝까지 읽지 않아도 내용을 다 알 수 있어요.',ARRAY['K5-1-u4-X06']::text[],false,'{"seq":1,"concept":"K5-1-u4-C6","difficulty":2,"kind":"ox","stem":"글의 구조를 알면 글을 끝까지 읽지 않아도 내용을 다 알 수 있어요.","answer":"X","reason_options":[{"t":"구조는 중요한 내용이 어디에 있는지 찾도록 돕는 길잡이일 뿐 글은 읽어야 하기 때문에","correct":true},{"t":"구조만 보면 내용이 저절로 보이기 때문에","mis":"K5-1-u4-X06"}],"mis":"K5-1-u4-X06","explanation":["구조는 길잡이예요.","내용은 읽어야 알아요.","읽으면서 구조를 활용해요."]}'::jsonb),
('g5_1_kor_u4_L01_challenge#2','kor',5,1,'u4','L01','g5_1_kor_u4_L01_challenge','lesson_challenge','K5-1-u4-C5',2,'mc','auto','요약할 때 글의 구조를 활용하면 좋은 까닭은 무엇인가요?',ARRAY['K5-1-u4-X05','K5-1-u4-X06','K5-1-u4-X14']::text[],false,'{"seq":2,"concept":"K5-1-u4-C5","difficulty":2,"kind":"mc","stem":"요약할 때 글의 구조를 활용하면 좋은 까닭은 무엇인가요?","options":[{"t":"구조가 보이면 어디가 중요한 내용인지 드러나기 때문이다","correct":true},{"t":"구조를 쓰면 글이 길어지기 때문이다","mis":"K5-1-u4-X05"},{"t":"구조를 쓰면 중요한 내용을 몰라도 되기 때문이다","mis":"K5-1-u4-X06"},{"t":"구조는 요약과 관계없기 때문이다","mis":"K5-1-u4-X14"}],"explanation":["요약은 짧게 하는 일이에요.","중요한 내용을 찾아야 해요.","구조가 중요한 곳을 보여 줘요."]}'::jsonb),
('g5_1_kor_u4_L01_challenge#3','kor',5,1,'u4','L01','g5_1_kor_u4_L01_challenge','lesson_challenge','K5-1-u4-C1',3,'mc','auto','다음 가운데 설명하는 글로 쓰기에 가장 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u4-X01']::text[],false,'{"seq":3,"concept":"K5-1-u4-C1","difficulty":3,"kind":"mc","stem":"다음 가운데 설명하는 글로 쓰기에 가장 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구와 다툰 뒤 사과하는 마음을 전하는 글","correct":true},{"t":"전통 놀이 방법을 동생에게 알려 주는 글","mis":"K5-1-u4-X01"},{"t":"우리 학교를 다른 나라 친구에게 소개하는 글","mis":"K5-1-u4-X01"},{"t":"두 악기의 차이를 소개하는 글","mis":"K5-1-u4-X01"}],"explanation":["놀이 방법을 알려 줘요.","학교를 알려 줘요.","사과는 마음을 전하는 글이에요."]}'::jsonb),
('g5_1_kor_u4_L01_challenge#4','kor',5,1,'u4','L01','g5_1_kor_u4_L01_challenge','lesson_challenge','K5-1-u4-C2',3,'error','auto','이든이에게 친구들이 해 준 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u4-X02','K5-1-u4-X04']::text[],false,'{"seq":4,"concept":"K5-1-u4-C2","difficulty":3,"kind":"error","stem":"이든이에게 친구들이 해 준 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「아는 것을 하나도 빠짐없이 떠오르는 대로 다 말하면 돼.」","correct":true,"mis_target":"K5-1-u4-X02"},{"t":"「무엇부터 말할지 틀을 먼저 정해 봐.」","mis":"K5-1-u4-X04"},{"t":"「비슷한 것끼리 묶어서 말하면 알아듣기 쉬워.」","mis":"K5-1-u4-X04"}],"explanation":["틀을 정하라는 말은 알맞아요.","묶어서 말하라는 말도 알맞아요.","떠오르는 대로 늘어놓으면 정리하기 어려워요."],"asset":{"type":"speech","turns":[{"who":"다른 나라 친구","text":"안녕? 나는 다른 나라에 사는 친구야. 너희 학교가 어떤 곳인지 궁금해. 소개해 줄 수 있어?"},{"who":"이든","text":"음… 우리 학교는 크고, 운동장이 있고, 급식이 맛있고, 도서관도 있고, 또……."}]}}'::jsonb),
('g5_1_kor_u4_L01_challenge#5','kor',5,1,'u4','L01','g5_1_kor_u4_L01_challenge','lesson_challenge','K5-1-u4-C4',3,'mc','auto','이든이가 「도서관」을 「틀에 담으면」의 어느 항목에 넣는 것이 가장 알맞나요?',ARRAY['K5-1-u4-X04','K5-1-u4-X02']::text[],false,'{"seq":5,"concept":"K5-1-u4-C4","difficulty":3,"kind":"mc","stem":"이든이가 「도서관」을 「틀에 담으면」의 어느 항목에 넣는 것이 가장 알맞나요?","options":[{"t":"둘째, 학교의 주요 시설","correct":true},{"t":"첫째, 학교의 크기와 위치","mis":"K5-1-u4-X04"},{"t":"셋째, 우리 학교만의 특별한 활동","mis":"K5-1-u4-X04"},{"t":"어느 항목에도 넣지 않고 맨 끝에 따로 덧붙인다","mis":"K5-1-u4-X02"}],"explanation":["크기와 위치가 아니에요.","활동이 아니라 시설이에요.","비슷한 것끼리 묶어요."],"asset":{"type":"passage","lines":["떠오르는 대로 — 크고, 운동장이 있고, 급식이 맛있고, 도서관도 있고……","틀에 담으면 — 첫째, 학교의 크기와 위치","　　　　　　 둘째, 학교의 주요 시설","　　　　　　 셋째, 우리 학교만의 특별한 활동"],"title":"같은 내용, 다른 정리"}}'::jsonb),
('g5_1_kor_u4_L01_challenge#6','kor',5,1,'u4','L01','g5_1_kor_u4_L01_challenge','lesson_challenge','K5-1-u4-C7',3,'mc','auto','이 단원의 두 공부가 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X07','K5-1-u4-X02']::text[],false,'{"seq":6,"concept":"K5-1-u4-C7","difficulty":3,"kind":"mc","stem":"이 단원의 두 공부가 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"구조를 알고 읽은 글을 본보기 삼아 내가 쓸 글의 틀을 정한다","correct":true},{"t":"읽기와 쓰기는 따로라서 읽은 글은 쓸 때 쓸모가 없다","mis":"K5-1-u4-X07"},{"t":"요약을 잘하면 글을 쓰지 않아도 된다","mis":"K5-1-u4-X07"},{"t":"쓸 때는 떠오르는 대로 쓰고 읽을 때만 구조를 본다","mis":"K5-1-u4-X02"}],"explanation":["읽으며 익힌 구조를 쓸 때 써요.","두 가지를 다 배워요.","읽기와 쓰기가 이어져요."]}'::jsonb),
('g5_1_kor_u4_L01_challenge#7','kor',5,1,'u4','L01','g5_1_kor_u4_L01_challenge','lesson_challenge','K5-1-u4-C3',3,'mc','auto','같은 내용이라도 어떤 틀에 담느냐에 따라 어떻게 될 수 있나요?',ARRAY['K5-1-u4-X03','K5-1-u4-X02']::text[],false,'{"seq":7,"concept":"K5-1-u4-C3","difficulty":3,"kind":"mc","stem":"같은 내용이라도 어떤 틀에 담느냐에 따라 어떻게 될 수 있나요?","options":[{"t":"잘 전해지기도 하고 흩어지기도 한다","correct":true},{"t":"틀과 관계없이 늘 똑같이 전해진다","mis":"K5-1-u4-X03"},{"t":"틀은 글씨 모양을 말하므로 내용과 관계없다","mis":"K5-1-u4-X03"},{"t":"틀에 담으면 내용이 많아진다","mis":"K5-1-u4-X02"}],"explanation":["틀에 따라 달라져요.","틀은 글의 구조예요.","같은 내용도 틀이 전달을 바꿔요."]}'::jsonb),
('g5_1_kor_u4_L01_challenge#8','kor',5,1,'u4','L01','g5_1_kor_u4_L01_challenge','lesson_challenge','K5-1-u4-C2',4,'essay','teacher','이든이의 대답을 틀에 담아 다시 소개하는 말로 고쳐 쓰고, 그렇게 고치면 다른 나라 친구에게 무엇이 좋은지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u4-C2","difficulty":4,"kind":"essay","stem":"이든이의 대답을 틀에 담아 다시 소개하는 말로 고쳐 쓰고, 그렇게 고치면 다른 나라 친구에게 무엇이 좋은지 쓰세요.","answer_guide":{"answer":"예: 「우리 학교를 세 가지로 소개할게. 첫째, 우리 학교는 크고 마을 한가운데에 있어. 둘째, 넓은 운동장과 도서관이 있어. 셋째, 텃밭을 가꾸는 특별한 활동이 있어.」 이렇게 묶어 차례대로 말하면 친구가 무엇부터 들어야 할지 알고 한 번에 이해할 수 있다.","scoring_points":["내용을 묶어 틀에 담았는가","차례를 밝혀 고쳐 썼는가","듣는 친구에게 좋은 점을 썼는가"]},"explanation":["비슷한 것끼리 묶어요.","무엇부터 말할지 정해요.","친구가 얻는 것을 써요."],"asset":{"type":"speech","turns":[{"who":"다른 나라 친구","text":"안녕? 나는 다른 나라에 사는 친구야. 너희 학교가 어떤 곳인지 궁금해. 소개해 줄 수 있어?"},{"who":"이든","text":"음… 우리 학교는 크고, 운동장이 있고, 급식이 맛있고, 도서관도 있고, 또……."}]}}'::jsonb),
('g5_1_kor_u4_L01_challenge#9','kor',5,1,'u4','L01','g5_1_kor_u4_L01_challenge','lesson_challenge','K5-1-u4-C6',4,'essay','teacher','글의 구조를 생각하며 읽으면 좋은 점을 두 가지 쓰고, 그것이 요약과 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u4-C6","difficulty":4,"kind":"essay","stem":"글의 구조를 생각하며 읽으면 좋은 점을 두 가지 쓰고, 그것이 요약과 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 글 전체의 내용을 잘 이해할 수 있고, 중요한 내용이 어디에 있는지 쉽게 찾을 수 있다. 구조가 보이면 중요한 내용을 골라 간추릴 수 있으므로 요약하기도 쉬워진다.","scoring_points":["좋은 점을 두 가지 썼는가","요약과 이어 썼는가","구조가 중요한 내용을 찾게 돕는다는 점을 썼는가"]},"explanation":["이해하기와 찾기를 떠올려요.","요약은 간추리는 일이에요.","구조가 길잡이가 돼요."]}'::jsonb),
('g5_1_kor_u4_L01_challenge#10','kor',5,1,'u4','L01','g5_1_kor_u4_L01_challenge','lesson_challenge','K5-1-u4-C1',4,'essay','teacher','설명하는 글이 필요한 상황을 하나 떠올려 쓰고, 그 상황에서 무엇을 설명하면 좋을지와 그 상황이 설명하는 글에 알맞은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u4-C1","difficulty":4,"kind":"essay","stem":"설명하는 글이 필요한 상황을 하나 떠올려 쓰고, 그 상황에서 무엇을 설명하면 좋을지와 그 상황이 설명하는 글에 알맞은 까닭을 쓰세요.","answer_guide":{"answer":"예: 전학 온 친구에게 우리 학교 도서관을 알려 주는 상황이다. 책을 빌리는 방법과 도서관에 있는 여러 공간을 설명하면 좋겠다. 친구가 잘 모르는 대상을 알려 주려는 것이므로 설명하는 글이 알맞다.","scoring_points":["설명하는 글이 필요한 상황을 썼는가","무엇을 설명할지 썼는가","모르는 대상을 알려 준다는 까닭을 썼는가"]},"explanation":["누구에게 알려 주나요?","무엇을 알려 주나요?","왜 설명하는 글이 알맞나요?"]}'::jsonb),
('g5_1_kor_u4_L02_basic#1','kor',5,1,'u4','L02','g5_1_kor_u4_L02_basic','lesson_basic','K5-1-u4-C8',1,'mc','auto','「사물놀이의 네 악기」는 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X08','K5-1-u4-X10','K5-1-u4-X03']::text[],false,'{"seq":1,"concept":"K5-1-u4-C8","difficulty":1,"kind":"mc","stem":"「사물놀이의 네 악기」는 어떤 구조로 쓴 글인가요?","options":[{"t":"열거 구조","correct":true},{"t":"순서 구조","mis":"K5-1-u4-X08"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X10"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["차례나 단계가 없어요.","두 대상을 견주지 않았어요.","네 악기의 특징을 하나씩 나열했어요."],"asset":{"type":"passage","lines":["사물놀이는 네 가지 악기로 연주하는 우리 전통 음악이다.","첫째, 꽹과리는 가장 작고 소리가 높으며 연주를 이끈다.","둘째, 징은 가장 크고 소리가 낮게 퍼지며 큰 마디를 짚어 준다.","셋째, 장구는 양쪽 가죽의 소리가 달라 잔가락을 넣는다.","넷째, 북은 낮고 묵직한 소리로 흐름을 받쳐 준다.","네 악기는 흔히 천둥 · 바람 · 비 · 구름에 빗댄다.","이처럼 네 악기가 서로 다른 소리를 맡아 하나의 가락을 이룬다."],"title":"「사물놀이의 네 악기」"}}'::jsonb),
('g5_1_kor_u4_L02_basic#2','kor',5,1,'u4','L02','g5_1_kor_u4_L02_basic','lesson_basic','K5-1-u4-C9',1,'mc','auto','「우유갑으로 연필꽂이 만들기」는 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X09','K5-1-u4-X10','K5-1-u4-X03']::text[],false,'{"seq":2,"concept":"K5-1-u4-C9","difficulty":1,"kind":"mc","stem":"「우유갑으로 연필꽂이 만들기」는 어떤 구조로 쓴 글인가요?","options":[{"t":"순서 구조","correct":true},{"t":"열거 구조","mis":"K5-1-u4-X09"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X10"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["만드는 단계가 차례대로 있어요.","두 대상을 견주지 않았어요.","단계를 차례대로 설명했어요."],"asset":{"type":"passage","lines":["다 마신 우유갑도 조금만 손보면 쓸모 있는 물건이 된다.","연필꽂이를 만드는 방법을 알아보자.","먼저, 우유갑을 깨끗이 씻어 말린다.","다음으로, 연필 길이를 생각해 윗부분을 반듯하게 자른다.","그 뒤, 자른 곳에 테이프를 둘러 마감한다.","마지막으로, 겉면을 색종이나 천으로 감싸 꾸민다."],"title":"「우유갑으로 연필꽂이 만들기」"}}'::jsonb),
('g5_1_kor_u4_L02_basic#3','kor',5,1,'u4','L02','g5_1_kor_u4_L02_basic','lesson_basic','K5-1-u4-C10',1,'mc','auto','「가야금과 거문고」는 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X10','K5-1-u4-X09','K5-1-u4-X03']::text[],false,'{"seq":3,"concept":"K5-1-u4-C10","difficulty":1,"kind":"mc","stem":"「가야금과 거문고」는 어떤 구조로 쓴 글인가요?","options":[{"t":"비교와 대조 구조","correct":true},{"t":"열거 구조","mis":"K5-1-u4-X10"},{"t":"순서 구조","mis":"K5-1-u4-X09"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["두 악기를 견주었어요.","단계가 아니에요.","공통점과 차이점을 찾아 설명했어요."],"asset":{"type":"passage","lines":["㉮ 가야금과 거문고는 모두 긴 나무 몸통에 명주실 줄을 얹어 만들고,","　 무릎에 놓고 연주한다는 공통점이 있다.","㉯ 가야금은 줄이 열두 개이고 줄마다 안족이라는 받침이 놓여 있다.","　 반면 거문고는 줄이 여섯 개이고 몸통에 괘라는 턱이 붙어 있다.","㉰ 가야금은 손가락으로 줄을 뜯거나 튕긴다. 반면 거문고는","　 술대라는 막대로 줄을 치거나 밀어 소리를 낸다.","㉱ 그래서 가야금 소리는 맑고 부드럽고, 거문고 소리는 굵고 단단하다."],"title":"「가야금과 거문고」"}}'::jsonb),
('g5_1_kor_u4_L02_basic#4','kor',5,1,'u4','L02','g5_1_kor_u4_L02_basic','lesson_basic','K5-1-u4-C11',1,'match','auto','구조와 그 구조를 가장 잘 짐작하게 하는 말을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-1-u4-C11","difficulty":1,"kind":"match","stem":"구조와 그 구조를 가장 잘 짐작하게 하는 말을 이으세요.","pairs":[{"l":"열거 구조","r":"첫째 · 둘째 · 셋째"},{"l":"순서 구조","r":"먼저 · 다음으로 · 마지막으로"},{"l":"비교와 대조 구조","r":"공통점 · 반면 · 다르게"}],"mis":"K5-1-u4-X11","explanation":["항목을 나열해요.","차례를 밝혀요.","같은 점과 다른 점을 말해요."]}'::jsonb),
('g5_1_kor_u4_L02_basic#5','kor',5,1,'u4','L02','g5_1_kor_u4_L02_basic','lesson_basic','K5-1-u4-C9',2,'mc','auto','순서 구조로 설명하기에 가장 알맞은 내용은 어느 것인가요?',ARRAY['K5-1-u4-X08','K5-1-u4-X10']::text[],false,'{"seq":5,"concept":"K5-1-u4-C9","difficulty":2,"kind":"mc","stem":"순서 구조로 설명하기에 가장 알맞은 내용은 어느 것인가요?","options":[{"t":"종이배를 접는 방법","correct":true},{"t":"사물놀이 네 악기의 특징","mis":"K5-1-u4-X08"},{"t":"가야금과 거문고의 같은 점과 다른 점","mis":"K5-1-u4-X10"},{"t":"우리 학교의 여러 시설","mis":"K5-1-u4-X08"}],"explanation":["특징 나열은 열거예요.","견주기는 비교와 대조예요.","접는 방법은 차례가 있어요."]}'::jsonb),
('g5_1_kor_u4_L02_basic#6','kor',5,1,'u4','L02','g5_1_kor_u4_L02_basic','lesson_basic','K5-1-u4-C11',2,'mc','auto','「반면」은 어떤 구조를 짐작하게 하는 말인가요?',ARRAY['K5-1-u4-X11','K5-1-u4-X14']::text[],false,'{"seq":6,"concept":"K5-1-u4-C11","difficulty":2,"kind":"mc","stem":"「반면」은 어떤 구조를 짐작하게 하는 말인가요?","options":[{"t":"비교와 대조 구조(차이점을 말할 때)","correct":true},{"t":"순서 구조","mis":"K5-1-u4-X11"},{"t":"열거 구조","mis":"K5-1-u4-X11"},{"t":"어느 구조와도 관계없는 말","mis":"K5-1-u4-X14"}],"explanation":["차례를 밝히는 말이 아니에요.","항목을 늘어놓는 말이 아니에요.","다른 점을 말할 때 써요."]}'::jsonb),
('g5_1_kor_u4_L02_basic#7','kor',5,1,'u4','L02','g5_1_kor_u4_L02_basic','lesson_basic','K5-1-u4-C10',2,'mc','auto','비교와 대조 구조로 설명하면 좋은 점은 어느 것인가요?',ARRAY['K5-1-u4-X09','K5-1-u4-X10','K5-1-u4-X38']::text[],false,'{"seq":7,"concept":"K5-1-u4-C10","difficulty":2,"kind":"mc","stem":"비교와 대조 구조로 설명하면 좋은 점은 어느 것인가요?","options":[{"t":"두 대상의 같은 점과 다른 점을 한눈에 견줄 수 있다","correct":true},{"t":"방법이나 절차를 차근차근 알려 준다","mis":"K5-1-u4-X09"},{"t":"한 대상의 특징만 항목별로 늘어놓는다","mis":"K5-1-u4-X10"},{"t":"글쓴이의 느낌을 잘 드러낸다","mis":"K5-1-u4-X38"}],"explanation":["그것은 순서 구조예요.","그것은 열거 구조예요.","두 대상을 한눈에 견줘요."]}'::jsonb),
('g5_1_kor_u4_L02_basic#8','kor',5,1,'u4','L02','g5_1_kor_u4_L02_basic','lesson_basic','K5-1-u4-C12',2,'ox','auto','첫째 · 둘째 · 셋째가 나오면 그 글은 언제나 열거 구조예요.',ARRAY['K5-1-u4-X12']::text[],false,'{"seq":8,"concept":"K5-1-u4-C12","difficulty":2,"kind":"ox","stem":"첫째 · 둘째 · 셋째가 나오면 그 글은 언제나 열거 구조예요.","answer":"X","reason_options":[{"t":"순서 구조에서도 쓸 수 있어서 내용의 순서를 바꾸어 보아야 알 수 있기 때문에","correct":true},{"t":"첫째 · 둘째 · 셋째는 열거 구조에만 쓰는 말이기 때문에","mis":"K5-1-u4-X12"}],"mis":"K5-1-u4-X12","explanation":["순서 구조에도 쓰여요.","말은 단서일 뿐이에요.","내용을 바꾸어 보아요."]}'::jsonb),
('g5_1_kor_u4_L02_basic#9','kor',5,1,'u4','L02','g5_1_kor_u4_L02_basic','lesson_basic','K5-1-u4-C13',2,'mc','auto','가야금의 여러 특징을 하나씩 소개하는 글을 쓴다면 알맞은 구조는 어느 것인가요?',ARRAY['K5-1-u4-X13']::text[],false,'{"seq":9,"concept":"K5-1-u4-C13","difficulty":2,"kind":"mc","stem":"가야금의 여러 특징을 하나씩 소개하는 글을 쓴다면 알맞은 구조는 어느 것인가요?","options":[{"t":"열거 구조","correct":true},{"t":"비교와 대조 구조","mis":"K5-1-u4-X13"},{"t":"순서 구조","mis":"K5-1-u4-X13"},{"t":"가야금은 이미 비교와 대조로 썼으니 다른 구조는 쓸 수 없다","mis":"K5-1-u4-X13"}],"explanation":["견주는 것이 아니에요.","만드는 차례가 아니에요.","같은 대상도 말하려는 것에 따라 구조가 달라져요."]}'::jsonb),
('g5_1_kor_u4_L02_basic#10','kor',5,1,'u4','L02','g5_1_kor_u4_L02_basic','lesson_basic','K5-1-u4-C14',3,'mc','auto','구조를 드러내는 말을 살피며 읽으면 어떤 점이 좋은가요?',ARRAY['K5-1-u4-X06','K5-1-u4-X14']::text[],false,'{"seq":10,"concept":"K5-1-u4-C14","difficulty":3,"kind":"mc","stem":"구조를 드러내는 말을 살피며 읽으면 어떤 점이 좋은가요?","options":[{"t":"다음에 무엇이 나올지 짐작하며 읽어 긴 글도 머리에 남는다","correct":true},{"t":"드러내는 말만 읽고 나머지는 건너뛰어도 된다","mis":"K5-1-u4-X06"},{"t":"구조 찾기는 요약과 관계없다","mis":"K5-1-u4-X14"},{"t":"드러내는 말이 있으면 내용을 읽을 필요가 없다","mis":"K5-1-u4-X06"}],"explanation":["내용은 읽어야 해요.","구조 찾기가 요약의 첫걸음이에요.","짐작하며 읽으면 흩어지지 않아요."]}'::jsonb),
('g5_1_kor_u4_L02_challenge#1','kor',5,1,'u4','L02','g5_1_kor_u4_L02_challenge','lesson_challenge','K5-1-u4-C9',2,'mc','auto','「우유갑으로 연필꽂이 만들기」에서 「다음으로」와 「그 뒤」의 내용을 서로 바꾸면 어떻게 될까요?',ARRAY['K5-1-u4-X18','K5-1-u4-X12']::text[],false,'{"seq":1,"concept":"K5-1-u4-C9","difficulty":2,"kind":"mc","stem":"「우유갑으로 연필꽂이 만들기」에서 「다음으로」와 「그 뒤」의 내용을 서로 바꾸면 어떻게 될까요?","options":[{"t":"자르기도 전에 테이프를 두르게 되어 만드는 방법이 이상해진다","correct":true},{"t":"글이 그대로라 아무 문제가 없다","mis":"K5-1-u4-X18"},{"t":"글이 열거 구조로 바뀐다","mis":"K5-1-u4-X12"},{"t":"더 짧고 좋은 글이 된다","mis":"K5-1-u4-X18"}],"explanation":["차례가 곧 방법이에요.","구조가 바뀌는 것이 아니에요.","단계를 바꾸면 방법이 어긋나요."],"asset":{"type":"passage","lines":["다 마신 우유갑도 조금만 손보면 쓸모 있는 물건이 된다.","연필꽂이를 만드는 방법을 알아보자.","먼저, 우유갑을 깨끗이 씻어 말린다.","다음으로, 연필 길이를 생각해 윗부분을 반듯하게 자른다.","그 뒤, 자른 곳에 테이프를 둘러 마감한다.","마지막으로, 겉면을 색종이나 천으로 감싸 꾸민다."],"title":"「우유갑으로 연필꽂이 만들기」"}}'::jsonb),
('g5_1_kor_u4_L02_challenge#2','kor',5,1,'u4','L02','g5_1_kor_u4_L02_challenge','lesson_challenge','K5-1-u4-C12',2,'mc','auto','첫째 · 둘째 · 셋째로 쓴 글이 열거 구조인지 순서 구조인지 알아보는 방법은 무엇인가요?',ARRAY['K5-1-u4-X12','K5-1-u4-X03']::text[],false,'{"seq":2,"concept":"K5-1-u4-C12","difficulty":2,"kind":"mc","stem":"첫째 · 둘째 · 셋째로 쓴 글이 열거 구조인지 순서 구조인지 알아보는 방법은 무엇인가요?","options":[{"t":"첫째와 둘째의 내용을 서로 바꾸어 글이 그대로인지 살핀다","correct":true},{"t":"「첫째」라는 말이 있으면 열거로 정한다","mis":"K5-1-u4-X12"},{"t":"문단의 개수를 센다","mis":"K5-1-u4-X12"},{"t":"글의 제목 길이를 본다","mis":"K5-1-u4-X03"}],"explanation":["말만 보고 정하지 않아요.","개수는 기준이 아니에요.","바꾸어 보는 것이 확인 방법이에요."]}'::jsonb),
('g5_1_kor_u4_L02_challenge#3','kor',5,1,'u4','L02','g5_1_kor_u4_L02_challenge','lesson_challenge','K5-1-u4-C12',3,'mc','auto','「종이 모자 접기」는 어떤 구조이고, 그렇게 볼 수 있는 까닭은 무엇인가요?',ARRAY['K5-1-u4-X12','K5-1-u4-X10','K5-1-u4-X08']::text[],false,'{"seq":3,"concept":"K5-1-u4-C12","difficulty":3,"kind":"mc","stem":"「종이 모자 접기」는 어떤 구조이고, 그렇게 볼 수 있는 까닭은 무엇인가요?","options":[{"t":"순서 구조 — 첫째와 둘째를 바꾸면 접기가 이상해진다","correct":true},{"t":"열거 구조 — 첫째 · 둘째 · 셋째가 있기 때문이다","mis":"K5-1-u4-X12"},{"t":"비교와 대조 구조 — 두 가지를 견주었기 때문이다","mis":"K5-1-u4-X10"},{"t":"열거 구조 — 차례를 바꾸어도 똑같이 접힌다","mis":"K5-1-u4-X08"}],"explanation":["말만 보면 안 돼요.","견주는 내용이 없어요.","접는 차례가 정해져 있어요."],"asset":{"type":"passage","lines":["첫째, 네모난 종이를 반으로 접었다가 편다.","둘째, 위쪽 두 귀퉁이를 가운데 접힌 선에 맞춰 접는다.","셋째, 아래쪽 띠를 앞뒤로 한 번씩 올려 접는다.","넷째, 양쪽을 벌려 모자 모양을 잡는다."],"title":"친구가 쓴 「종이 모자 접기」"}}'::jsonb),
('g5_1_kor_u4_L02_challenge#4','kor',5,1,'u4','L02','g5_1_kor_u4_L02_challenge','lesson_challenge','K5-1-u4-C13',3,'mc','auto','「가야금」을 대상으로 순서 구조의 글을 쓴다면 무엇을 말하려는 글일까요?',ARRAY['K5-1-u4-X13','K5-1-u4-X38']::text[],false,'{"seq":4,"concept":"K5-1-u4-C13","difficulty":3,"kind":"mc","stem":"「가야금」을 대상으로 순서 구조의 글을 쓴다면 무엇을 말하려는 글일까요?","options":[{"t":"가야금을 만드는 과정","correct":true},{"t":"가야금의 여러 특징","mis":"K5-1-u4-X13"},{"t":"가야금과 거문고의 차이","mis":"K5-1-u4-X13"},{"t":"가야금 소리를 들은 내 느낌","mis":"K5-1-u4-X38"}],"explanation":["특징을 늘어놓으면 열거예요.","견주면 비교와 대조예요.","과정은 차례가 있어요."]}'::jsonb),
('g5_1_kor_u4_L02_challenge#5','kor',5,1,'u4','L02','g5_1_kor_u4_L02_challenge','lesson_challenge','K5-1-u4-C13',3,'error','auto','구조를 고르는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u4-X13','K5-1-u4-X10']::text[],false,'{"seq":5,"concept":"K5-1-u4-C13","difficulty":3,"kind":"error","stem":"구조를 고르는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「대상이 정해지면 구조도 하나로 정해져.」","correct":true,"mis_target":"K5-1-u4-X13"},{"t":"「무엇을 말하려는지에 따라 구조가 달라져.」","mis":"K5-1-u4-X13"},{"t":"「같은 대상도 다른 것과 견주면 비교와 대조 구조가 돼.」","mis":"K5-1-u4-X10"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","구조는 대상이 아니라 말하려는 내용이 정해요."]}'::jsonb),
('g5_1_kor_u4_L02_challenge#6','kor',5,1,'u4','L02','g5_1_kor_u4_L02_challenge','lesson_challenge','K5-1-u4-C11',3,'mc','auto','「가야금과 거문고」의 ㉯와 ㉰에서 차이점을 드러내는 말은 어느 것인가요?',ARRAY['K5-1-u4-X11']::text[],false,'{"seq":6,"concept":"K5-1-u4-C11","difficulty":3,"kind":"mc","stem":"「가야금과 거문고」의 ㉯와 ㉰에서 차이점을 드러내는 말은 어느 것인가요?","options":[{"t":"반면","correct":true},{"t":"모두","mis":"K5-1-u4-X11"},{"t":"먼저","mis":"K5-1-u4-X11"},{"t":"첫째","mis":"K5-1-u4-X11"}],"explanation":["「모두」는 같은 점을 말해요.","「먼저」는 차례를 밝혀요.","「반면」이 다른 점을 이어 줘요."],"asset":{"type":"passage","lines":["㉮ 가야금과 거문고는 모두 긴 나무 몸통에 명주실 줄을 얹어 만들고,","　 무릎에 놓고 연주한다는 공통점이 있다.","㉯ 가야금은 줄이 열두 개이고 줄마다 안족이라는 받침이 놓여 있다.","　 반면 거문고는 줄이 여섯 개이고 몸통에 괘라는 턱이 붙어 있다.","㉰ 가야금은 손가락으로 줄을 뜯거나 튕긴다. 반면 거문고는","　 술대라는 막대로 줄을 치거나 밀어 소리를 낸다.","㉱ 그래서 가야금 소리는 맑고 부드럽고, 거문고 소리는 굵고 단단하다."],"title":"「가야금과 거문고」"}}'::jsonb),
('g5_1_kor_u4_L02_challenge#7','kor',5,1,'u4','L02','g5_1_kor_u4_L02_challenge','lesson_challenge','K5-1-u4-C14',3,'mc','auto','글을 읽다가 「반면」이 나왔을 때 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u4-X11','K5-1-u4-X14']::text[],false,'{"seq":7,"concept":"K5-1-u4-C14","difficulty":3,"kind":"mc","stem":"글을 읽다가 「반면」이 나왔을 때 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"앞 내용과 다른 점이 이어서 나올 것이다","correct":true},{"t":"다음 단계가 나올 것이다","mis":"K5-1-u4-X11"},{"t":"글이 곧 끝날 것이다","mis":"K5-1-u4-X14"},{"t":"같은 점이 이어서 나올 것이다","mis":"K5-1-u4-X11"}],"explanation":["단계는 「다음으로」예요.","끝을 알리는 말이 아니에요.","다른 점을 짐작하며 읽어요."]}'::jsonb),
('g5_1_kor_u4_L02_challenge#8','kor',5,1,'u4','L02','g5_1_kor_u4_L02_challenge','lesson_challenge','K5-1-u4-C10',4,'essay','teacher','열거 · 순서 · 비교와 대조 구조가 각각 무엇을 설명할 때 쓰이는지 쓰고, 「사물놀이의 네 악기」 · 「우유갑으로 연필꽂이 만들기」 · 「가야금과 거문고」를 예로 드세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u4-C10","difficulty":4,"kind":"essay","stem":"열거 · 순서 · 비교와 대조 구조가 각각 무엇을 설명할 때 쓰이는지 쓰고, 「사물놀이의 네 악기」 · 「우유갑으로 연필꽂이 만들기」 · 「가야금과 거문고」를 예로 드세요.","answer_guide":{"answer":"예: 열거 구조는 대상의 여러 특징을 항목별로 나열할 때 쓴다. 「사물놀이의 네 악기」는 네 악기의 특징을 하나씩 늘어놓았다. 순서 구조는 방법이나 절차를 차례대로 알려 줄 때 쓴다. 「우유갑으로 연필꽂이 만들기」는 만드는 단계를 차례로 썼다. 비교와 대조 구조는 두 대상의 공통점과 차이점을 견줄 때 쓴다. 「가야금과 거문고」는 두 악기의 같은 점과 다른 점을 찾아 썼다.","scoring_points":["세 구조의 쓰임을 모두 썼는가","세 글을 알맞은 구조와 이었는가","구조마다 무엇을 보여 주는지 밝혔는가"]},"explanation":["항목 · 단계 · 견주기를 떠올려요.","글마다 무엇을 했나요?","세 가지를 모두 써요."]}'::jsonb),
('g5_1_kor_u4_L02_challenge#9','kor',5,1,'u4','L02','g5_1_kor_u4_L02_challenge','lesson_challenge','K5-1-u4-C12',4,'essay','teacher','「첫째 · 둘째 · 셋째」가 열거 구조에도 순서 구조에도 쓰인다는 것을 예를 들어 설명하고, 어느 구조인지 확인하는 방법을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u4-C12","difficulty":4,"kind":"essay","stem":"「첫째 · 둘째 · 셋째」가 열거 구조에도 순서 구조에도 쓰인다는 것을 예를 들어 설명하고, 어느 구조인지 확인하는 방법을 쓰세요.","answer_guide":{"answer":"예: 「첫째, 꽹과리는… 둘째, 징은…」은 첫째와 둘째를 바꾸어도 글이 그대로이므로 열거 구조이다. 「첫째, 종이를 반으로 접는다. 둘째, 귀퉁이를 접는다.」는 바꾸면 접는 방법이 이상해지므로 순서 구조이다. 그러므로 말만 보지 말고 첫째와 둘째의 내용을 바꾸어 보아 확인한다.","scoring_points":["열거의 예를 들었는가","순서의 예를 들었는가","내용을 바꾸어 보는 확인 방법을 썼는가"]},"explanation":["바꾸어도 되는 글을 떠올려요.","바꾸면 안 되는 글을 떠올려요.","확인 방법을 써요."]}'::jsonb),
('g5_1_kor_u4_L02_challenge#10','kor',5,1,'u4','L02','g5_1_kor_u4_L02_challenge','lesson_challenge','K5-1-u4-C13',4,'essay','teacher','「줄넘기」를 대상으로 열거 · 순서 · 비교와 대조 구조의 글을 쓴다면 각각 무엇을 말하는 글이 될지 쓰고, 구조를 정하는 것이 무엇인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u4-C13","difficulty":4,"kind":"essay","stem":"「줄넘기」를 대상으로 열거 · 순서 · 비교와 대조 구조의 글을 쓴다면 각각 무엇을 말하는 글이 될지 쓰고, 구조를 정하는 것이 무엇인지 쓰세요.","answer_guide":{"answer":"예: 열거 구조라면 줄넘기의 여러 가지 넘는 방법을 소개한다. 순서 구조라면 줄넘기 이단 뛰기를 익히는 단계를 차례대로 알려 준다. 비교와 대조 구조라면 줄넘기와 긴 줄넘기의 같은 점과 다른 점을 견준다. 같은 대상이라도 무엇을 말하려는지가 구조를 정한다.","scoring_points":["열거로 쓸 내용을 썼는가","순서와 비교와 대조로 쓸 내용을 썼는가","구조를 정하는 것이 말하려는 내용이라고 썼는가"]},"explanation":["여러 방법을 소개하면?","익히는 차례는? 견주기는?","대상보다 말하려는 것이에요."]}'::jsonb),
('g5_1_kor_u4_L04_basic#1','kor',5,1,'u4','L04','g5_1_kor_u4_L04_basic','lesson_basic','K5-1-u4-C15',1,'mc','auto','문단의 이야기를 대표하는 문장을 무엇이라고 하나요?',ARRAY['K5-1-u4-X15']::text[],false,'{"seq":1,"concept":"K5-1-u4-C15","difficulty":1,"kind":"mc","stem":"문단의 이야기를 대표하는 문장을 무엇이라고 하나요?","options":[{"t":"중심 문장","correct":true},{"t":"뒷받침 문장","mis":"K5-1-u4-X15"},{"t":"제목","mis":"K5-1-u4-X15"},{"t":"끝 문장","mis":"K5-1-u4-X15"}],"explanation":["풀어 주는 문장이에요.","글 전체의 이름이에요.","대표하는 문장이 중심 문장이에요."]}'::jsonb),
('g5_1_kor_u4_L04_basic#2','kor',5,1,'u4','L04','g5_1_kor_u4_L04_basic','lesson_basic','K5-1-u4-C15',1,'mc','auto','이 문단의 중심 문장은 어느 것인가요?',ARRAY['K5-1-u4-X16','K5-1-u4-X15']::text[],false,'{"seq":2,"concept":"K5-1-u4-C15","difficulty":1,"kind":"mc","stem":"이 문단의 중심 문장은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"K5-1-u4-X16"},{"t":"㉰","mis":"K5-1-u4-X16"},{"t":"세 문장 모두","mis":"K5-1-u4-X15"}],"explanation":["㉮를 풀어 주는 문장이에요.","㉮의 까닭을 대는 문장이에요.","나머지 문장이 ㉮를 풀어 줘요."],"asset":{"type":"passage","lines":["㉮ 장구는 양쪽 가죽의 소리가 달라 잔가락을 넣는다.","㉯ 한쪽은 두껍고 다른 쪽은 얇다.","㉰ 그래서 손과 채로 양쪽을 번갈아 치면 소리의 높낮이가 달라진다."],"title":"한 문단"}}'::jsonb),
('g5_1_kor_u4_L04_basic#3','kor',5,1,'u4','L04','g5_1_kor_u4_L04_basic','lesson_basic','K5-1-u4-C18',1,'ox','auto','순서 구조로 정리할 때는 단계의 차례를 바꾸어도 돼요.',ARRAY['K5-1-u4-X18']::text[],false,'{"seq":3,"concept":"K5-1-u4-C18","difficulty":1,"kind":"ox","stem":"순서 구조로 정리할 때는 단계의 차례를 바꾸어도 돼요.","answer":"X","reason_options":[{"t":"단계가 곧 내용이라 차례를 바꾸면 방법이 달라지기 때문에","correct":true},{"t":"내용만 다 들어 있으면 차례는 상관없기 때문에","mis":"K5-1-u4-X18"}],"mis":"K5-1-u4-X18","explanation":["차례가 곧 방법이에요.","바꾸면 엉뚱한 방법이 돼요.","단계의 차례를 지켜요."]}'::jsonb),
('g5_1_kor_u4_L04_basic#4','kor',5,1,'u4','L04','g5_1_kor_u4_L04_basic','lesson_basic','K5-1-u4-C21',1,'mc','auto','구조에 맞는 틀에 중심 내용을 정리할 때 알맞은 방법은 어느 것인가요?',ARRAY['K5-1-u4-X21','K5-1-u4-X04']::text[],false,'{"seq":4,"concept":"K5-1-u4-C21","difficulty":1,"kind":"mc","stem":"구조에 맞는 틀에 중심 내용을 정리할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"중심 낱말로 짧게 적는다","correct":true},{"t":"글을 처음부터 끝까지 옮겨 적는다","mis":"K5-1-u4-X21"},{"t":"뒷받침 문장까지 빠짐없이 적는다","mis":"K5-1-u4-X21"},{"t":"떠오르는 대로 아무 낱말이나 적는다","mis":"K5-1-u4-X04"}],"explanation":["옮기면 한눈에 안 들어와요.","중심 내용만 남겨요.","중심 낱말로 간단히 적어요."]}'::jsonb),
('g5_1_kor_u4_L04_basic#5','kor',5,1,'u4','L04','g5_1_kor_u4_L04_basic','lesson_basic','K5-1-u4-C17',2,'mc','auto','「사물놀이의 네 악기」를 열거 틀에 정리할 때 항목 칸에 넣지 않는 것은 어느 것인가요?',ARRAY['K5-1-u4-X17']::text[],false,'{"seq":5,"concept":"K5-1-u4-C17","difficulty":2,"kind":"mc","stem":"「사물놀이의 네 악기」를 열거 틀에 정리할 때 항목 칸에 넣지 않는 것은 어느 것인가요?","options":[{"t":"이처럼 네 악기가 서로 다른 소리를 맡아 하나의 가락을 이룬다","correct":true},{"t":"꽹과리 — 소리가 높고 연주를 이끈다","mis":"K5-1-u4-X17"},{"t":"징 — 소리가 낮게 퍼지고 큰 마디를 짚는다","mis":"K5-1-u4-X17"},{"t":"북 — 낮은 소리로 흐름을 받쳐 준다","mis":"K5-1-u4-X17"}],"explanation":["꽹과리 항목이에요.","징 항목이에요.","앞의 내용을 묶는 끝 문장이라 항목이 아니에요."],"asset":{"type":"passage","lines":["사물놀이는 네 가지 악기로 연주하는 우리 전통 음악이다.","첫째, 꽹과리는 가장 작고 소리가 높으며 연주를 이끈다.","둘째, 징은 가장 크고 소리가 낮게 퍼지며 큰 마디를 짚어 준다.","셋째, 장구는 양쪽 가죽의 소리가 달라 잔가락을 넣는다.","넷째, 북은 낮고 묵직한 소리로 흐름을 받쳐 준다.","네 악기는 흔히 천둥 · 바람 · 비 · 구름에 빗댄다.","이처럼 네 악기가 서로 다른 소리를 맡아 하나의 가락을 이룬다."],"title":"「사물놀이의 네 악기」"}}'::jsonb),
('g5_1_kor_u4_L04_basic#6','kor',5,1,'u4','L04','g5_1_kor_u4_L04_basic','lesson_basic','K5-1-u4-C18',2,'match','auto','「우유갑으로 연필꽂이 만들기」의 단계와 하는 일을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-1-u4-C18","difficulty":2,"kind":"match","stem":"「우유갑으로 연필꽂이 만들기」의 단계와 하는 일을 이으세요.","pairs":[{"l":"먼저","r":"씻어 말리기"},{"l":"다음으로","r":"윗부분 자르기"},{"l":"그 뒤","r":"자른 곳 마감하기"},{"l":"마지막으로","r":"겉면 꾸미기"}],"mis":"K5-1-u4-X18","explanation":["처음엔 씻어요.","자른 다음 마감해요.","차례를 지켜 이어요."],"asset":{"type":"passage","lines":["다 마신 우유갑도 조금만 손보면 쓸모 있는 물건이 된다.","연필꽂이를 만드는 방법을 알아보자.","먼저, 우유갑을 깨끗이 씻어 말린다.","다음으로, 연필 길이를 생각해 윗부분을 반듯하게 자른다.","그 뒤, 자른 곳에 테이프를 둘러 마감한다.","마지막으로, 겉면을 색종이나 천으로 감싸 꾸민다."],"title":"「우유갑으로 연필꽂이 만들기」"}}'::jsonb),
('g5_1_kor_u4_L04_basic#7','kor',5,1,'u4','L04','g5_1_kor_u4_L04_basic','lesson_basic','K5-1-u4-C19',2,'mc','auto','어떤 친구의 차이점 정리에서 잘못된 줄은 어느 것인가요?',ARRAY['K5-1-u4-X19']::text[],false,'{"seq":7,"concept":"K5-1-u4-C19","difficulty":2,"kind":"mc","stem":"어떤 친구의 차이점 정리에서 잘못된 줄은 어느 것인가요?","options":[{"t":"받침 — 가야금: 괘 · 거문고: 안족","correct":true},{"t":"줄 — 가야금: 열두 개 · 거문고: 여섯 개","mis":"K5-1-u4-X19"},{"t":"연주 — 가야금: 손가락 · 거문고: 술대","mis":"K5-1-u4-X19"},{"t":"세 줄 모두 바르다","mis":"K5-1-u4-X19"}],"explanation":["바르게 정리했어요.","바르게 정리했어요.","안족은 가야금, 괘는 거문고의 것이에요."],"asset":{"type":"passage","lines":["줄 — 가야금: 열두 개 · 거문고: 여섯 개","받침 — 가야금: 괘 · 거문고: 안족","연주 — 가야금: 손가락 · 거문고: 술대"],"title":"어떤 친구의 차이점 정리"}}'::jsonb),
('g5_1_kor_u4_L04_basic#8','kor',5,1,'u4','L04','g5_1_kor_u4_L04_basic','lesson_basic','K5-1-u4-C10',2,'mc','auto','「가야금과 거문고」에서 두 악기의 공통점으로 든 것은 어느 것인가요?',ARRAY['K5-1-u4-X19','K5-1-u4-X10']::text[],false,'{"seq":8,"concept":"K5-1-u4-C10","difficulty":2,"kind":"mc","stem":"「가야금과 거문고」에서 두 악기의 공통점으로 든 것은 어느 것인가요?","options":[{"t":"긴 나무 몸통에 명주실 줄을 얹고 무릎에 놓고 연주한다","correct":true},{"t":"줄이 열두 개이다","mis":"K5-1-u4-X19"},{"t":"술대로 줄을 친다","mis":"K5-1-u4-X19"},{"t":"소리가 굵고 단단하다","mis":"K5-1-u4-X10"}],"explanation":["가야금만의 것이에요.","거문고만의 것이에요.","㉮에 공통점이 있어요."],"asset":{"type":"passage","lines":["㉮ 가야금과 거문고는 모두 긴 나무 몸통에 명주실 줄을 얹어 만들고,","　 무릎에 놓고 연주한다는 공통점이 있다.","㉯ 가야금은 줄이 열두 개이고 줄마다 안족이라는 받침이 놓여 있다.","　 반면 거문고는 줄이 여섯 개이고 몸통에 괘라는 턱이 붙어 있다.","㉰ 가야금은 손가락으로 줄을 뜯거나 튕긴다. 반면 거문고는","　 술대라는 막대로 줄을 치거나 밀어 소리를 낸다.","㉱ 그래서 가야금 소리는 맑고 부드럽고, 거문고 소리는 굵고 단단하다."],"title":"「가야금과 거문고」"}}'::jsonb),
