('g5_1_kor_u4_review_a#4','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C10',1,'mc','auto','단비의 글은 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X10','K5-1-u4-X09','K5-1-u4-X03']::text[],false,'{"seq":4,"concept":"K5-1-u4-C10","difficulty":1,"kind":"mc","stem":"단비의 글은 어떤 구조로 쓴 글인가요?","options":[{"t":"비교와 대조 구조","correct":true},{"t":"열거 구조","mis":"K5-1-u4-X10"},{"t":"순서 구조","mis":"K5-1-u4-X09"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["두 신발을 견주었어요.","만드는 차례가 아니에요.","공통점과 차이점을 찾아 썼어요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb),
('g5_1_kor_u4_review_a#5','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C8',1,'mc','auto','무진이의 글은 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X08','K5-1-u4-X10','K5-1-u4-X03']::text[],false,'{"seq":5,"concept":"K5-1-u4-C8","difficulty":1,"kind":"mc","stem":"무진이의 글은 어떤 구조로 쓴 글인가요?","options":[{"t":"열거 구조","correct":true},{"t":"순서 구조","mis":"K5-1-u4-X08"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X10"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["차례가 아니라 쓰임을 늘어놓았어요.","두 대상을 견주지 않았어요.","부채의 쓰임을 항목별로 나열했어요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb),
('g5_1_kor_u4_review_a#6','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C9',1,'mc','auto','서우의 글은 어떤 구조로 쓴 글인가요?',ARRAY['K5-1-u4-X09','K5-1-u4-X10','K5-1-u4-X03']::text[],false,'{"seq":6,"concept":"K5-1-u4-C9","difficulty":1,"kind":"mc","stem":"서우의 글은 어떤 구조로 쓴 글인가요?","options":[{"t":"순서 구조","correct":true},{"t":"열거 구조","mis":"K5-1-u4-X09"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X10"},{"t":"구조가 없는 글","mis":"K5-1-u4-X03"}],"explanation":["단계가 차례대로 있어요.","두 대상을 견주지 않았어요.","가는 차례를 밝혔어요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb),
