('g5_1_kor_u4_review_a#13','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C31',2,'mc','auto','해담이가 읽을 사람을 생각해 더하면 좋을 것은 어느 것인가요?',ARRAY['K5-1-u4-X31']::text[],false,'{"seq":13,"concept":"K5-1-u4-C31","difficulty":2,"kind":"mc","stem":"해담이가 읽을 사람을 생각해 더하면 좋을 것은 어느 것인가요?","options":[{"t":"「멜빵」 같은 말을 쉽게 풀고 지게 그림을 함께 넣는다","correct":true},{"t":"어려운 말을 더 많이 쓴다","mis":"K5-1-u4-X31"},{"t":"설명을 다 줄여 한 줄만 쓴다","mis":"K5-1-u4-X31"},{"t":"어른이 읽는 글과 똑같이 쓴다","mis":"K5-1-u4-X31"}],"explanation":["동생들이 읽기 어려워요.","너무 줄이면 알 수 없어요.","저학년 동생들을 생각해요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb),
