('g5_1_kor_u4_review_a#15','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C39',2,'mc','auto','「나」의 댓글이 도움이 되는 까닭은 무엇인가요?',ARRAY['K5-1-u4-X39']::text[],false,'{"seq":15,"concept":"K5-1-u4-C39","difficulty":2,"kind":"mc","stem":"「나」의 댓글이 도움이 되는 까닭은 무엇인가요?","options":[{"t":"좋았던 점과 보탤 점을 근거와 함께 말했다","correct":true},{"t":"칭찬만 했다","mis":"K5-1-u4-X39"},{"t":"지적만 했다","mis":"K5-1-u4-X39"},{"t":"자기 글과 견주었다","mis":"K5-1-u4-X39"}],"explanation":["보탤 점도 있어요.","좋았던 점도 있어요.","두 가지를 함께 말했어요."],"asset":{"type":"speech","turns":[{"who":"가","text":"잘 썼네."},{"who":"나","text":"비교와 대조 구조라 두 신발이 한눈에 견주어졌어. 볏짚이 무엇인지 짧게 풀어 주면 동생들도 읽기 쉽겠어."},{"who":"다","text":"내 글이 더 재미있는 것 같아."},{"who":"라","text":"㉱는 빼. 그냥 별로야."}]}}'::jsonb),
('g5_1_kor_u4_review_a#16','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C6',2,'mc','auto','글의 구조를 아는 것이 중요한 까닭이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u4-X06']::text[],false,'{"seq":16,"concept":"K5-1-u4-C6","difficulty":2,"kind":"mc","stem":"글의 구조를 아는 것이 중요한 까닭이 아닌 것은 어느 것인가요?","options":[{"t":"글을 읽지 않아도 내용을 알 수 있다","correct":true},{"t":"글 전체의 내용을 잘 이해할 수 있다","mis":"K5-1-u4-X06"},{"t":"중심 내용을 쉽게 간추릴 수 있다","mis":"K5-1-u4-X06"},{"t":"쓸 내용을 짜임새 있게 정리할 수 있다","mis":"K5-1-u4-X06"}],"explanation":["까닭이 맞아요.","까닭이 맞아요.","글은 읽어야 해요."]}'::jsonb),
('g5_1_kor_u4_review_a#17','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C13',3,'mc','auto','「부채」를 대상으로 순서 구조의 글을 쓴다면 무엇을 말하는 글이 알맞을까요?',ARRAY['K5-1-u4-X13','K5-1-u4-X38']::text[],false,'{"seq":17,"concept":"K5-1-u4-C13","difficulty":3,"kind":"mc","stem":"「부채」를 대상으로 순서 구조의 글을 쓴다면 무엇을 말하는 글이 알맞을까요?","options":[{"t":"부채를 만드는 과정","correct":true},{"t":"부채의 여러 가지 쓰임","mis":"K5-1-u4-X13"},{"t":"부채와 선풍기의 같은 점과 다른 점","mis":"K5-1-u4-X13"},{"t":"부채를 받은 날의 기분","mis":"K5-1-u4-X38"}],"explanation":["그것은 열거예요.","그것은 비교와 대조예요.","과정은 차례가 있어요."]}'::jsonb),
('g5_1_kor_u4_review_a#18','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C12',3,'mc','auto','「어떤 글 ㉠」은 어떤 구조이고, 그렇게 볼 수 있는 까닭은 무엇인가요?',ARRAY['K5-1-u4-X12','K5-1-u4-X10','K5-1-u4-X08']::text[],false,'{"seq":18,"concept":"K5-1-u4-C12","difficulty":3,"kind":"mc","stem":"「어떤 글 ㉠」은 어떤 구조이고, 그렇게 볼 수 있는 까닭은 무엇인가요?","options":[{"t":"순서 구조 — 첫째와 둘째를 바꾸면 차례가 어긋난다","correct":true},{"t":"열거 구조 — 첫째 · 둘째 · 셋째가 있기 때문이다","mis":"K5-1-u4-X12"},{"t":"비교와 대조 구조 — 두 가지를 견주었기 때문이다","mis":"K5-1-u4-X10"},{"t":"열거 구조 — 바꾸어도 글이 그대로이기 때문이다","mis":"K5-1-u4-X08"}],"explanation":["말만 보면 안 돼요.","견주는 내용이 없어요.","싹을 틔워야 모판에 뿌려요."],"asset":{"type":"passage","lines":["첫째, 볍씨를 물에 담가 싹을 틔운다.","둘째, 싹이 튼 볍씨를 모판에 뿌려 기른다.","셋째, 자란 모를 논에 옮겨 심는다."],"title":"어떤 글 ㉠"}}'::jsonb),
('g5_1_kor_u4_review_a#19','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C36',3,'mc','auto','단비가 짚신에 대해 모은 자료 가운데 가장 믿을 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u4-X36']::text[],false,'{"seq":19,"concept":"K5-1-u4-C36","difficulty":3,"kind":"mc","stem":"단비가 짚신에 대해 모은 자료 가운데 가장 믿을 수 있는 것은 어느 것인가요?","options":[{"t":"만든 곳과 올린 때가 밝혀진 박물관 누리집의 짚신 설명","correct":true},{"t":"누가 썼는지 모르는 게시글","mis":"K5-1-u4-X36"},{"t":"친구가 어디서 들었다는 이야기","mis":"K5-1-u4-X36"},{"t":"사진이 예쁘지만 출처가 없는 글","mis":"K5-1-u4-X36"}],"explanation":["누가 썼는지 몰라요.","확인하기 어려워요.","믿을 수 있고 최신인지 알 수 있어요."]}'::jsonb),
('g5_1_kor_u4_review_a#20','kor',5,1,'u4','','g5_1_kor_u4_review_a','unit_review','K5-1-u4-C25',3,'mc','auto','강솔이의 글 ㉰가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X25','K5-1-u4-X10']::text[],false,'{"seq":20,"concept":"K5-1-u4-C25","difficulty":3,"kind":"mc","stem":"강솔이의 글 ㉰가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"작은 습관이 다음 친구를 위한 배려라며 실천을 권한다","correct":true},{"t":"대상을 처음 소개한다","mis":"K5-1-u4-X25"},{"t":"세 방법을 하나씩 늘어놓는다","mis":"K5-1-u4-X25"},{"t":"도서관과 서점을 견준다","mis":"K5-1-u4-X10"}],"explanation":["그것은 처음이에요.","그것은 가운데예요.","끝은 묶고 권해요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb),
