('g5_1_kor_u4_review_b#5','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C11',1,'mc','auto','무진이의 글에서 구조를 짐작하게 하는 말은 어느 것인가요?',ARRAY['K5-1-u4-X11']::text[],false,'{"seq":5,"concept":"K5-1-u4-C11","difficulty":1,"kind":"mc","stem":"무진이의 글에서 구조를 짐작하게 하는 말은 어느 것인가요?","options":[{"t":"첫째 · 둘째 · 셋째 · 넷째","correct":true},{"t":"먼저 · 다음으로","mis":"K5-1-u4-X11"},{"t":"반면 · 다르게","mis":"K5-1-u4-X11"},{"t":"모두 · 공통점","mis":"K5-1-u4-X11"}],"explanation":["글에 없는 말이에요.","글에 없는 말이에요.","항목을 여는 말이 있어요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb),
('g5_1_kor_u4_review_b#6','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C18',1,'mc','auto','서우의 글에서 「그 뒤」에 하는 일은 어느 것인가요?',ARRAY['K5-1-u4-X18','K5-1-u4-X17']::text[],false,'{"seq":6,"concept":"K5-1-u4-C18","difficulty":1,"kind":"mc","stem":"서우의 글에서 「그 뒤」에 하는 일은 어느 것인가요?","options":[{"t":"손잡이를 잡고 위짝을 천천히 돌린다","correct":true},{"t":"콩을 물에 담가 불린다","mis":"K5-1-u4-X18"},{"t":"흘러나온 콩물을 그릇에 받는다","mis":"K5-1-u4-X18"},{"t":"맷돌은 돌 두 짝을 포갠 도구이다","mis":"K5-1-u4-X17"}],"explanation":["그것은 「먼저」예요.","그것은 「마지막으로」예요.","넣은 다음 돌려요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb),
('g5_1_kor_u4_review_b#7','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C25',1,'mc','auto','강솔이의 글에서 가운데 부분은 어느 것인가요?',ARRAY['K5-1-u4-X25']::text[],false,'{"seq":7,"concept":"K5-1-u4-C25","difficulty":1,"kind":"mc","stem":"강솔이의 글에서 가운데 부분은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"K5-1-u4-X25"},{"t":"㉰","mis":"K5-1-u4-X25"},{"t":"㉮ · ㉰","mis":"K5-1-u4-X25"}],"explanation":["처음이에요.","끝이에요.","세 방법이 가운데예요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb),
('g5_1_kor_u4_review_b#8','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C8',1,'mc','auto','해담이의 계획에서 (　　　)에 들어갈 구조로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X13','K5-1-u4-X29']::text[],false,'{"seq":8,"concept":"K5-1-u4-C8","difficulty":1,"kind":"mc","stem":"해담이의 계획에서 (　　　)에 들어갈 구조로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"열거 구조","correct":true},{"t":"순서 구조","mis":"K5-1-u4-X13"},{"t":"비교와 대조 구조","mis":"K5-1-u4-X13"},{"t":"구조는 정하지 않아도 된다","mis":"K5-1-u4-X29"}],"explanation":["쓸 내용이 단계가 아니에요.","견주는 대상이 없어요.","여러 면을 항목별로 소개해요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb),
('g5_1_kor_u4_review_b#9','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C19',2,'mc','auto','단비가 차이점을 정리할 때 바르게 마주 놓은 것은 어느 것인가요?',ARRAY['K5-1-u4-X19']::text[],false,'{"seq":9,"concept":"K5-1-u4-C19","difficulty":2,"kind":"mc","stem":"단비가 차이점을 정리할 때 바르게 마주 놓은 것은 어느 것인가요?","options":[{"t":"재료 — 짚신: 볏짚 · 나막신: 통나무","correct":true},{"t":"재료 — 짚신: 볏짚 · 나막신: 비 오는 날","mis":"K5-1-u4-X19"},{"t":"신는 날 — 짚신: 마른 날 · 나막신: 통나무","mis":"K5-1-u4-X19"},{"t":"무게 — 짚신: 가볍다 · 나막신: 비 오는 날","mis":"K5-1-u4-X19"}],"explanation":["재료와 신는 날을 섞었어요.","신는 날과 재료를 섞었어요.","같은 항목끼리 마주 놓았어요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb),
('g5_1_kor_u4_review_b#10','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C12',2,'mc','auto','무진이의 글에서 첫째와 둘째의 내용을 서로 바꾸어 보면 무엇을 알 수 있나요?',ARRAY['K5-1-u4-X12','K5-1-u4-X10']::text[],false,'{"seq":10,"concept":"K5-1-u4-C12","difficulty":2,"kind":"mc","stem":"무진이의 글에서 첫째와 둘째의 내용을 서로 바꾸어 보면 무엇을 알 수 있나요?","options":[{"t":"글이 그대로이므로 열거 구조임을 확인할 수 있다","correct":true},{"t":"글이 이상해지므로 순서 구조이다","mis":"K5-1-u4-X12"},{"t":"「첫째」가 있으니 바꾸어 볼 필요가 없다","mis":"K5-1-u4-X12"},{"t":"바꾸면 비교와 대조 구조가 된다","mis":"K5-1-u4-X10"}],"explanation":["바꾸어도 글이 그대로예요.","말만 보고 정하지 않아요.","바꾸어도 되면 열거예요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb),
('g5_1_kor_u4_review_b#11','kor',5,1,'u4','','g5_1_kor_u4_review_b','unit_review','K5-1-u4-C12',2,'mc','auto','서우가 「먼저 · 다음으로」 대신 「첫째 · 둘째」로 고쳐 쓴다면 이 글은 어떤 구조인가요?',ARRAY['K5-1-u4-X12','K5-1-u4-X03','K5-1-u4-X10']::text[],false,'{"seq":11,"concept":"K5-1-u4-C12","difficulty":2,"kind":"mc","stem":"서우가 「먼저 · 다음으로」 대신 「첫째 · 둘째」로 고쳐 쓴다면 이 글은 어떤 구조인가요?","options":[{"t":"그래도 순서 구조이다 — 차례를 바꾸면 방법이 달라지기 때문이다","correct":true},{"t":"열거 구조로 바뀐다","mis":"K5-1-u4-X12"},{"t":"구조가 없어진다","mis":"K5-1-u4-X03"},{"t":"비교와 대조 구조가 된다","mis":"K5-1-u4-X10"}],"explanation":["말이 바뀌어도 내용은 단계예요.","구조는 그대로 있어요.","내용의 성격이 구조를 정해요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb),
