('g5_1_kor_u4_review_c#4','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C10',1,'mc','auto','단비의 글에서 두 신발의 공통점으로 든 것은 어느 것인가요?',ARRAY['K5-1-u4-X19']::text[],false,'{"seq":4,"concept":"K5-1-u4-C10","difficulty":1,"kind":"mc","stem":"단비의 글에서 두 신발의 공통점으로 든 것은 어느 것인가요?","options":[{"t":"자연에서 얻은 재료로 만들었다","correct":true},{"t":"굽이 높다","mis":"K5-1-u4-X19"},{"t":"볏짚으로 만들었다","mis":"K5-1-u4-X19"},{"t":"비 오는 날에 신었다","mis":"K5-1-u4-X19"}],"explanation":["나막신만의 것이에요.","짚신만의 것이에요.","㉮에 공통점이 있어요."],"asset":{"type":"passage","lines":["㉮ 짚신과 나막신은 옛날 사람들이 신던 신발로, 둘 다 자연에서","　 얻은 재료로 만들었다는 공통점이 있다.","㉯ 짚신은 볏짚을 꼬아 엮어 만들어 가볍고 발이 편하다. 반면","　 나막신은 통나무를 파서 만들어 무겁지만 물이 스미지 않는다.","㉰ 신는 날도 달랐다. 짚신은 마른 날에 신었고, 나막신은 굽이","　 높아서 비가 오거나 땅이 질척한 날에 신었다.","㉱ 나는 나막신이 또각또각 울리는 소리가 세상에서 제일 좋다."],"title":"단비의 글 초안 「짚신과 나막신」"}}'::jsonb),
('g5_1_kor_u4_review_c#5','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C17',1,'mc','auto','무진이의 글을 열거 틀에 정리할 때 항목 칸에 들어갈 것은 어느 것인가요?',ARRAY['K5-1-u4-X17','K5-1-u4-X38']::text[],false,'{"seq":5,"concept":"K5-1-u4-C17","difficulty":1,"kind":"mc","stem":"무진이의 글을 열거 틀에 정리할 때 항목 칸에 들어갈 것은 어느 것인가요?","options":[{"t":"판소리에서 이야기를 살린다","correct":true},{"t":"부채는 손으로 흔들어 바람을 일으키는 물건이다","mis":"K5-1-u4-X17"},{"t":"부채는 바람을 일으키는 데에만 쓰인 것이 아니다","mis":"K5-1-u4-X17"},{"t":"나는 접는 부채가 더 좋다","mis":"K5-1-u4-X38"}],"explanation":["대상을 소개하는 첫 문장이에요.","앞을 묶는 끝 문장이에요.","셋째 쓰임이에요."],"asset":{"type":"passage","lines":["부채는 손으로 흔들어 바람을 일으키는 물건이다.","첫째, 더운 날 바람을 일으켜 땀을 식혀 준다.","둘째, 햇볕이 따가울 때 얼굴을 가리는 데 쓴다.","셋째, 판소리를 하는 소리꾼은 부채를 펴고 접으며 이야기를 살린다.","넷째, 옛날에는 단옷날 부채를 선물하며 여름을 잘 나기를 빌었다.","이처럼 부채는 바람을 일으키는 데에만 쓰인 것이 아니다."],"title":"무진이의 글 「부채의 여러 가지 쓰임」"}}'::jsonb),
('g5_1_kor_u4_review_c#6','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C11',1,'mc','auto','서우의 글에서 구조를 짐작하게 하는 말은 어느 것인가요?',ARRAY['K5-1-u4-X11','K5-1-u4-X24']::text[],false,'{"seq":6,"concept":"K5-1-u4-C11","difficulty":1,"kind":"mc","stem":"서우의 글에서 구조를 짐작하게 하는 말은 어느 것인가요?","options":[{"t":"먼저 · 다음으로 · 그 뒤 · 마지막으로","correct":true},{"t":"반면 · 다르게","mis":"K5-1-u4-X11"},{"t":"모두 · 공통점","mis":"K5-1-u4-X11"},{"t":"이처럼","mis":"K5-1-u4-X24"}],"explanation":["글에 없는 말이에요.","글에 없는 말이에요.","차례를 밝히는 말이 있어요."],"asset":{"type":"passage","lines":["맷돌은 둥근 돌 두 짝을 포개어 곡식을 가는 도구이다.","먼저, 콩을 물에 담가 하룻밤 불린다.","다음으로, 위짝의 구멍에 불린 콩과 물을 조금씩 넣는다.","그 뒤, 손잡이를 잡고 위짝을 한 방향으로 천천히 돌린다.","마지막으로, 두 짝 사이로 흘러나온 콩물을 그릇에 받는다."],"title":"서우의 글 「맷돌로 콩 가는 차례」"}}'::jsonb),
('g5_1_kor_u4_review_c#7','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C15',1,'mc','auto','강솔이의 글 ㉯에서 첫째 방법의 중심 문장은 어느 것인가요?',ARRAY['K5-1-u4-X16','K5-1-u4-X25']::text[],false,'{"seq":7,"concept":"K5-1-u4-C15","difficulty":1,"kind":"mc","stem":"강솔이의 글 ㉯에서 첫째 방법의 중심 문장은 어느 것인가요?","options":[{"t":"깨끗한 손으로 책장을 넘긴다","correct":true},{"t":"손에 묻은 기름과 먼지는 책장을 누렇게 만든다","mis":"K5-1-u4-X16"},{"t":"학교 도서관 책은 여러 사람이 돌려 가며 읽는다","mis":"K5-1-u4-X25"},{"t":"오늘 빌린 책부터 실천해 보자","mis":"K5-1-u4-X25"}],"explanation":["까닭을 대는 뒷받침 문장이에요.","처음 부분이에요.","첫째 방법을 대표해요."],"asset":{"type":"passage","lines":["㉮ 학교 도서관 책은 여러 사람이 돌려 가며 읽는다. 책을 오래","　 읽으려면 어떻게 해야 할지 알아보자.","㉯ 첫째, 깨끗한 손으로 책장을 넘긴다. 손에 묻은 기름과 먼지는","　 책장을 누렇게 만든다. 둘째, 읽던 곳은 책장을 접지 말고","　 책갈피를 끼운다. 셋째, 다 읽은 책은 제때 돌려준다.","㉰ 이처럼 책을 아끼는 작은 습관은 다음에 읽을 친구를 위한","　 배려이다. 오늘 빌린 책부터 실천해 보자."],"title":"강솔이의 학급 신문 글 「도서관 책을 오래 읽는 방법」"}}'::jsonb),
('g5_1_kor_u4_review_c#8','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C41',1,'mc','auto','해담네 반 모음집의 큰 주제 「옛 물건 이야기」가 알맞은 까닭은 무엇인가요?',ARRAY['K5-1-u4-X41','K5-1-u4-X43']::text[],false,'{"seq":8,"concept":"K5-1-u4-C41","difficulty":1,"kind":"mc","stem":"해담네 반 모음집의 큰 주제 「옛 물건 이야기」가 알맞은 까닭은 무엇인가요?","options":[{"t":"여러 친구가 저마다 다른 옛 물건을 골라 나누어 쓸 수 있다","correct":true},{"t":"한 사람만 아는 이야기라서","mis":"K5-1-u4-X41"},{"t":"모두 같은 물건을 써야 해서","mis":"K5-1-u4-X43"},{"t":"자료를 찾을 수 없어서","mis":"K5-1-u4-X41"}],"explanation":["여럿이 쓸 수 있어요.","물건은 저마다 골라요.","자료를 찾을 수 있어요."],"asset":{"type":"speech","turns":[{"who":"해담","text":"우리 반 모음집의 큰 주제는 「옛 물건 이야기」로 정했어. 이제 무엇을 함께 정할까?"},{"who":"무진","text":"모두 똑같이 비교와 대조 구조로 쓰자. 그래야 한 권처럼 보여."},{"who":"단비","text":"구조는 각자 대상에 맞게 고르고, 제목 다는 방식이랑 분량을 맞추자."},{"who":"서우","text":"머리말에는 왜 옛 물건을 모았는지 쓰고, 글 제목과 쪽수로 차례도 만들자."}]}}'::jsonb),
