('g5_1_kor_u4_review_c#13','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C29',2,'mc','auto','해담이의 계획을 정한 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u4-X29']::text[],false,'{"seq":13,"concept":"K5-1-u4-C29","difficulty":2,"kind":"mc","stem":"해담이의 계획을 정한 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"목적 → 읽을 사람 → 대상 → 구조","correct":true},{"t":"구조 → 대상 → 목적 → 읽을 사람","mis":"K5-1-u4-X29"},{"t":"대상 → 구조 → 읽을 사람 → 목적","mis":"K5-1-u4-X29"},{"t":"읽을 사람만 정하면 된다","mis":"K5-1-u4-X29"}],"explanation":["구조는 맨 나중이에요.","목적부터 정해요.","네 가지를 차례대로 정해요."],"asset":{"type":"passage","lines":["목적 — 옛 물건이 생활에서 어떻게 쓰였는지 알리기","읽을 사람 — 학교 축제에서 모음집을 볼 저학년 동생들","대상 — 지게(민속 마을 체험에서 직접 져 본 적이 있음)","쓸 내용 — 생김새 · 짐을 지는 방법 · 오늘날 볼 수 있는 곳","구조 — (　　　　)"],"title":"해담이의 글 계획"}}'::jsonb),
('g5_1_kor_u4_review_c#14','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C42',2,'mc','auto','큰 주제를 정한 해담네 반이 다음에 할 일은 어느 것인가요?',ARRAY['K5-1-u4-X42']::text[],false,'{"seq":14,"concept":"K5-1-u4-C42","difficulty":2,"kind":"mc","stem":"큰 주제를 정한 해담네 반이 다음에 할 일은 어느 것인가요?","options":[{"t":"각자 설명할 옛 물건을 고른다","correct":true},{"t":"바로 모음집으로 묶는다","mis":"K5-1-u4-X42"},{"t":"표지부터 꾸민다","mis":"K5-1-u4-X42"},{"t":"주제를 다시 정한다","mis":"K5-1-u4-X42"}],"explanation":["글을 쓰기 전이에요.","묶는 일은 나중이에요.","주제 다음은 대상이에요."],"asset":{"type":"speech","turns":[{"who":"해담","text":"우리 반 모음집의 큰 주제는 「옛 물건 이야기」로 정했어. 이제 무엇을 함께 정할까?"},{"who":"무진","text":"모두 똑같이 비교와 대조 구조로 쓰자. 그래야 한 권처럼 보여."},{"who":"단비","text":"구조는 각자 대상에 맞게 고르고, 제목 다는 방식이랑 분량을 맞추자."},{"who":"서우","text":"머리말에는 왜 옛 물건을 모았는지 쓰고, 글 제목과 쪽수로 차례도 만들자."}]}}'::jsonb),
('g5_1_kor_u4_review_c#15','kor',5,1,'u4','','g5_1_kor_u4_review_c','unit_review','K5-1-u4-C40',2,'mc','auto','쓰기 과정을 점검한다는 것은 무엇을 돌아보는 것인가요?',ARRAY['K5-1-u4-X40']::text[],false,'{"seq":15,"concept":"K5-1-u4-C40","difficulty":2,"kind":"mc","stem":"쓰기 과정을 점검한다는 것은 무엇을 돌아보는 것인가요?","options":[{"t":"자료를 모으고 구조를 정해 끝까지 쓰고 다듬는 과정 전체","correct":true},{"t":"다 쓴 글의 길이만","mis":"K5-1-u4-X40"},{"t":"글자를 쓴 빠르기만","mis":"K5-1-u4-X40"},{"t":"맞춤법만","mis":"K5-1-u4-X40"}],"explanation":["결과만 보는 것이 아니에요.","빠르기는 기준이 아니에요.","과정 전체를 돌아봐요."]}'::jsonb),
